quests[3903] = { id = 3903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milly Geltmark", description = "Ihr habt Euch als verlässlich erwiesen, {name}. Verlässlich und ohne Angst, Euch auch mal die Hände schmutzig zu machen, wie?\n\nTja, eine Freundin von mir, Milly Geltmark, hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Ich bin mir sicher, sie könnte Eure Hilfe gut gebrauchen.", sourceObjective = "Sprecht mit Milly Geltmark.", completion = "Ach, Deputy Willem hat Euch also gesagt, Ihr sollt mit mir reden, ja? Er ist ein tapferer Kerl und immer bereit, mir zu helfen, aber seine Pflichten halten ihn in der Abtei von Nordhain fest und ich fürchte, das Problem, das ich heute habe, ist etwas zu groß für ihn.\n\nVielleicht könnt Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[3904] = { id = 3904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Millys Ernte", description = "Eine Bande von Briganten, die Defias, sind in die Weinberge von Nordhain eingedrungen, als ich gerade bei der Weinlese war! Ich habe es den Wachen von Nordhain gemeldet und sie haben mir auch versprochen, dass sie sich darum kümmern würden, aber... Ich habe Angst um meine Traubenernte! Selbst wenn die Defias sie nicht stehlen, befürchte ich, dass unsere Wachen beim Vertreiben der Rohlinge alles zertrampeln.\n\nBitte, Ihr müsst mir helfen! Die meisten Trauben sind schon in Eimern gesammelt, aber ich habe sie in den Weinbergen im Südosten zurückgelassen.\n\nBringt mir diese Kübel! Rettet meine Ernte!", sourceObjective = "Bringt 8 Kisten mit Millys Ernte zu Milly Geltmark in der Nähe der Abtei von Nordhain.", progress = "Habt Ihr meine Ernte, {name}?", completion = "Oh, danke, {name}! Ihr habt meine Ernte gerettet! Und ich hoffe, Ihr habt einigen von diesen Defias gezeigt, dass sie hier nicht so einfach Ärger machen können.\n\nWir sind zur Zeit zwar knapp an Wachen, aber glücklicherweise haben wir Helden wie Euch, die uns beschützen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3905] = { id = 3905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traubenliste", description = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.\n\nIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.", sourceObjective = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.", progress = "Ihr seht so frohgemut aus! Kommt! Setzt Euch und trinkt etwas!", completion = "Dann zeigt mal her...\n\nMeine Güte! Millys Trauben sind gerettet! Als sie mir erzählte, dass Briganten ihren Weinberg überfallen haben, wäre ich fast verzweifelt, doch ich habe den Glauben an das Licht nicht verloren!\n\nUnd dank Eures Heldenmutes haben wir jetzt Trauben, um neuen Wein herstellen zu können! Möge das Licht Euch segnen und über Euch wachen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[3906] = { id = 3906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmonie der Flamme", description = "Die Ältesten haben eine Störung der Elemente gespürt. Die Dunkeleisenzwerge haben einen üblen Geist in unsere Welt beschworen, durch den unser Land von einer ewigen Dürre heimgesucht werden könnte. Die Disharmonie der Flamme muss untersucht werden.\n\nBegebt Euch zum Schwarzfels und dann durch die Flammenschlucht in den Steinbruch. Dort werdet Ihr diesen Herrn des Feuers finden: Übermeister Pyron.\n\nMacht der Störung ein Ende und kehrt dann zu mir zurück.", sourceObjective = "Reist zum Steinbruch am Schwarzfels und tötet Übermeister Pyron. Kehrt zu Donnerherz zurück, sobald Ihr den Auftrag erledigt habt.", progress = "Die Elemente befinden sich noch immer in einem Zustand der Unordnung, {name}.", completion = "Das kann nicht sein... es darf nicht sein. Die Vernichtung Pyrons hat lediglich einen Schleier gelüftet. In den Tiefen von Blackrock befindet sich eine noch weit heimtückischere Quelle der Verderbnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[3907] = { id = 3907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmonie des Feuers", description = "Ich kann die Verderbtheit in der Luft, die Euch umgibt, riechen, {name}. Es gibt einen anderen, versteckt in den Tiefen des Schwarzfels, der diese Verderbtheit kontrolliert.\n\nDer Wind und die Erde schreien seinen Namen hinaus: Lord Incendius. Doch irgendjemand...irgendetwas...gebietet über dieses Wesen. Er ist nichts weiter als ein Abgesandter.\n\nSucht ihn und findet heraus, wo sich sein Meister versteckt hält. Kehrt zu mir zurück, sobald Ihr diese Information gesammelt habt.", sourceObjective = "Betretet die Schwarzfelstiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Donnerherz.", progress = "Bald schon werden die Flammen dieses Land überwältigen. Sputet Euch, {name}!", completion = "<Thunderheart umklammert die Schrifttafel von Kurniya.>\n\nRagnaros... hier...\n\nDie Ältesten hatten Recht, die vom Blackrock ausgehende Verderbnis zu fürchten. Ein General der Alten Götter! IN UNSERER WELT! Wir müssen unsere Position hier in Kargath völlig neu überdenken. Wir müssen entscheiden, ob wir bleiben und kämpfen oder ob wir aus Furcht vor einer neuen Teilung flüchten.\n\nHütet Euch vor jeder weiteren Erforschung des Blackrocks, {name}. Ein Übel, das viel größer ist als alles, was in dieser Welt existiert, haust dort unten in den feurigen Tiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3908] = { id = 3908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist für jeden ein Geheimnis", description = "Seht, ich habe keine Ahnung, wie ich hierher kam. Niemand weiß das - niemand versteht es! Ich kann mich einfach an nichts erinnern...\n\nAber diese Gegenstände, die Ihr mir gebracht habt... Ich erinnere mich an etwas.\n\nMein Schwert. Ich soll es irgendwie stärken, aber ich weiß beim besten Willen nicht, warum. Es tut mir leid, dass ich Euch nicht mehr sagen kann, aber ich kann mich einfach nicht erinnern!\n\nNa, egal, ich weiß aber, wo Ihr es hinbringen könnt: zu Donova Schneeweh in Winterquell. Ihr findet sie bei den Thermalquellen. Sie kann das Schwert an den Teichen dort aushärten.", sourceObjective = "Bringt Linkens Schwert zu Donova Schneeweh in Winterquell.", progress = "Sieh an... Hat Linken mir also doch endlich sein Schwert geschickt.", completion = "Aber natürlich kann ich dieses Schwert aushärten. Und während ich arbeite, könnt Ihr mir erklären, warum Linken so lange gebraucht hat, um mir das Schwert zukommen zu lassen. Normalerweise ist er nicht so vergesslich...", sourceObjectiveStatus = "unverified-source-field" }
quests[3909] = { id = 3909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Videre-Elixier", description = "Was sagt Ihr da? Linken... HAT ES VERGESSEN?\n\nAh, verstehe... Hat sein Gedächtnis verloren...\n\nNa gut, hier ist sein Schwert. Es ist aber noch nicht fertig. Ich habe von jemandem gehört, der es fertig stellen kann, aber... tja, es könnte etwas schwierig werden, mit ihm zu reden.\n\nHört mal, ich weiß jemanden, der Euch bestimmt helfen kann. Ich kann Euch jetzt nicht alles erklären, das würde zu lange dauern, aber Ihr müsst Euch irgendwie ein Videre-Elixier beschaffen. Der Einzige, von dem ich weiß, dass er Euch dabei helfen kann, ist Gregan Hopfenspei. Er ist ziemlich schwer aufzuspüren, aber zuletzt hatte er ein Lager in der Wildnis von Feralas.", sourceObjective = "Sucht nach Gregan Hopfenspei im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Schneeweh nach Winterquell zurück.", progress = "Schon zurück?", completion = "Eine Phiole davon brauche ich, um sicherzugehen, dass es wirklich das richtige Elixier ist... Ja... Genau das wollte ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[3911] = { id = 3911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Element", description = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, {name}.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hin gemurmelt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3912] = { id = 3912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Grab", description = "Durch dieses Elixier könnt Ihr mit jemandem sprechen, den Ihr normalerweise nicht einmal sehen würdet...\n\nBringt das Videre-Elixier und Linkens Schwert mit zum Friedhof kurz vor Gadgetzan in Tanaris. Wenn Ihr dort seid, nehmt den Trank zu Euch. Ihr werdet möglicherweise von der Wirkung sehr überrascht sein, aber erschreckt nicht.\n\nGeht in Eurer 'anderen Form' nach Norden, bis Ihr die Berge erreicht. Dort findet Ihr den, mit dem Ihr sprechen müsst, in einer der Felsspalten. Sein Name ist Gaeriyan.\n\nAber vergesst nicht: Nur in dieser Form wird er mit Euch sprechen...", sourceObjective = "Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden.\n\nBereitgestellter Gegenstand:", completion = "Es ist lange her, dass jemand gekommen ist, um mit mir zu sprechen...", sourceObjectiveStatus = "unverified-source-field" }
quests[3913] = { id = 3913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabesstille", description = "Wenn Ihr zum Friedhof zurückkehrt, {name}, findet Ihr dort einen Grabstein... Nicht einfach nur irgendeinen Grabstein... Dieser hebt sich von all den anderen ab. Geheimnisse liegen darin verborgen.\n\nDrückt gegen den Stein, dann erfahrt Ihr von diesen Geheimnissen...", sourceObjective = "Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat.", progress = "Das muss der Grabstein sein, von dem Gaeriyan sprach...", completion = "Ihr drückt fest gegen den Stein und er rutscht zur Seite. Darunter wird eine kleine Vertiefung sichtbar.\n\nAls Ihr Linkens Schwert in die Vertiefung legt, stellt Ihr fest, dass es haargenau hineinpasst...", sourceObjectiveStatus = "unverified-source-field" }
quests[3914] = { id = 3914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linkens Schwert", description = "Ein greller Lichtblitz blendet Euch, dann könnt Ihr das Schwert wieder aufheben. Es hat sich verwandelt!", sourceObjective = "Liefert Linkens überragendes Schwert bei Linken im Krater von Un'Goro ab.", progress = "Oh! An Euch erinnere ich mich! Ihr seid... Nein, sagt es mir nicht!", completion = "Mein Schwert... Es ist vollendet!\n\nWenn ich mich jetzt doch nur noch daran erinnern könnte, warum ich es brauche...\n\nHier, lasst mich Euch wenigstens für Eure Arbeit bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3921] = { id = 3921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenikee Kübelbolz", description = "Ich glaube, ich habe das Samophlang zerbrochen. Das ist schlecht, denn ich habe schon einigen Kollegen aus Undermine davon erzählt, und die waren äußerst fasziniert. Wir müssen einen Weg finden, es zu reparieren!\n\nBringt das zerbrochene Samophlang zu Wenikee Kübelbolz beim Außenposten der Horde, zwischen dem Brachland und dem Eschental. Sie ist sehr schlau und wissbegierig. Wenn Ihr ihr das Samophlang zeigt, dann, wette ich, stürzt sie sich sofort darauf und will es reparieren.", sourceObjective = "Bringt das zerbrochene Samophlang zu Wenikee Kübelbolz.", progress = "Ich bin gerade sehr beschäftigt, {class}. Wenn Ihr also nichts für mich habt, dann solltet Ihr am besten einfach wieder gehen...", completion = "Oh, was haben wir denn hier? Ein Samophlang, sagt Ihr? Was ist ein Samophlang?\n\nAh, jetzt schaut doch nur, es bewegt sich, wenn man es anfasst. Und im Inneren ist das Geräusch eines komplizierten Getriebes. Oh Mann! Ich will das Ding unbedingt reparieren und sehen, was es tut, Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[3922] = { id = 3922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schraubnieten", description = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Schraubnieten mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.\n\nDer nächstgelegene Ort, an dem man sie bekommen kann, ist das Schlickermoor im Osten. Die Leute von der Venture Company bewahren sie normalerweise in ihren Werkzeugkisten auf. Geht ins Schlickermoor und schaut in den Werkzeugkisten nach, die Ihr dort findet. Kommt zu mir zurück, sobald Ihr genug Schraubnieten gesammelt habt.", sourceObjective = "Bringt 15 Schraubnieten zu Wenikee Kübelbolz im Brachland.", progress = "Habt Ihr die Nugget-Patronen, {name}? Ständig muss ich mir dieses Samophlang ansehen - ich kann es gar nicht erwarten, endlich daran herumzubasteln.", completion = "Prima, Ihr habt sie! Jetzt kann ich mich endlich an die Arbeit machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[3923] = { id = 3923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rilli Schmierklump", description = "Tja, das hat schon mal nicht funktioniert. Ich habe an dem Samophlang ein paar zusätzliche Messgeräte angebracht, um seine strukturelle Integrität zu messen, und laut der Anzeige war die Integrität am absoluten Tiefpunkt. Ich könnte natürlich noch ein paar Skalen und vielleicht auch den einen oder anderen Hebel anbringen, aber...ich glaube, das würde alles nur noch schlimmer machen.\n\nIhr solltet das Samophlang zu Rilli Schmierklump bringen. Er hat mal für die Venture Company gearbeitet. Wenn irgendjemand weiß, wie man das Ding reparieren kann, dann Rilli.\n\nIhr findet ihn bei 'Noggs Meistermaschinen' in Orgrimmar, im Tal der Ehre.", sourceObjective = "Bringt das zerbrochene und ramponierte Samophlang nach Orgrimmar zu Rilli Schmierklump.", progress = "Passt auf Euren Kopf auf! Ich will nicht, dass er meiner Arbeit in die Quere kommt!", completion = "Was ist denn das? Aber das ist doch ein Samophlang! Wo habt Ihr das denn her? Habt Ihr etwa in der Anlage der Venture Company im Brachland herumgeschnüffelt?\n\nDann seid Ihr entweder sehr mutig oder sehr dumm.", sourceObjectiveStatus = "unverified-source-field" }
quests[3924] = { id = 3924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlanghandbuch", description = "Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch. Als ich noch für die Venture Company arbeitete, hatte ich einen Konkurrenten, Boss Kupferdraht. Der hat das Geheimnis des Samophlangs gehütet wie seinen Augapfel und immer nur kleine Fitzelchen an Informationen an diejenigen verteilt, denen er traute. Zu dieser kleinen, ausgewählten Gruppe habe ich leider nicht gehört...\n\nBoss Kupferdraht war früher immer in der Felsadermine im Nordosten des Brachlandes. Beschafft Euch das Handbuch von ihm, und falls er irgendjemandem einzelne Seiten davon gegeben hat, dann müsst Ihr diese ebenfalls einsammeln.", sourceObjective = "Bringt das Samophlanghandbuch nach Orgrimmar zu Rilli Schmierklump.", progress = "Habt Ihr das Handbuch?", completion = "Ihr habt das Handbuch! Ich kann es kaum erwarten, es zu lesen und herauszufinden, wie man das Samophlang reparieren kann! Ich habe mit Sputtervale in Ratchet gesprochen - er möchte Euch für Eure Hilfe danken und Euch für Eure Mühe belohnen.\n\nIch möchte Euch ebenfalls danken - und falls es mir gelingt, dieses Ding hier jemals zu reparieren, lasse ich es Euch wissen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[3941] = { id = 3941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe des Gnoms", description = "Ich denke... Ich denke... Ich weiß, dass ich aus irgendeinem wichtigen Grund hergekommen bin...\n\nIch hab da eine Idee, {name}. In der Höhle dort drüben wohnt eine Gnomin namens J.D. Sie war sehr freundlich zu mir, als ich hier ankam. Vielleicht habe ich in meiner Verwirrung ihr gegenüber irgendwas erwähnt.\n\nWarum fragt Ihr sie nicht, ob sie etwas weiß? Oh, aber seid vorsichtig: Sie spielt immer mit diesen verrückten, leuchtenden Kristallen herum, die ich im Krater gesehen habe. Ich habe keine Ahnung, was sie da drinnen treibt.", sourceObjective = "Sucht J.D. Collie in der Höhle in Marschalls Zuflucht auf.", completion = "Bleibt mal einen Moment da, wo Ihr seid... Ich probiere gerade eine neue Kristallkombination aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[3942] = { id = 3942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linkens Andenken", description = "Oh... Linken? Jaaa, der ist echt witzig. Als er hier ankam, murmelte er ständig irgendwelche seltsamen Dinge. Hat wahrscheinlich einen ziemlich heftigen Schlag auf den Kopf bekommen, würde ich mal sagen.\n\nAber etwas, das er gesagt hat, ist bei mir irgendwie hängen geblieben - dass er dabei war, eine Art Totem herzustellen; er sagte, er müsse mit jemandem namens Eridan Blauwind sprechen... an einem Ort namens Teufelswald, glaube ich.\n\nAber ich bezweifle, dass Linken Euch jetzt noch viel darüber sagen kann. Wenn Ihr mehr wissen wollt, solltet Ihr diesen Eridan vielleicht selbst suchen gehen...", sourceObjective = "Sucht Eridan Blauwind im südlichen Teil des Teufelswalds.", completion = "Hallo, {class}. Kann ich Euch irgendwie helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[3961] = { id = 3961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linkens Abenteuer", description = "Wenn man sich überlegt, dass Linken nur hergekommen ist, um uns von Sturmflamme zu befreien... Er scheint so gar nichts Außergewöhnliches an sich zu haben, aber mir ist aufgefallen, dass er sich überhaupt nicht für meine Experimente oder Geräte interessiert hat, wie das bei den meisten Gnomen sonst der Fall ist. Er muss im Herzen ein echter Krieger sein.\n\nBringt ihm das Totem. Vielleicht hilft ihm das, sich zu erinnern, warum er hergekommen ist.", sourceObjective = "Bringt das Silbertotem von Aquementas zu Linken in Marschalls Zuflucht.", progress = "Ach, hallo, {name}!", completion = "Konnte J. D. Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[3962] = { id = 3962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allein ist es gefährlich", description = "{name}, ich fange endlich an, mich zu erinnern! Ich bin hergekommen, um gegen Sturmflamme zu kämpfen. Ich war auf einer Reise und das hätte der letzte Schritt sein sollen.\n\nAber ich bin kein Held mehr... sondern Ihr. Alles, was Ihr getan habt... Ihr müsst dies jetzt zu Ende bringen, nicht ich.\n\nFindet Sturmflamme und besiegt ihn. Er bewacht ein Artefakt, das die Goldene Flamme genannt wird. Es verleiht mehr Macht als alles, was ich je zuvor gesehen habe, und in den Händen von jemandem, dessen Herz böse ist, ist es äußerst gefährlich.\n\nIhr solltet aber unbedingt Verstärkung mitnehmen - es ist gefährlich, allein zu gehen.", sourceObjective = "Begebt Euch zum Feuersäulengrat südlich von Marschalls Zuflucht.\n\nSucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle.", progress = "Hinter der Aura, die er mit Hilfe der Goldenen Flamme um sich herum erzeugt hat, ist Sturmflamme fast unbesiegbar. Nur Ihr habt die Macht, diese Aura mit dem Silbertotem von Aquementas zu entfernen.", completion = "Ich danke Euch, {name}.\n\nDie Goldene Flamme wird jetzt in meine Heimat zurückgebracht, wo sie beschützt werden wird, damit sie niemals wieder für das Böse eingesetzt werden kann.\n\nDa Ihr so viel für mich getan habt, möchte ich, dass Ihr dies nehmt... Sucht Euch aus, was immer Ihr wollt. Ohne Euch wüsste ich noch immer nicht, wer ich eigentlich bin!", sourceObjectiveStatus = "unverified-source-field" }
quests[3981] = { id = 3981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Gor'shak", description = "Der arme Gargal... er wurde davon völlig überrascht. BUMM! Der tödliche Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt...\n\n<Galamav zieht eine Grimasse.>\n\nAls wir den Pfeil herauszogen, sahen wir, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines Orcs hinter Gittern mit der Unterschrift von Kommandant Gor'shak.\n\nFalls er noch am Leben sein sollte, dort unten in den Tiefen, dann müsst Ihr ihn finden.\n\nEine Falle, sagt Ihr? Ach nee, Dumpfhuf! Deswegen geht ja auch Ihr und nicht wir!", sourceObjective = "Sucht Kommandant Gor'shak in den Schwarzfelstiefen.\n\nIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.", completion = "Wir haben nicht viel Zeit. Hört gut zu, {race}. Was ich Euch zu sagen habe, ist vertraulich und nur für Eure Ohren bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3982] = { id = 3982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los?", description = "Ich wurde unter der Schirmherrschaft von Thrall hierher geschickt. Glaubt Ihr wirklich, diese Clowns könnten mich fangen? Ich habe mich fangen lassen, um so Informationen sammeln zu können.\n\n<Gor'shak flüstert.>\n\nDie Prinzessin von Eisenschmiede wurde von Imperator Thaurissan entführt. Prinzessin Bronzebart befindet sich in dieser Stadt! Ich wette, dem alten Magni ist fast das Herz stehen geblieben, als er diese Neuigkeiten gehört hat.\n\n<Gor'shak lacht.>\n\nPssst! Hört Ihr das? Es kommen Wachen! VERTEIDIGT EUCH!", sourceObjective = "Verteidigt Gor'shak.", progress = "Verteidigt Euch, Dummkopf!", completion = "Das war knapp. Sie wissen jetzt, dass Ihr hier seid... bestimmt kommen bald mehr von ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4001] = { id = 4001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los?", description = "Bisher war meine Kommunikation mit dem Zwerg Kharan in der Zelle auf der anderen Seite der Halle nur sehr eingeschränkt möglich. Doch ich konnte ihn immerhin davon überzeugen, dass ich - oder besser - dass wir ihm nichts Böses wollen.\n\nGeht und redet mit ihm und erfahrt so viel über die Prinzessin und ihre Entführer wie nur möglich. Bringt diese Informationen dann dem Kriegshäuptling.\n\nThrall will nicht, dass der Prinzessin ein Leid geschieht. Er hat irgendeinen großen Plan, und der umfasst auch, dass sie wieder sicher nach Eisenschmiede zurückgebracht wird. Kharan weiß das alles schon...Geht!", sourceObjective = "Sprecht mit Kharan Hammermacht und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebart. Bringt diese Informationen dann zu Thrall nach Orgrimmar.\n\nIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.", progress = "Was führt Euch auf diesen geheiligten Boden?", completion = "Dies ist eine Chance für die Horde, das politische Klima in unserer vom Krieg zerrissenen Welt für immer zu verändern. Hört gut zu, {name}.\n\nEinen Fehlschlag dieser Mission werde ich nicht akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[4002] = { id = 4002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das östliche Königreich", description = "Ihr bringt ganz ausgezeichnete Nachrichten, {name}.\n\nAls Kriegshäuptling ist es meine Aufgabe, das zu tun, was das Beste für die Horde ist. Zu garantieren, dass die nachfolgenden Generationen nicht in einer hoffnungslosen Existenz gefangen sein werden.\n\nJetzt ist uns die einzigartige Chance, die Allianzen der Zukunft zu formen, in den Schoß gefallen. Wenn wir jetzt den Zwergen helfen, könnte dies unsere Beziehungen zum östlichen Königreich enorm verbessern. Und aus genau diesem Grund dürft Ihr nicht versagen!\n\nSeid Ihr bereit?", sourceObjective = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.", completion = "Jetzt könnt Ihr nicht mehr zurück, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4003] = { id = 4003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die königliche Rettung", description = "Der Schlag gegen die Dunkeleisenzwerge wird, wenn er denn erfolgreich verläuft, eine Schockwelle durch ihr ganzes Königreich jagen.\n\nPrinzessin Bronzebart ist unter der Kontrolle von Imperator Thaurissan. Um sie zu befreien, müsst Ihr den Imperator töten. Doch seid gewarnt, denn Eure Aufgabe ist doppelt gefährlich. Zweifellos wird Euch Prinzessin Bronzebart angreifen, solange sie noch der Kontrolle des Imperators unterliegt.\n\nIHR DÜRFT IHR KEIN LEID ZUFÜGEN!", sourceObjective = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebart von seinem bösen Zauber.", completion = "Was habt Ihr getan!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[4004] = { id = 4004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist die Prinzessin gerettet?", description = "Ihr habt meinen Ehemann erschlagen, {race}! Mein Kind wird ohne Vater in diese Welt geboren werden.\n\n<Prinzessin Moira zeigt direkt auf Euch.>\n\nIch versichere Euch, dieses Kind wird der nächste Herrscher des Königreichs von Eisenschmiede sein. Ihr und Eure Art solltet für diese ungerechte Tat bis ans Ende aller Tage gejagt werden.\n\n<Ihr denkt, dass Prinzessin Moira vielleicht unter den Nachwirkungen von Thaurissans Zauber leidet.>\n\nLasst mich in Ruhe, {race}. Ich bin sicher, Euer Kriegshäuptling ist erpicht darauf, vom Ergebnis seiner Einmischung zu erfahren.", sourceObjective = "Kehrt zu Thrall zurück!", completion = "<Thrall ist bestürzt über die Informationen, die Ihr ihm präsentiert habt.>\n\nJetzt dräut eine neue Bedrohung am Horizont. Da Magnis Jahre sich dem Ende neigen, wird der Weg für diesen ungeborenen Dunkeleisenzwerg geöffnet, um Herrscher von Ironforge zu werden.\n\nIhr habt erreicht, worum ich Euch gebeten habe, und dafür sollt Ihr belohnt werden.\n\nVerlasst mich nun, {name}. Ich muss mich mit Sylvanas und Cairne beraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[4005] = { id = 4005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquementas", description = "Nehmt diese Tasche mit Vorräten mit Euch nach Tanaris. Begebt Euch zur Mast- und Schotbucht und sucht dort einen Kreis aus Steinen.\n\nIn der östlichsten Halbinsel liegt das Geheimnis...\n\nLest aus dem Buch von Aquor vor - aber nur innerhalb dieses Kreises - und beschwört das einzige Wesen, das die Gegenstände, die Ihr gesammelt habt, in ein Totem verwandeln kann, mit dem Ihr Sturmflamme bekämpfen könnt.\n\nEs wird Aquementas nicht gefallen, dass Ihr ihn aufweckt, doch vergesst nicht: Ihr müsst unbedingt in dem Kreis bleiben, damit er die Gegenstände transformieren kann.", sourceObjective = "Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.\n\nBenutzt das Buch von Aquor, um Aquementas zu beschwören.\n\nWenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marschalls Zuflucht zurück.", progress = "Ihr seid also zurück, wie? Hmmm... Lasst mich das mal sehen, {name}.", completion = "Sturmflamme, sagt Ihr...\n\nJa, ich weiß, dass sich ein starker Elementar im verkohlten Zentrum des Kraters aufhält. Wir halten uns einfach alle davon fern, denn noch niemand war in der Lage, die mächtige Aura zu durchdringen, die ihn umgibt. Viele schon wurden von den felsigen Pfaden auf den Grund des Kraters hinabgestürzt, als sie versuchten, sich ihm zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4021] = { id = 4021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenangriff!", description = "Die Horde lobt Euch für Eure Erfolge gegen die Kolkar, doch die Kolkar kochen vor Wut. Ich habe Berichte erhalten, denen zufolge ein Kontingent Kolkar ihr Zuhause in Desolace verlassen hat und ins Brachland gezogen ist, um dort Rache zu üben. Den letzten Berichten nach, rücken Sie in diesem Moment von Westen her gegen diese Bunker vor!\n\nStellt Euch den Eindringlingen der Kolkar und bereitet der Bedrohung, die sie für das Brachland darstellen, ein Ende. Tötet sie, bis ihr Anführer, Kriegsherr Krom'zar, erscheint. Besiegt ihn und bringt mir ein Teil seiner Flagge als Beweis.\n\nWir zählen auf Euch, {name}.", sourceObjective = "Bringt ein Teil von Krom'zars Flagge zu Regthar Totenfurt, westlich des Wegekreuzes.", progress = "Habt Ihr die Flagge?", completion = "Ihr habt es geschafft! Ihr habt die Kolkar besiegt!\n\nIch werde dafür sorgen, dass Thrall von Euren Taten hier erfährt, {name}.\n\nSchreitet erhobenen Hauptes dahin. Ihr und die Horde könnt stolz auf Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[4022] = { id = 4022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe der Flamme", description = "Der Klan ist sich Eurer Arbeit in der sengenden Schlucht bewusst.\n\nZeigt sie mir, {race}. Die abgestreifte Drachenhaut, Dummkopf!", sourceObjective = "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Velarok Windklinge erhalten habt.", progress = "<Cyrus' Augen beginnen zu glühen.>", completion = "<Cyrus untersucht die Drachenhaut.>\n\nDamit beweist Ihr, dass Ihr nicht völlig nutzlos seid, sterbliches Wesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4023] = { id = 4023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe der Flamme", description = "Ihr sucht nach dem Klan? Zeigt mir einen Beweis für Eure Nützlichkeit, sterbliches Wesen.", sourceObjective = "Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.\n\nIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid.", progress = "<Cyrus' Augen beginnen zu glühen.>", completion = "<Cyrus untersucht die Drachenhaut.>\n\nDamit beweist Ihr, dass Ihr nicht völlig nutzlos seid, sterbliches Wesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4024] = { id = 4024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe der Flamme", description = "Ich möchte die sengenden Flammen des Feuerberges schmecken. Die flüssigen Feuer des Schwarzfels über mich strömen lassen. Diese Essenz, diese sengende Hitze ist es, nach der ich mich sehne.\n\nIn den Tiefen des Schwarzfels haust Bael'Gar: ein Wesen aus reinstem Feuer, geboren aus den Flammen des Ragnaros. Tötet Bael'Gar und bringt mir aus seinen glimmenden Überresten einen Teil seines inneren Feuers.\n\nVerwendet die Drachenhaut für seine Überreste, um die innere Flamme sicher entnehmen zu können.\n\nSeid erfolgreich und Ihr werdet belohnt.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und tötet Bael'Gar.\n\nIhr wisst lediglich, dass der Riese irgendwo in den Schwarzfelstiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\n\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", progress = "Habt Ihr den Riesen niedergestreckt?", completion = "<Cyrus reißt Euch die feurige Essenz aus der Hand.>\n\nJA!\n\nNehmt Euren Lohn und hebt Euch hinfort! Geht mir unverzüglich aus den Augen!", sourceObjectiveStatus = "unverified-source-field" }
quests[4041] = { id = 4041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Videre-Elixier", progress = "Klar, wenn Ihr mir eine Evowurzel bringt, dann kann ich Euch auch das Videre-Elixier machen.\n\nIch weiß alle möglichen Dinge über Kräuter und Alchimie... Ich könnte Euch Geschichten erzählen... zum Beispiel, wie ich mal Gold aus dem Käse gemacht habe, den ich eigentlich zum Mittagessen... he! Wo wollt Ihr hin?", completion = "Soso, Ihr habt also den alten Miblon reingelegt, wie?" }
quests[4061] = { id = 4061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Maschinen", description = "Wir stießen bereits bei unseren ersten Streifzügen in der sengenden Schlucht auf die Maschinen. Weitere Nachforschungen ergaben, dass sie aus der brennenden Steppe, eventuell auch aus den Schwarzfelstiefen, stammen. Und dafür brauchen wir Euch, {name}.\n\nEure erste Aufgabe besteht darin, Euch in die brennende Steppe zu begeben und dort einige Elementarsplitter von den Felsautomatons und den geringen Felsgeschöpfen der Gegend zu beschaffen. Sobald Ihr eine ausreichende Menge gesammelt habt, kehrt zu mir zurück, dann werde ich herausfinden, woher sie wirklich stammen.", sourceObjective = "Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\n\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.", progress = "Nehmt diese Aufgabe nicht zu leicht, {name}!", completion = "<Theodora legt die Fragmente vor sich hin.>\n\n<Theodora untersucht die Fragmente sorgfältig mit einem riesigen Monokel.>\n\nInteressant. In die strukturelle Basis jedes dieser Fragmente sind... Initialen eingeätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4062] = { id = 4062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Maschinen", description = "G.L.A.\n\nDas sind die Buchstaben, die in die Elementarsplitter eingeprägt sind. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen, die Ihr in der brennenden Steppe zerstört habt, hatten den 'Rang IV'. Ich nehme an, das ist ein eher niedriger Rang.\n\nBringt diese Splitterprobe in das Lager im Osten zu Lotwil Veriatus. Er ist ein Gelehrter und vor allem für seine Arbeit auf dem Gebiet der Elementarforschung bekannt. Vielleicht kann er uns bei unserer Suche helfen.", sourceObjective = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\n\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert.", progress = "Was habt Ihr denn da, {race}?", completion = "<Lotwil erbleicht.>\n\nIch... Ich kenne diese Markierungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4063] = { id = 4063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Maschinen", description = "Das kann doch nicht Argelmach sein... Argelmach wurde vor zehn Jahren getötet. Warum ich das so genau weiß? Weil ich derjenige war, der ihn getötet hat.\n\nEr war ein abscheulicher Zwerg und wild entschlossen, mein Lebenswerk zu verderben und es für seine teuflischen Zwecke zu benutzen. Wie es scheint, finden die Tückischen immer einen Weg, ihrer gerechten Strafe zu entgehen.\n\nWenn dies Argelmachs Werk ist, dann muss er zerstört werden. Ich brauche Proben seiner jüngsten Schöpfungen. Mit den richtigen Proben kann ich vielleicht diesem Aufstand ein Ende machen. Die Schöpfungen bewachen Argelmach in den Schwarzfelstiefen.", sourceObjective = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.", progress = "War er es? War er wirklich am Leben?", completion = "Was ist das? Dieser Kopf besteht nicht aus Fleisch und Blut! Es muss eine Schöpfung der Dunkeleisenzwerge sein: ein Schatten Argelmachs - NOCH EINE Maschine! Ich fürchte, Eure Vernichtung Argelmachs wird nicht von Dauer sein und bald wird eine weitere Kopie seinen Platz einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4081] = { id = 4081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SOFORT TÖTEN: Dunkeleisenzwerge", description = "Auf Befehl von Kriegsherr Bluthauer, Kommandant des Expeditionskorps von Kargath:\n\nAlle Streitkräfte, über die General Zornesschmied in den Schwarzfelstiefen verfügt, müssen ausgelöscht werden.\n\nZornesschmieds Männer sind rücksichtslose Killer und verantwortlich für den Massenmord an der 109. Division des Expeditionskorps von Kargath. Alle Helden, die diesen gefühllosen Bestien gegenübertreten wollen, werden aufgefordert, extreme Vorsicht walten zu lassen.\n\nJede Person, die die erste Kampfreihe von General Zornesschmieds Streitkräften in den Schwarzfelstiefen vernichtet, wird einen Tribut erhalten.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Bluthauer möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", completion = "Dieser erste Schlag sollte Zornesschmied schon ein bisschen die Laune vermiesen. Und jetzt, bewegt Euch, Soldat. Ich muss arbeiten, Schlachten planen, Feinde vernichten!\n\nSchaut Euch die Plakate an, wenn Ihr noch etwas tun wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4082] = { id = 4082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", description = "Auf Befehl von Kriegsherr Bluthauer, Kommandant des Expeditionskorps von Kargath:\n\nDer Leiter der Aufklärungseinheit des KEK, Großmeister Lexlort, kam mit Neuigkeiten über den Verbleib einiger hochrangiger Führungskräfte der Dunkeleisenzwerge zurück. Hinter dem verschlossenen Tor, nahe dem Herzen der Stadt, bilden sie ihre Streitkräfte darin aus, unsere Männer auszulöschen. Geht in die Schwarzfelstiefen und vernichtet sie!\n\nWer diese Mission erfüllt, erhält einen Tribut.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Bluthauer möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", completion = "Ganz zweifellos ist der Zornesschmied jetzt... wütend. Kommt wieder zu mir, wenn Ihr einen dritten Tribut erhaltet, dann können wir mit der Operation 'Tod dem Zornesschmied' beginnen. Ich kann nicht darüber sprechen, was das im Detail bedeutet, aber seid gewiss: jemand wird sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[4083] = { id = 4083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der spektrale Kelch", progress = "Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens.", completion = "Geräuschlos fallen die Edelsteine in die Tiefen des Kelchs..." }
quests[4084] = { id = 4084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silberherz", description = "Ich kenne denjenigen nicht, von dem Ihr sprecht, {name}.\n\nDoch keine Sorge, wenn Euer Freund auf der Suche nach mir war, dann weiß ich, was er von mir wollte.\n\nIm Herzen des Kraters von Un'Goro lebt das Böse in seiner reinsten Form. Dort manifestiert es sich in der Gestalt eines Elementars namens Sturmflamme. Er wird von einer Aura beschützt, die niemand durchdringen kann.\n\nNiemand... außer denen, die über genügend Macht verfügen. Diese Macht kann ich Euch lehren, {name}.\n\nDoch zunächst müsst Ihr mir eine Bitte erfüllen. Beschafft 11 silbrige Klauen und 1 Eisenstammherz von den Kreaturen im Teufelswald und kommt dann zu mir zurück.", sourceObjective = "Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Blauwind im Teufelswald.", progress = "Ich kann Euch mehr über die Macht sagen, die Ihr benötigt, um Sturmflamme zu besiegen, doch zunächst müsst Ihr die Dinge besorgen, die ich brauche.", completion = "Nun gut, {name}. Wie ich sehe, ist es Euch ernst damit, Eurem Freund zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4101] = { id = 4101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Teufelswald säubern", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", sourceObjective = "Bringt 15 Einheiten Blutharz zu Arathandris Silberwolke im Teufelswald.", progress = "Ich weiß, dass der Teufelswald leidet, {name}, denn ich leide mit ihm! Doch ich muss standhaft bleiben; fiele mein Wissen in die falschen Hände, dann wäre dies eine Katastrophe für den ganzen Teufelswald.\n\nBringt mir das Blutharz der getöteten Wucherborkenelementare, dann vertraue ich Euch genug, um mir von Euch dabei helfen zu lassen, ein Mittel gegen die Verderbnis herzustellen.", completion = "Mit dem Blutharz werden wir einen Weg finden, die Verderbnis hier im Teufelswald zu besiegen. Ihr habt mir bewiesen, dass Ihr bereit seid, alles zu tun, was notwendig ist, um dem Zirkel des Cenarius zu helfen. Ich vertraue Euch jetzt.\n\nEs mag Euch seltsam erscheinen, dass Ihr Euch mir gegenüber durch die Tötung der Elementare beweisen musstet, doch die Rettung des Lebens von unzähligen intelligenten Wesen rechtfertigt die Mittel, die wir ergriffen haben. Jetzt können wir uns auf die Bewahrung des Lebens konzentrieren... mit den Salben, die ich herzustellen weiß.\n\n{name}, endlich ist die Zeit gekommen, den Teufelswald zu säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[4102] = { id = 4102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Teufelswald säubern", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", sourceObjective = "Bringt 15 Einheiten Blutharz zu Maybess Flussbrise im Teufelswald.", progress = "Ich weiß, dass der Teufelswald leidet, {name}, denn ich leide mit ihm! Doch ich muss standhaft bleiben; fiele mein Wissen in die falschen Hände, dann wäre dies eine Katastrophe für den ganzen Teufelswald.\n\nBringt mir das Blutharz der getöteten Wucherborkenelementare, dann vertraue ich Euch genug, um mir von Euch dabei helfen zu lassen, ein Mittel gegen die Verderbnis herzustellen.", completion = "Mit dem Blutharz werden wir einen Weg finden, die Verderbnis hier im Teufelswald zu besiegen. Ihr habt mir bewiesen, dass Ihr bereit seid, alles zu tun, was notwendig ist, um dem Zirkel des Cenarius zu helfen. Ich vertraue Euch jetzt.\n\nEs mag Euch seltsam erscheinen, dass Ihr Euch mir gegenüber durch die Tötung der Elementare beweisen musstet, doch die Rettung des Lebens von unzähligen intelligenten Wesen rechtfertigt die Mittel, die wir ergriffen haben. Jetzt können wir uns auf die Bewahrung des Lebens konzentrieren... mit den Salben, die ich herzustellen weiß.\n\n{name}, endlich ist die Zeit gekommen, den Teufelswald zu säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[4103] = { id = 4103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Jagd", progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, {name}! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern." }
quests[4104] = { id = 4104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Bergbau", progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen." }
quests[4105] = { id = 4105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Sammlung", progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, {name}, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, {race}!" }
quests[4106] = { id = 4106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Kürschnerei", progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, {name}!" }
quests[4107] = { id = 4107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Entzauberung", progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, {name}. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!" }
quests[4108] = { id = 4108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Jagd", progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, {name}! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern." }
quests[4109] = { id = 4109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Bergbau", progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen." }
quests[4110] = { id = 4110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Sammlung", progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Läuterungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, {name}, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, {race}!" }
quests[4111] = { id = 4111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Kürschnerei", progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch einige cenarische Pflanzensalben dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, {name}!" }
quests[4112] = { id = 4112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Entzauberung", progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, {name}. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!" }
quests[4113] = { id = 4113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4114] = { id = 4114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4115] = { id = 4115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4116] = { id = 4116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4117] = { id = 4117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Peitscherwurzel", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4118] = { id = 4118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4119] = { id = 4119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Nachtdrache", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4120] = { id = 4120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft der Verderbnis", description = "Als Jäger strebe ich danach, die Stärken nachzuahmen, die ich bei meinen Gegnern sehe. Man kann den Kampf zu seinen Gunsten wenden, indem man einfach seinen Feind gut kennt, {name}.\n\nAn einem Ort namens Teufelswald, nördlich des Eschentals, wurden die Kreaturen durch dämonische Energien verderbt. Die Bären und Wölfe wurden von ihnen verrückt, allerdings glaube ich, dass sie dadurch auch noch stärker geworden sind.\n\nGeht, {name}. Reist zum Teufelswald und tretet den Bestien gegenüber. Erfahrt selbst, ob sie wirklich so stark sind, wie ich glaube.", sourceObjective = "Talo Dornhuf im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt.", completion = "Nach Euren Beschreibungen klingt es, als würden die Kreaturen eine gedankenlose Wildheit an den Tag legen...\n\nBleibt wachsam, {name}! Es könnte in Eurem Interesse sein, mehr über diese Verderbnis zu erfahren. Kennt immer Euren Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[4121] = { id = 4121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Zwickmühle", description = "Glaubt Ihr wirklich, dass Ihr es mit mir als Gefangenem zum vereinbarten Treffpunkt schafft? Habt Ihr wirklich gedacht, Ihr könntet in eine schwer bewachte Festung des Schwarzfelsklans eindringen und völlig unbemerkt ihren wertvollsten Besitz entführen?\n\nMan wird Euch vernichten!", sourceObjective = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Schwarzfels in die sengende Schlucht.\n\nEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen.", progress = "Ich übernehme diesen dreckigen Verräter, {name}.", completion = "Eure Heldentaten sollen nicht unbeachtet bleiben, {name}. Diesen Tribut habt Ihr Euch verdient. Der Kriegsherr wird jetzt mit Euch über die letzte Aufgabe sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4122] = { id = 4122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grark Lorkrub", description = "Ich habe ihn durch die ganze sengende Schlucht, durch den Berg und in die brennende Steppe hinein verfolgt. Der Verräter wurde auf frischer Tat dabei ertappt, wie er den Schwarzfelsorcs wichtige Informationen über die tagtäglichen Vorgänge bei uns lieferte. Ich spreche von Grark Lorkrub.\n\nEr sitzt jetzt in der brennenden Steppe, sicher unter deren Schutz - glaubt er jedenfalls.\n\nNehmt diese Fesseln, {name}. Findet Grark, legt ihm die Fesseln an und führt ihn durch den Schwarzfels. Wenn Ihr das tut, ist ein Tribut Euer.", sourceObjective = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung des Schwarzfelsklans gesehen worden.\n\nWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Schwarzfels in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nBereitgestellter Gegenstand:", completion = "Seht Ihr denn nicht, welche Macht wir gewinnen, wenn wir uns der Blackrocklegion anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[4123] = { id = 4123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Berges", description = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum unteren Gewölbe der Schwarzfelstiefen durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", sourceObjective = "Bringt das 'Herz des Berges' zu Maxwort Funkelglanz in der brennenden Steppe.", progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, {name}, nehmt dies als Bezahlung an!", sourceObjectiveStatus = "unverified-source-field" }
quests[4124] = { id = 4124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Kurier", description = "Einer meiner Kollegen, Ginro Herdfeuer, braucht Hilfe und Informationen über den Aufenthaltsort eines Kuriers und der Pakete, die er bei sich hatte. Es ist etwa eine Woche her, dass der Kurier verschwunden ist; unsere eigene Suche hat nichts ergeben und wir wissen nicht, was wir noch tun sollen. Leider musste ich den Kurier für vermisst erklären.\n\nWenn Ihr freie Zeit und Kapazitäten habt, dann sprecht doch bitte mit Ginro. Er sollte irgendwo hier in der Festung sein, vielleicht in seinem Quartier.", sourceObjective = "Sprecht mit Ginro Herdfeuer in der Mondfederfeste.", completion = "Ich nehme an, Latro hat Euch geschickt. Ich glaube zwar inzwischen, dass es aussichtslos ist, aber ich nehme trotzdem gern jede Hilfe in Anspruch, die Ihr mir geben könnt. Ich muss zugeben... ich werde erleichtert sein, wenn ich diese Sache endlich vergessen kann. Jeden Tag gehe ich in die Wildnis Feralas' hinaus und suche dort nach einem Zeichen von Raschal. Und jeden Abend komme ich heim mit nichts in der Hand als Gnollzähnen und Enttäuschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[4125] = { id = 4125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Kurier", description = "Es ist etwa eine Woche her, seit der Kurier Raschal sich nach Thalanaar aufgemacht hat. Er kennt Feralas gut; er ist schon bei uns, seit General Mondfeder das Exeditionskorps hergeführt hat. Ich weiß, dass er vorhatte, mit einem Ruderboot die Küste entlangzufahren und Feralas im Süden zu durchqueren, um das Lager der Horde zu umgehen.\n\nIch konnte sein Boot nicht finden, aber vielleicht findet Ihr es ja. Vielleicht liegt es irgendwo versteckt...oder vielleicht wurde es auch versenkt. Wie dem auch sei, möglicherweise enthält es einen Hinweis darauf, wo Raschal ist. Wenn Ihr irgendetwas entdeckt, lasst es mich bitte wissen.", sourceObjective = "Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas.", completion = "Ihr habt etwas gefunden, das wie ein havariertes Ruderboot aussieht. Durch das etwas schlammige Wasser seht Ihr backbords etliche klaffende Löcher: Das ganze Boot ist fast bis auf sein einfaches hölzernes Grundgerüst zerfetzt. Was auch immer dieses Boot so zugerichtet hat, muss versucht haben, es entzweizubrechen. Steuerbords ist das Boot mit einem kleinen Wappen der Festung Feathermoon bemalt.\n\nIm Matsch am Boden des Bootes seht Ihr etwas metallisch aufblitzen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[4126] = { id = 4126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hurley Pestatem", description = "Die Dunkeleisenzwerge, angeführt von dem Bösewicht Hurley Pestatem, haben eines der besten Rezepte der Donnerbräus gestohlen, jenes für das Donnerbräu Lagerbier. Diese Schurken! Sie verdienen ein solch edles Gebräu nicht!\n\n{name}, ich habe eine schwierige Aufgabe für Euch. Geht zu den Schwarzfelstiefen in der brennenden Steppe, zerstört alle Fässer mit Donnerbräu Lagerbier, die Ihr finden könnt, und bringt unser Donnerbräurezept zurück!\n\nBitte, bringt das Rezept unbedingt zurück, und wenn Ihr dafür die ganzen Schwarzfelstiefen umkrempeln müsstet!", sourceObjective = "Bringt Ragnar Donnerbräu in Kharanos das verlorene Donnerbräurezept.", progress = "Habt Ihr das Rezept, {name}? Ich kann es nicht ertragen, dass diese Dunkeleisenzwerge sich an dem Stammgetränk meiner Familie laben!", completion = "Ihr habt es gefunden! Gut gemacht! Und ich hoffe, dass Ihr diesen Dunkeleisenzwergen und Hurley Pestatem eine ordentliche Abreibung verpasst habt!\n\nDie Donnerbräus stehen Euch jederzeit zu Diensten, {name}! Ihr seid der Held des Tages!", sourceObjectiveStatus = "unverified-source-field" }
quests[4127] = { id = 4127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havarie", description = "Als Ihr mit der Hand durch den Matsch fahrt, fühlt Ihr plötzlich den Griff eines Messers unter Euren Fingern. Es sieht gut gepflegt aus und dürfte mit Sicherheit jemandem gehört haben, der auf dem Boot gewesen ist. Vielleicht hat das große Stück des verschwundenen Bootes irgendetwas mit seinem Verschwinden zu tun.\n\nIhr nehmt das Messer an Euch, denn Ginro Herdfeuer in der Mondfederfeste hatte Euch angewiesen, ihm jegliche Hinweise sofort zu bringen. Allerdings werdet Ihr das ungute Gefühl nicht los, dass Ihr in diesem Gewässer nicht allein seid...", sourceObjective = "Kehrt zur Mondfederfeste zurück und zeigt Ginro Herdfeuer das gefundene Messer.", progress = "Ah, da seid Ihr ja wieder, {name}. Ich hoffe, dass Ihr etwas über Raschals Schicksal erfahren habt, so tragisch es auch sein mag.", completion = "Interessant... Ich glaube, das ist Raschals Messer. Ihr sagt, Ihr habt es auf dem Grund des Gewässers zusammen mit seinem Boot entdeckt? Tja, die Entdeckung des Messers allein wird nicht reichen, um Raschals Verschwinden zu erklären. Uns steht jedoch noch eine etwas unkonventionelle Methode zur Verfügung, mit der wir versuchen können, etwas herauszufinden.\n\nHabt Ihr schon mal von Psychometrie gehört?", sourceObjectiveStatus = "unverified-source-field" }
quests[4128] = { id = 4128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragnar Donnerbräu", description = "Hallo, {name}. Wie ich hörte, soll Ragnar Donnerbräu außer sich vor Wut sein, dass jemand sein Bier gestohlen hat. Er sucht nach wackeren Abenteurern und ist gewillt, sie reichlich zu entlohnen.\n\nSprecht mit Ragnar, wenn Ihr Interesse habt. Ihr findet ihn in der Brauerei Donnerbräu in Kharanos in Dun Morogh.", sourceObjective = "Sprecht mit Ragnar Donnerbräu.", completion = "Ich bin in der Tat fuchsteufelswild! Man hat mich beraubt! Eines der Rezepte unserer Familie wurde gestohlen! Wie können sie es wagen! Als hätte ich nicht schon Grund genug, die Dunkeleisenzwerge zu hassen! Aber jetzt, oh... jetzt sind sie dran!", sourceObjectiveStatus = "unverified-source-field" }
quests[4129] = { id = 4129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wieder aufgetauchte Messer", description = "Der Hausdruide der Festung, Quintis Lebenshand, verfügt über ein paar... ungewöhnliche Fertigkeiten. Eine davon ist die Psychometrie - die Fähigkeit, durch Berührung eines Objekts etwas über seine Geschichte zu erfahren. Fragt mich nicht, wie er das bewerkstelligt. Es muss etwas mit Magie zu tun haben, wovon ich nichts verstehe und womit ich auch nichts zu tun haben will. Zwei Dinge weiß ich jedoch: Erstens, ich habe gesehen, dass es funktioniert, und zweitens, der Gauner schuldet mir etwas.\n\nQuint lebt in einem kleinen Baumhaus. Bringt ihm das Messer und richtet ihm von mir aus, dass seine Kalimdor-Poker-Schulden bei mir beglichen sind, wenn er seinen Hokuspokus bei dem Messer wirkt.", sourceObjective = "Bringt Quintis Lebenshand in der Mondfederfeste das gefundene Messer.", progress = "Ach nein, also Ginro schickt Euch? Na ja...\n\nPsychometrie zehrt ziemlich an der Psyche... aber meine Verluste beim Kalimdor-Poker auch. Hier in der Festung nennt man mich den 'König der schlechten Karten'. Pech im Spiel... Glück im Umgang mit den Geheimnissen der Natur, könnte man sagen.\n\nWie dem auch sei, natürlich tu ich es. Das könnte genau der Durchbruch sein, den wir brauchen, um etwas über Raschals Schicksal in Erfahrung zu bringen. Wenn Ihr mir das Messer gebt, können wir gleich anfangen.", completion = "Ich danke Euch, {name}.\n\nPsychometrie ist zwar nicht einmal im weitläufigsten Sinn eine exakte Kunst, doch habe ich mich ihrer manchmal bedient, um in Situationen, in denen andere schon längst aufgegeben haben, Erleuchtung zu finden. Ich glaube, wenn ich sie bei dem Messer anwende, das Ihr gefunden habt, könnte uns das einen Hinweis darauf geben, was aus Raschal geworden ist.\n\nEs wird nur einen Moment dauern, aber es ist eine für den Zaubernden nicht gerade angenehme Angelegenheit. Habt Nachsicht mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[4130] = { id = 4130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Psychometrie-Sitzung", description = "Entschuldigt bitte, mir ist immer noch ein bisschen schwummrig. Wie dem auch sei, ich hatte ein paar nützliche Visionen.\n\nRaschal nimmt zwei lederne Rucksäcke aus seinem Boot und geht landeinwärts. Dann jedoch kehrt er zu seinem Boot zurück. Ich sehe Gnollskalps...er ist auf ein paar Gnolle gestoßen - Waldpfoten nennt man sie, glaube ich. Er ist sehr besorgt - fast schon panisch - wegen etwas. Und das so sehr, dass er nicht bemerkt, wie sich Wasserelementare hinter seinem Rücken manifestieren. Hier enden die Visionen.\n\nIch muss mich ausruhen, tut mir leid, {name}. Erzählt Gin, was ich gesehen habe. Er muss das wissen.", sourceObjective = "Sprecht mit Ginro Herdfeuer in der Mondfederfeste.", completion = "Vielen Dank, dass Ihr mir von Quints Visionen berichtet habt, {name}. Ich werde vielleicht ein bisschen großzügiger bei ihm sein, wenn wir uns das nächste Mal zu einem Kartenspiel zusammensetzen.\n\nRaschal kann in einem Kampf seinen Mann stehen und Gnolle sind nichts, was ihm Sorgen bereiten oder gar in Panik versetzen könnte. Vielleicht ist diese neue Information ja hilfreich für Euch und bringt Euch den Durchbruch, den wir so dringend benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4131] = { id = 4131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waldpfotengnolle", description = "Unsere 'Freunde', die Waldpfoten, mögen Raschal am Ende vielleicht zwar erwischt haben, aber irgendwie habe ich das Gefühl, als hätte sich da etwas anderes ereignet. Wie dem auch sei, es dürfte allerdings der beste Anhaltspunkt sein, um mit der Suche zu beginnen.\n\nIch wünschte nur, ich wüsste genauer, was zu tun ist, aber momentan kann ich lediglich sagen: 'Durchsucht die Lager der Waldpfoten. Macht Euch auf den Weg.' Ich weiß, dass Gnolle Gegenstände, die sie ergattern, behalten und um sie zanken. Vielleicht haben sie ja auch die Rucksäcke gefunden, die Quint erwähnte. Ohne Quints Visionen hätte ich bei früheren Suchaktionen niemals eine direkte Konfrontation mit ihnen gesucht, aber jetzt würde ich sagen: Auf sie mit Gebrüll!", sourceObjective = "Durchsucht die Lager der Waldpfotengnolle im Süden von Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten.", completion = "An einen Baum in der Nähe sind zwei große Lederrucksäcke genagelt. Beide tragen auf der Vorderseite klein die Insignien der Festung Feathermoon...", sourceObjectiveStatus = "unverified-source-field" }
quests[4132] = { id = 4132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Tod dem Zornesschmied", description = "Ihr habt bemerkenswerte Arbeit geleistet, {name}. Jetzt ist es an der Zeit, Euch auf Eure letzte Mission zu schicken.\n\nGeneral Zornesschmied, der für die Koordination der Angriffe auf die 109. Division des KEK und die massive Dezimierung unserer Truppen verantwortliche Dunkeleisenzwerg, muss zur Rechenschaft gezogen werden.\n\nDies wird zweifellos Eure schwerste Mission werden, aber solltet Ihr erfolgreich sein, wird man Euch reich entlohnen.", sourceObjective = "Begebt Euch zu den Schwarzfelstiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Bluthauer zurück, sobald Ihr diese Aufgabe erledigt habt.", completion = "Endlich! Der Bösewicht hat seine gerechte Strafe erhalten! Ihr seid ein bemerkenswertes Individuum, {name}. Tragt dieses Medaillon als Symbol Eures unerschütterlichen Engagements zum Wohle der Horde und des KEK.", sourceObjectiveStatus = "unverified-source-field" }
quests[4133] = { id = 4133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vivian Lagrave", description = "Schattenmeisterin Vivian Lagrave benötigt Eure Dienste. Sie lebt im Ödland, im orcischen Außenposten Kargath, wo sie dem Gerücht nachgeht, nach dem die Dunkeleisenzwerge der Schwarzfelstiefen angeblich ein bestimmtes Gebräu herstellen.\n\nSprecht mit Vivian. Sie erwartet Euch.", sourceObjective = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath.", completion = "Vielen Dank, dass Ihr gekommen seid, {name}. Dieser Ort entbehrt nicht eines gewissen rauen Charmes, aber es mangelt an den Annehmlichkeiten des Apothekariums.\n\nDoch genug geplaudert. Kommen wir zum Geschäft, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[4134] = { id = 4134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Donnerbräurezept", description = "Es geht das Gerücht umher, dass der Dunkeleisenzwerg Hurley Pestatem ein Rezept zum Brauen von Bier gestohlen habe. Dieses Bier, das Donnerbräu Lagerbier, soll angeblich jeden, der es trinkt, mit großer Kraft und Mut erfüllen. Wir möchten dieses Getränk gern untersuchen. Vielleicht finden wir ja noch andere Anwendungsgebiete für seine Vorzüge... Anwendungsgebiete, die eher im Einklang mit den Zielen der Verlassenen sind.\n\nDurchforstet die Schwarzfelstiefen, findet Hurley, nehmt das Donnerbräurezept von ihm und bringt es mir.\n\nUnd um ihn zu finden, müsst Ihr ihn möglicherweise locken, indem Ihr sein wertvolles Bier bedroht.", sourceObjective = "Bringt Vivian Lagrave in Kargath das verlorene Donnerbräurezept.", progress = "Habt Ihr das Donnerbräurezept, {name}?", completion = "Sehr gut. Ich schicke dieses Rezept zu Studienzwecken zum Apothekarium, wo man ihm schon bald seine Geheimnisse entlocken wird. Eines Tages werden die Zwerge der Allianz die Vorzüge dieses Getränks am eigenen Leib zu spüren bekommen!\n\nIch finde das höchst amüsant. Vielleicht hat der Tod Auswirkungen auf den Sinn für Humor ... was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[4135] = { id = 4135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verwundene Tiefe", description = "In den Rucksäcken befinden sich zwei Gegenstände: Der erste ist ein für Thalanaar bestimmtes Paket mit Waren, der zweite eine hastig hingekritzelte Notiz, die an einen unbekannten Empfänger gerichtet ist.\n\nDie Notiz spricht von der Entdeckung heimtückischer käferartiger Kreaturen südlich des Gnoll-Lagers an einem Ort der verwundene Tiefe genannt wird. Der Verfasser wollte die Sache persönlich untersuchen, da er dies als ernsthafte Bedrohung für ganz Feralas befand. Die Notiz ist mit 'Raschal von Mondfeder' unterzeichnet.\n\nOffenbar habt Ihr jetzt herausgefunden, wohin Raschal letztlich verschwunden ist.", sourceObjective = "Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt eine große Kapsel fremdartigen Ursprungs entdeckt. Die Oberfläche der Kapsel wirkt schleimig, doch an manchen Stellen ragen gehärtete Vorsprünge heraus. Die Kapsel selbst ist hoch und tief genug, dass ein humanoides Wesen leicht darin Platz finden könnte ... und anhand des humanoid anmutenden Umrisses der Gestalt darin, die durch die dünne Haut der Kapsel sichtbar ist, nehmt Ihr an, dass es tatsächlich ein solches Wesen ist, das darin verborgen liegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4136] = { id = 4136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ribbly Schraubstutz", description = "Mein Bruder Ribbly hat unserer Familie schon immer auf der Tasche gelegen, unser Geld genommen und es für eine Dummheit nach der anderen ausgegeben.\n\nTja, seine letzte Dummheit muss wohl seine bislang schlimmste gewesen sein, denn Baron Revilgaz von Beutebucht hat ein Kopfgeld auf den armen Ribbly ausgesetzt. Ich kann Euch gar nicht sagen, wie glücklich das die Schraubstutzs macht! Endlich ist unser kleiner Ribbly mal etwas wert!\n\nEr versteckt sich jetzt allerdings ganz weit unten in den Schwarzfelstiefen. Sucht ihn doch bitte und bringt ihn zu mir!\n\nUnd falls er nicht mitkommen will, ist das auch kein Problem...bringt mir einfach seinen Kopf.", sourceObjective = "Bringt Yuka Schraubstutz in der brennenden Steppe Ribblys Kopf.", progress = "Habt Ihr Ribbly mitgebracht? Oder zumindest einen Teil von ihm?", completion = "Aha! Ihr habt ihn gefunden! Und wie mir scheint, wollte mein kleiner Bruder offenbar nicht freiwillig mitkommen. Wie schade. Ich hätte zu gern sein Gesicht gesehen, wenn ich ihm von unserem Plan, ihn Revilgaz auszuliefern, erzählt hätte.\n\nDanke, {name}. Ihr habt meine Familie sehr glücklich gemacht. Und Ribbly hat nie so friedlich ausgesehen wie jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4141] = { id = 4141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muigin und Larion", description = "Seht Ihr Larion da drüben? Es ist SEINE Schuld, dass wir hier sind!\n\nIch hab ihm noch gesagt, dass wir in die falsche Richtung gehen, aber hat er auf mich gehört? Und stellt Euch vor, jetzt spricht er nicht mehr mit mir. Na ja, erlauben wir uns doch ein kleines Späßchen mit ihm, bis er es sich anders überlegt.\n\nSind Euch die seltsamen pflanzenartigen Kreaturen in dieser Gegend hier aufgefallen? Die machen nichts als Ärger, wirklich, aber ich glaube, wenn man sie ordentlich abrichten würde, könnte man sie dazu bringen, Befehlen zu gehorchen.\n\nAls Erstes bräuchte ich allerdings ein paar davon, um sie zu studieren. Meint Ihr, Ihr könntet mir ein paar bringen?", sourceObjective = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück.", progress = "Larion kann sich auf was gefasst machen, das steht mal fest!", completion = "Ich hoffe, sie haben Euch nicht zu viel Ärger bereitet, {name}. Ich versuche immer, ihnen aus dem Weg zu gehen - sie sind mir einfach zu wild!\n\nEinmal wollte ich über eine drüberspringen... Da griff sie mich an. Das ist doch kein Benehmen für eine Pflanze!", sourceObjectiveStatus = "unverified-source-field" }
quests[4142] = { id = 4142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei Gregan", description = "Ich weiß nicht so recht, was ich davon halten soll, {name}. Die Pflanzen... sie scheinen ein gewisses Maß an Intelligenz zu besitzen.\n\nAllerdings bin ich auf diesem Gebiet kein Experte. Aber ich kenne einen!\n\nGeht nach Nord-Feralas und sucht einen Freund von mir auf, er heißt Gregan Hopfenspei. Er kennt sich mit solchen Dingen bestens aus.\n\nGregan kann uns bestimmt weiterhelfen. Ihr findet ihn draußen in der Wildnis, denn für das Großstadtleben hat er nicht viel übrig.", sourceObjective = "Bringt Gregan Hopfenspei in Feralas eine Blutblüte.", progress = "Ich lebe hier draußen im Wald... Es ist so friedlich hier.\n\nNa, wenigstens dachte ich das. Ich bekomme hier draußen mehr Besuch als damals, als ich noch in Ironforge wohnte!", completion = "Eine Blutblüte was? Hmmm... Tja, Ihr solltet mir lieber mal erklären, was Ihr vorhabt, dann sage ich Euch, ob ich Euch helfen kann oder nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4143] = { id = 4143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunst des Bösen", description = "Um ehrlich zu sein, {name}, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...\n\nEgal, ich weiß vermutlich, was Muigin benötigt - Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.\n\nIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tieflauerern, Düsterwürmern oder Brühschlammern, die man dort findet. Viel Glück, {name}!", sourceObjective = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Krater von Un'Goro.", progress = "Larion spricht immer noch nicht mit mir! Wie kann man nur so nachtragend sein!", completion = "Ich muss gestehen, dass ich das Zeug nur sehr ungern anfasse, {name}! Aber wenn Gregan sagt, dass es funktioniert, dann will ich es mal ausprobieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[4144] = { id = 4144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutblütensprösslinge", sourceObjective = "Das ist mein Plan, {name}: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.\n\nIhr haltet mich vielleicht für rachsüchtig... Und damit liegt Ihr absolut richtig! \n\nDie Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!\n\nUnd nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!", progress = "Das ist mein Plan, {name}: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.\n\nIhr haltet mich vielleicht für rachsüchtig ... Und damit liegt Ihr absolut richtig! \n\nDie Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!\n\nUnd nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!", completion = "Dann mal los, {name}! Damit werden wir Larions Aufmerksamkeit erringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[4145] = { id = 4145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larion und Muigin", description = "Seht Ihr Muigin da drüben? Es ist SEINE Schuld, dass wir uns verirrt haben!\n\nIch kannte den richtigen Weg, aber er bestand darauf, eine Abkürzung zu nehmen, und so sind wir hier gelandet!\n\nUnd um die Lage noch zu verschlimmern, schickt er mir jetzt auch noch seine verrückten Pflanzen, um mich zu ärgern. Ich bin so wütend, dass ich bis auf weiteres kein Wort mehr mit ihm reden werde, aber diese Quälgeister sind wirklich unerträglich.\n\nWarum versuchen wir nicht als Erstes, seinen Bestand ein bisschen zu dezimieren? Geht hinaus und jagt einige Blutblüten und kehrt dann zu mir zurück.", sourceObjective = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marschalls Zuflucht.", completion = "Danke für Eure Hilfe, {name}, aber ich fürchte, ich habe schlechte Neuigkeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[4146] = { id = 4146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrumpftreibstoff", description = "Ihr habt Glück, {name}! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet, eines davon ist ein Käferschrumpfer mit kurzer Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.\n\nIhr könnt gern einen meiner Schrumpferprototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Schrumpfer benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tieflauerern, Düsterwürmern oder Brühschlammern.", sourceObjective = "Bringt Larion in Marschalls Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai.", progress = "Das kann einen echt fertig machen, {name}. Diese Biester lassen mich einfach nicht in Ruhe!", completion = "Marvon war also nicht da, eh? Na ja, zeigt mir trotzdem, was Ihr da habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4147] = { id = 4147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marvons Werkstatt", description = "Ich habe herausgefunden, was Muigin so treibt. Er züchtet da drüben doch tatsächlich diese verdammten Dinger!\n\nIch glaube, die einzige Lösung des Problems besteht darin, mit... nein, nicht mit ihm zu sprechen... Was für ein Blödsinn! Die Lösung ist zurückzuschlagen!\n\nWir brauchen die Hilfe meines Freundes Marvon, der in Ratschet eine Werkstatt hat. Er kann bestimmt irgendein Gerät zusammenbasteln, das uns helfen wird.", sourceObjective = "Reist zu Marvon Nietensuchers Werkstatt in Ratschet.", completion = "Marvon ist schon eine ganze Weile fort, {name}. Er wollte nach Tanaris, um dort ein paar der alten Troll-Ruinen zu untersuchen.\n\nAlso, was wolltet Ihr doch noch gleich?", sourceObjectiveStatus = "unverified-source-field" }
quests[4148] = { id = 4148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutblütenschrumpfer", progress = "Damit der Schrumpfer funktioniert, brauchen wir ein Exemplar der Kreaturen, für die er eingestellt werden soll. Geht zum Krater und holt einen Blutblütensprössling. Dann kann ich ihn so einstellen, dass er bei Muigins kleinen Freunden funktioniert...\n\nWenn der Typ nicht so stur wäre, könnten wir alle schon längst auf dem Heimweg sein. Aber jetzt muss ich ihm erst einmal beweisen, dass mir seine Faxen nicht das Geringste ausmachen!", completion = "Sieht aus, als würde es perfekt funktionieren, {name}. Und nicht vergessen: Benutzt diesen Schrumpfer, sobald Ihr auf einen dieser Plagegeister stoßt!" }
quests[4161] = { id = 4161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept der Kaldorei", description = "Vor langer Zeit nannte man die Nachtelfen 'Kaldorei', was übersetzt 'Kinder der Sterne' bedeutet. Für Euch als {class} ist es besonders wichtig etwas über die Vergangenheit zu erfahren, also hört gut zu, was ich Euch zu sagen habe, {name}.\n\nDie Kaldorei waren schon immer stolz auf ihre harmonische Beziehung zur Natur. Das bedeutet, dass wir von der Natur nur nehmen, was notwendig ist, und es in gleichem Maße vergelten. Dieses Gleichgewicht bedeutet uns viel, {name}.\n\nGeht und sammelt sieben kleine Spinnenbeine - und nicht mehr, und kommt dann zu mir zurück.", sourceObjective = "Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar.", progress = "Denkt an das Gleichgewicht, {name}. Ich möchte, dass Ihr das Leben im Wald verstehen lernt und Einfühlungsvermögen dafür entwickelt.", completion = "Denkt immer an das, was ich Euch heute gezeigt habe, {name}. Ihr seid Teil des Gleichgewichts, das die Nachtelfen auch in schweren Zeiten aufrechtzuerhalten bestrebt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[4181] = { id = 4181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Ich erwähne die Ingenieurskunst der Goblins nur, weil ich ein fairer und unvoreingenommener Lehrer bin. Sie machen gern Dinge, die in die Luft gehen, und es ist ihnen dabei meistens egal, ob dabei was im Weg herumsteht - auch wenn sie es selbst sind.\n\nLest dieses Handbuch, {name}. Wenn Ihr lernen wollt, wie Ihr Euch selbst in die Luft jagt, dann bringt es zu Nixx Sprossfeder nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr mehr über die Gobliningenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4182] = { id = 4182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachkin-Bedrohung", description = "Das Leben in der brennenden Steppe ist voller Konflikte.\n\nSeht Euch nur mal diesen Ort an! Wir wissen nur sehr wenig darüber, was mit diesen Gebäuden geschehen ist, aber wir wissen, dass all das hier irgendwann vor der großen Explosion einmal Teil der Rotkammbergkette war.\n\nAber genug gejammert! Wir haben ein Problem, {name}. Vielleicht sind Euch die Drachkin am Fuß dieses Bergkamms aufgefallen. Wir brauchen Hilfe, um sie zurückzuschlagen. Tötet so viele, wie Ihr könnt, und kommt dann zu mir zurück. Wenn Ihr erfolgreich seid, können wir uns vielleicht noch über andere Dinge unterhalten.", sourceObjective = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 Schwarzwyrmkins und 1 Schwarzdrachen. Kehrt zu Helendis Flusshorn zurück, sobald die Aufgabe erledigt ist.", completion = "Ausgezeichnete Jagd, {name}. Da wir jetzt wissen, dass Ihr Euch gegenüber den Drachkin behaupten könnt, können wir uns über dringendere Angelegenheiten unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[4183] = { id = 4183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahren Meister", description = "Bislang nahmen wir an, dass die Schwarzfelsorcs das Ergebnis ihrer primitiven Erziehung seien. Was wir jedoch hier, in ihrem Heimatland, entdeckt haben, erzählt uns eine ganz andere Geschichte.\n\nAngetrieben werden sie zwar tatsächlich von Kampfrausch und Streitlust, aber der schwarze Drachenschwarm ist es, der die Orcs des Schwarzfels beherrscht. Wir vermuten, dass es auch der schwarze Drachenschwarm ist, der ihre Wut und Feindseligkeit schürt.\n\nBringt diesen Brief zu Magistrat Solomon. Er wird wissen, was zu tun ist.\n\n<Helendis gibt Euch einen versiegelten Brief.>", sourceObjective = "Reist nach Seenhain und händigt Magistrat SolomonHelendis Flusshorns Brief aus.", progress = "Seid gegrüßt, {name}. Sind wir uns schon einmal begegnet? Ihr kommt mir irgendwie bekannt vor.", completion = "<Magistrat Solomon öffnet den versiegelten Brief von Helendis und beginnt zu lesen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4184] = { id = 4184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahren Meister", description = "Das sind schlimme Neuigkeiten, {name}. Zu entdecken, dass unsere Todfeinde nicht mehr als Marionetten einer viel größeren Bedrohung sind, ist wahrlich entmutigend. Es ist unmöglich, dass Seenhain einen Angriff durch die Schwarzfelsorcs UND den schwarzen Drachenschwarm überleben könnte. Wenn Seenhain dieser Gefahr anheim fällt, dann fällt bald auch Dunkelhain, und was dann? Goldhain? Auch Sturmwind?\n\nIhr müsst diese Information unbedingt sofort Hochlord Bolvar Fordragon in Sturmwind überbringen! Wenn dies nicht die Unterstützung Sturmwinds rechtfertigt, dann ist alles verloren.", sourceObjective = "Reist nach Sturmwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.\n\nBolvar residiert in der Burg Sturmwind.", progress = "Was führt Euch zur Burg Stormwind?", completion = "Großdrachen? Unmöglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[4185] = { id = 4185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahren Meister", description = "Solomon malt da ein recht düsteres Bild aus. Aber wir können es uns leider nicht leisten, unsere dünn gesäten Truppen aufgrund von reinen Vermutungen nach Seenhain zu schicken. Ich brauche einen Beweis für diese Behauptungen, bevor ich handeln kann.\n\nSprecht mit Lady Prestor, {name}. Sie ist eine kluge Frau und weiß viel über Großdrachen und Drachkin. Vielleicht kann sie ein bisschen Licht in die Sache bringen.", sourceObjective = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", progress = "<Bolvar betrachtet Euch eindringlich.>", completion = "<Bolvar reibt sein Kinn, als wäre er tief in Gedanken versunken.>\n\nIch respektiere zwar Lady Prestors Haltung, doch glaube ich, dass es für dieses Dilemma eine Lösung gibt, die all unsere Sorgen beseitigen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[4186] = { id = 4186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahren Meister", description = "Ich ernenne Euch hiermit zum kommissarischen Stellvertreter von Sturmwind, {name}.\n\nKehrt zu Magistrat Solomon in Seenhain zurück und übergebt ihm diesen Erlass.", sourceObjective = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus.", progress = "Irgendwelche Neuigkeiten von Bolvar?", completion = "Es hätte noch schlimmer kommen können, denke ich...\n\n<Magistrat Solomon betrachtet Euch eingehend.>\n\nEs scheint, als würde Seenhains Schicksal nun allein auf Euren Schultern lasten.\n\n<Ihr bemerkt, dass Magistrat Solomon heftig blinzelt. Er scheint zu weinen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4201] = { id = 4201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Liebestrank", description = "Oh, wie schmerzhaft doch die Liebe ist! Mein geliebter Gefreiter Rocknot ist immun gegen meinen Charme. Er verschmäht mich! Es ist zum Verrücktwerden!\n\nIhr müsst mir helfen! Wir Sukkubi wissen viel über die Liebe und ich kann einen Trank herstellen, der den eisernen Panzer um Rocknots Herz erweichen könnte. Dazu benötige ich folgende Dinge: das Kraut Gromsblut, Riesensilbervenen von den Klippenriesen Azsharas sowie Wasser aus der Quelle des Golakkakraters in Un'Goro. Ihr könnt das Wasser in diese Phiole füllen.\n\nBitte, {name}, verhelft einer armen Seele zum Glück!", sourceObjective = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Schwarzfelstiefen.", progress = "Habt Ihr die Zutaten? Die Leere in meinem Herzen verschlingt mich noch!", completion = "Oh, Ihr habt es geschafft! Jetzt kann ich meinen Trank brauen und ihn Rocknot geben. Endlich wird er meinem Charme verfallen!\n\nIch danke Euch, {name}. Ihr seid ein wahrer Verfechter der Liebe!", sourceObjectiveStatus = "unverified-source-field" }
quests[4221] = { id = 4221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4222] = { id = 4222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4223] = { id = 4223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahren Meister", description = "<Magistrat Solomon seufzt.>\n\nIhr müsst in die brennende Steppe zurückkehren, {name}. Als Stellvertreter von Sturmwind erwartet man von Euch, dass Ihr Euch bei Marschall Maxwell meldet. Viel Glück.", sourceObjective = "Sprecht mit Marschall Maxwell in der brennenden Steppe.", completion = "<Marshal Maxwell lacht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4224] = { id = 4224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahren Meister", description = "Was? Ihr dachtet, Ihr wärt der Erste? Wie viele Soldaten müssen wir noch verlieren, bevor Sturmwind handelt?\n\nWir hatten riesige Mengen an Informationen über die Schwarzfelsbedrohung zusammengetragen, doch dann verloren wir unseren befehlshabenden Offizier, Marschall Windsor. Zusammen mit Marschall Windsor gingen auch all unsere wertvollen Informationen verloren.\n\nWas wir brauchen, ist diese Dokumentation. Sprecht mit dem struppigen John, {name}. Er war mit Windsor zusammen, als sie von einem Stoßtrupp der Schwarzfelsorcs überfallen wurden. Er wurde zuletzt in einer Höhle im Norden gesehen.", sourceObjective = "Sprecht mit dem struppigen John, um etwas über Marschall Windsors Schicksal zu erfahren, und kehrt dann zu Marschall Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.\n\nIhr erinnert Euch daran, dass Marschall Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.", progress = "Habt Ihr schon mit John gesprochen?", completion = "Ich hätte Euch warnen können, aber das wäre nur der halbe Spaß gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4241] = { id = 4241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschall Windsor", description = "Dieser nichtsnutzige Feigling behauptet also, Windsor sei noch am Leben, was?\n\nMacht Euch bereit, Stellvertreter, Ihr werdet ausziehen, um ihn zu suchen. Falls Windsor noch am Leben ist, müsst Ihr ihn zurückholen. Sollte er tot sein, brauche ich einen Beweis dafür.\n\n<Maxwell lacht.>\n\nIch wette, das könnt Ihr langsam schon nicht mehr hören, was?", sourceObjective = "Reist zum Schwarzfels im Nordwesten und dann weiter zu den Schwarzfelstiefen. Findet heraus, was aus Marschall Windsor geworden ist.\n\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt.", completion = "Wo ist er? Ich bringe ihn um!", sourceObjectiveStatus = "unverified-source-field" }
quests[4242] = { id = 4242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Hoffnung", description = "Bolvar ist ein Dummkopf. Ich war gerade dabei, ihm seinen kostbaren 'Beweis' zu beschaffen, um ihm diesen in den Hals stopfen zu können.\n\nEr ist ein blinder Blödmann. Selbst wenn der Beweis ihn in die Nase beißt, würde er ihn nicht sehen.\n\nWas meine Informationen angeht, die sind verloren. Unwiderbringlich.\n\nSollte ich Eisenfeind jemals finden und es aus diesem Labyrinth herausschaffen, wird mein erster Halt Sturmwind sein, damit ich diesem Reptil meinen Hammer über den Schädel ziehen kann.\n\nGeht jetzt, {name}.", sourceObjective = "Überbringt Marschall Maxwell die schlechten Neuigkeiten.", completion = "Er ist offensichtlich verrückt geworden.\n\n<Maxwell senkt sorgenvoll den Kopf.>\n\nEs ist bedauerlich, dass ein einst so stolzer und edler Krieger zu solch einem kompletten Schwachkopf mutiert ist. Ich schätze, wir sind in einer Sackgasse...\n\nDennoch muss ich Euch für Eure bisherigen Bemühungen entlohnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4243] = { id = 4243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Kraters von Un'Goro heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.\n\nSie hat Wahrsagesteine als Augen, so konnte ich alles sehen, was auch sie sah. Den Fungusfels hat sie wohlbehalten erreicht - das ist das Versteck der Affen, gleich nördlich von hier. Und dort habe ich dann den Kontakt zu ihr verloren. Das Letzte, was ich sah, war eines der Alphamännchen, das auf sie zugestürmt kam, um sie zu begrüßen!\n\nKönntet Ihr mir wohl helfen, sie zu finden?", sourceObjective = "Sucht im Krater von Un'Goro nach A-Me 01.", completion = "Als Ihr A-Me 01 eingehend betrachtet, entdeckt Ihr zwei gewaltige Beulen, die Karnas Meisterwerk der Ingenieurskunst verunzieren. Eine Beule befindet sich an der Schulter von A-Me 01, die andere an ihrem Kopf.\n\nDurch ihre Bauteile scheint kein Strom zu fließen, wie Ihr nach weiterer Untersuchung feststellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4244] = { id = 4244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Ihr setzt Eure Untersuchungen fort und findet eine Abdeckung, die sich aufschieben lässt. Oberhalb der Verkabelung steht in gut lesbarer Schrift geschrieben: 'Mithrilgehäuse ersetzen und Strom erst ausschalten, dann einschalten.'\n\nEs dauert einen Moment, bis Ihr die Abdeckung wieder angebracht habt, und Ihr fragt Euch, ob es wirklich so einfach ist, A-Me 01 zu reparieren und zurück zu Karna Wirrbart in der Nähe von Marschalls Zuflucht zu bringen.\n\nTja, probieren geht über studieren...", sourceObjective = "Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Krater von Un'Goro.", progress = "Die Abdeckung, in die das Mithrilgehäuse gehört, ist immer noch verschlossen. Der Rest von A-Me 01 bleibt reglos.", completion = "Ihr entfernt wieder die Abdeckung im Rücken von A-Me 01 und nehmt das alte Mithrilgehäuse heraus, das offensichtlich durchgebrannt ist. Das neue klickt problemlos an seinen Platz. Vorausgesetzt, das Mithrilgehäuse war die Ursache des Problems, müsst Ihr jetzt nur noch den Schalter auf 'Aus' und dann wieder auf 'Ein' stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4245] = { id = 4245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Nachdem Ihr Euch vergewissert habt, dass Ihr bereit seid, A-Me 01 zu Karna Wirrbart zurückzubringen, knipst Ihr den Schalter auf 'Aus'. Ihr seht Euch nochmals um, um sicherzugehen, dass sich keine Gorillas nähern, und fragt Euch, was wohl geschieht, wenn Ihr den Schalter wieder auf die 'Ein'-Position stellt.\n\nDas ist Eure letzte Chance...wollt Ihr das wirklich tun?", sourceObjective = "Begleitet A-Me 01 zu Karna Wirrbart im Krater von Un'Goro.", completion = "Oh, Ihr habt es geschafft! Großartig! Ich danke Euch, {name}.\n\nOh, meine arme A-Me. Diese Beulen, oh nein! Aber mit Geduld und Spucke werden wir sie im Handumdrehen wieder voll funktionsfähig haben.\n\nNochmals danke, {name}. Ich weiß das wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4261] = { id = 4261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Geist", description = "Der Teufelswald war einst ein friedliches und ruhiges Land... bis die Legion hier eingefallen ist. Die Höllenbestien, Zerstörung, Chaos...\n\nDer Schädel des Gul'dan hat dafür gesorgt, dass hier niemand ungeschoren davonkam. Alles fiel der Verderbnis zum Opfer.\n\nSogar jetzt, da ich ein Geist bin, bin ich immer noch gefangen und muss die Leiden dieses Landes ertragen. Helft mir, den Weg nach Hause zu finden. Bitte, {name}, sagt mir, dass Ihr einen alten Geist weg von hier führen werdet, dorthin, wo ich endlich ruhen kann.\n\nSobald ich frei sein werde, solltet Ihr Kayneth Stillwind aufsuchen, einen Druiden, der in Waldeslied im Osten lebt.", sourceObjective = "Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Waldeslied, im Osten des Eschentals.", completion = "Ja, {name}. Der Teufelswald hat eine Menge durchgemacht. Vielen Dank für Eure Mühen.\n\nEines Tages werden wir den Teufelswald den Klauen der Verderbnis entreißen können. Jede gute Tat trägt dazu bei.", sourceObjectiveStatus = "unverified-source-field" }
quests[4262] = { id = 4262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übermeister Pyron", description = "Die letzten fünf meiner Magier, die ausgezogen waren, um sich auf dem Schwarzfels umzusehen, kamen knusprig geröstet zurück, mit einem dauerhaften orangefarbenen Gnomenafro - oder noch schlimmer.\n\n<Jalinda nimmt etwas Asche vom Boden auf und lässt sie vom Wind davontragen.>\n\nEin besonders mieses Individuum, Übermeister Pyron, scheint hier eine Menge Ärger zu verursachen. Dieser Elementar muss vernichtet werden, damit unser Expeditionsteam in die Schwarzfelstiefen reisen kann!\n\nEr bewacht den Eingang am Schwarzfelssteinbruch.", sourceObjective = "Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.\n\nIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?", completion = "Incendius? Oje...", sourceObjectiveStatus = "unverified-source-field" }
quests[4263] = { id = 4263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendius!", description = "Seid Ihr sicher, dass Pyron 'Incendius' sagte, als er starb?\n\n<Jalinda schluckt schwer.>\n\nLord Incendius soll angeblich einer von Ragnaros Dienern sein! Oje, oje... was sollen wir jetzt nur tun?\n\nMeint Ihr, Ihr könntet noch eine weitere Mission bewältigen? Ich habe niemand anderen, den ich schicken könnte, {name}!\n\nWir werden niemals eine Gruppe hineinbringen, solange Incendius Pyron aus der Asche immer wieder neu erstehen lässt.\n\nIhr müsst Lord Incendius suchen und vernichten!", sourceObjective = "Sucht Lord Incendius in den Schwarzfelstiefen und vernichtet ihn!", completion = "Oje! Seid Ihr sicher, dass Incendius 'Ragnaros' sagte?\n\n<Jalinda gibt Euch etwas und tätschelt Euer Handgelenk, während sie tief in Gedanken versinkt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4264] = { id = 4264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zusammengeknüllte Notiz", description = "Die Notiz ist mit Flecken übersät. Der Text ist kaum noch lesbar, aber Ihr könnt Folgendes erkennen:\n\n... süße Ironie...\n\n... der Sturz der zerbrochenen Allianz...\n\n... ohne General Angerfords Sorgfalt hätten wir das Schema der Verschlüsselung niemals herausgefunden...\n\n... Argelmach hat Windsors Notizen fast entschlüsselt.\n\nUnser Lord wird sich aus den Tiefen erheben und alle zerschmettern, die noch übrig sind...\n\nImperator Dagran Thaurissan", sourceObjective = "Soeben seid Ihr auf etwas gestoßen, das Marschall Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung.", progress = "<Marshal Windsor betrachtet die Notiz in Eurer Hand.>\n\nWas bringt Ihr mir da, {name}?", completion = "<Marshal Windsor nimmt die Notiz und beginnt zu lesen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4265] = { id = 4265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus dem Schwarmbau", description = "Die Kapsel platzt auf, als Ihr sie berührt, und zum Vorschein kommt ein Nachtelf, der überraschenderweise noch am Leben ist. Er scheint bei guter Gesundheit zu sein, ist jedoch sehr benommen. Als Ihr ihm aus der Kapsel heraushelft, regt sich Leben in ihm.\n\n\"Elune sei Dank! Ihr habt mich gerettet! Ich... Mein Name ist Raschal. Ich erwachte völlig gelähmt in dieser Kapsel, nachdem mich diese Käfer überwältigt hatten. Wurdet Ihr von der Festung geschickt?\"\n\nAnscheinend habt Ihr den vermissten Kurier gefunden!", sourceObjective = "Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.\n\nKehrt zu Ginro Herdfeuer in der Mondfederfeste zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht.", completion = "Willkommen daheim, {name}. Raschal hat mich vor kurzem aufgesucht und erzählt, was ihm zugestoßen ist.\n\nIch... nein, die gesamte Festung kann Euch gar nicht genug für Eure großartige Tat danken. Raschal wäre ohne Euer rechtzeitiges Einschreiten jetzt tot und Ihr habt uns geholfen, ohne auch nur den Hauch eines Söldnerlohns dafür zu verlangen. Ihr tragt das Zeichen eines wahren Helden. Wisset, dass Ihr in Ginro Hearthkindle einen Freund fürs Leben gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4266] = { id = 4266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Empfang eines Helden", description = "{name}, General Shandris Mondfeder möchte unter vier Augen mit Euch sprechen. Sie möchte Euch bestimmt für Eure Dienste zum Wohle der Festung danken, aber ich weiß auch, dass sie außerdem mit Euch über diese Insektenwesen sprechen will, auf die Ihr und Raschal im Süden von Feralas gestoßen seid. Die Berichte, die diese Insekten der Zukk'ash betreffen, sind...mehr als beängstigend.\n\nGeneral Mondfeder wartet im Haupttruppenlager auf Euch.", sourceObjective = "Sprecht mit Shandris Mondfeder in der Mondfederfeste.", completion = "{name}, meinen allerherzlichsten Dank für Eure Hilfe. Eure Tapferkeit angesichts widrigster Umstände verlangt nach einer Belohnung, die tausend Mal größer ist. Ich hoffe dennoch, dass Ihr dies im Namen der gesamten Festung annehmt.\n\nUnd jetzt, wenn Ihr gestattet ... Ich möchte Euch um einen weiteren Gefallen bitten. Angesichts der Entdeckung des Schwarmbaus der Zukk'ash hier in Feralas denke ich, dass Ihr die richtige Wahl für diese Mission seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[4267] = { id = 4267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Silithiden", description = "Ich vertraue Euch eine Kopie des Berichts an, den Raschal über die Plage im Südosten Feralas' angefertigt hat. Der eigentliche Bericht befindet sich in den Akten in Darnassus, aber ich möchte, dass Ihr diese Kopie an eine Vertraute des Protektorats überbringt. Ihr Name lautet Gracina Glaubensmacht. Sie ist eine Priesterin, die im Tempel des Mondes in Darnassus lebt. Sie verfügt über großes Wissen, solche Kreaturen betreffend, und wenn sie diesen Bericht erhalten würde, käme es uns allen sehr zugute.\n\nMacht Euch auf den Weg, und viel Glück, {name}. Möge Elune über uns alle wachen.", sourceObjective = "Bringt Raschals Bericht zu Gracina Glaubensmacht in Darnassus.", progress = "Willkommen in diesem gesegneten Tempel. Die Festung Feathermoon hat mich über Euer Kommen informiert. Habt Ihr den Bericht, den Shandris Feathermoon Euch gebeten hat mir zu bringen?", completion = "Wir Nachtelfen wissen um den Schrecken, von dem in diesem Bericht die Rede ist. Shandris hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden Feralas schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Die Insekten, auf die Ihr und der Kurier gestoßen seid, sind als Silithiden bekannt. Sie sind die Werkzeuge der größten Bedrohung, der sich die Horde und die Allianz gegenübersehen.\n\nIch bete darum, dass wir die Entschlossenheit besitzen, sie zu besiegen, bevor sie uns vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[4281] = { id = 4281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalanaar-Lieferung", description = "Dieses Paket mit Waren, das Ihr in den Lagern der Waldpfotengnolle gefunden habt, war für den kleinen Streckenposten Thalanaar im Südosten Feralas' bestimmt. Das Paket, ungeachtet des Schicksals des vermissten Kuriers, harrt immer noch der Auslieferung.\n\nIhr untersucht das Paket genauer und entdeckt den Namen 'Falfindel Wegeshut' handschriftlich auf der Verpackung vermerkt. Vielleicht ist er der eigentliche Empfänger des Pakets.", sourceObjective = "Bringt das nicht ausgelieferte Paket zu Falfindel Wegeshut in Thalanaar.", progress = "Willkommen in Thalanaar, {class}. Kann ich Euch irgendwie behilflich sein?", completion = "Elune sei gepriesen, die Lieferung von der Festung Feathermoon ist endlich eingetroffen!\n\nEure Anwesenheit hier sagt mir, dass Raschal, unseren eigentlichen Kurier, wohl ein böses Schicksal ereilt hat. Ich hoffe, dass sich alles zum Guten wenden wird. Ich weiß, dass die Waldpfoten seit kurzem wegen irgendetwas, das sich südlich von ihnen ereignet hat, äußerst aufgebracht sind. Vielleicht ist er dort der Wildnis zum Opfer gefallen. Ich an Eurer Stelle wäre vorsichtig.\n\nNun denn, nochmals danke. Hier ist Eure Entlohnung für die Auslieferung des Pakets.", sourceObjectiveStatus = "unverified-source-field" }
quests[4282] = { id = 4282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Funken Hoffnung", description = "<Marschall Windsor wedelt aufgeregt mit der Notiz herum.>\n\nWisst Ihr, was das bedeutet, {name}?\n\nVielleicht ist doch noch nicht alles verloren! Soweit ich das erkennen kann, wird die Information von zwei Dunkeleisenzwergen verwahrt: General Zornesschmied und dem Golemlord Argelmach. Ich habe das Gefühl, als würden sie die Information nicht einfach so herausrücken, wenn wir sie freundlich darum bitten.\n\nAlso hoffe ich, dass Ihr auf einen Kampf vorbereitet seid.\n\nZieht aus und findet die beiden Bösewichte! Vernichtet sie und bringt mir meine verloren gegangenen Informationen zurück.", sourceObjective = "Holt Marschall Windsors verlorene Informationen zurück.\n\nMarschall Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden.", progress = "Schon bald wird es mit dieser grandiosen Täuschung ein Ende haben.", completion = "<Marshal Windsor reißt die zwei Schrifttafeln aus Eurer Hand.>\n\nWir müssen hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[4283] = { id = 4283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FÜNFZIG! Jawoll!", description = "Ich werde Euch ein kleines Geheimnis verraten, Soldat: Kommt näher.\n\nICH BIN HIER DER EINZIGE, DER NOCH BEI VERSTAND IST!\n\nSeht Euch nur all diese Leute an! Ist es zu fassen, dass sie alle irre sind!? Oh ja, das sind sie! DURCHGEDREHT! WAHNSINNIG!\n\n<Oralius senkt die Stimme.>\n\nDas bleibt aber unter uns: mir, Euch und meinem Kumpel Käpt'n Winky.\n\n<Oralius greift in die Luft und drückt zu.>\n\nWie auch immer...Ich sammle Abzeichen, die gut zu meiner Sammlung Ogerohren passen. Orcs sind der letzte Schrei. Fünfzig. LOS!\n\n<Oralius stößt in ein Horn.>\n\nAB DAMIT!", sourceObjective = "Oralius will 50 Medaillons des Schwarzfelsklans haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet.", progress = "<Oralius spricht mit einem ziemlich großen, abgetrennten Ogerohr.>\n\nBrennende Steppe an Zentrale. Zentrale, bitte kommen.", completion = "Ihr habt es geschafft! Und das ist Eure Belohnung: STREICHELT MEINEN BAUCH! LOS DOCH! STREICHELT IHN!", sourceObjectiveStatus = "unverified-source-field" }
quests[4284] = { id = 4284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtkristalle", description = "Ich bin sicher, Ihr habt sie bemerkt, {name}. Sie sind überall!\n\nWovon ich rede? Na, von den Kristallen natürlich!\n\nDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht. Ich habe eine Weile mit ihnen herumexperimentiert, aber ich habe noch nichts herausgefunden. Tja, bis jetzt jedenfalls.\n\nAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?", sourceObjective = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marschalls Zuflucht.", progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, {name}!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4285] = { id = 4285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nordpylon", description = "Wofür die wohl gut sind? Ich muss ständig daran denken!\n\nEs macht mich verrückt, dass all die Gerüchte über die Kristallpylonen wahr sind. Nennt mich leichtgläubig, aber ich glaube gewöhnlich, was mir die Leute erzählen.\n\nWie dem auch sei, ich habe gehört, dass sich einer dieser Kristallpylonen hier ganz in der Nähe befinden soll. Irgendwo im Norden...Sucht ihn doch bitte, {name}. Ich weiß genau, dass es die Dinger gibt.", sourceObjective = "Findet den Standort des nördlichen Kristallpylonen im Krater von Un'Goro.", completion = "Ich weiß, dass die Geschichten wahr sind, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4286] = { id = 4286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feine Sachen", description = "Käpt'n Winky sagt mir, dass die Dunkeleisenzwerge in den Tiefen das ganze gute Zeug haben. Stimmt's nicht, Winky?\n\n<Oralius versucht, so gut es geht, einen Piraten zu imitieren.>\n\nHARRR, KUMPEL! DAS STIMMT!\n\nDa hört Ihr's. Ihr müsst Euch dorthin begeben und mir etwas von dem guten Zeug besorgen.\n\nGeht da rein und holt es Euch!", sourceObjective = "Reist in die Schwarzfelstiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Schwarzfelstiefen diese 'Gürteltaschen'-Dinger tragen.", progress = "Ich kann jetzt nicht, {name}. Ich und Winky müssen zu einer Konferenz.", completion = "<Oralius beginnt, in den hoch aufgetürmten Gürteltaschen herumzuwühlen.>\n\nOH, WUNDERBAR!\n\n<Oralius steckt seine lange Nase in den Berg und nimmt einen tiefen Atemzug.>\n\nKÖSTLICH! Seht Euch nur all die schönen Sachen an!\n\nDa, nehmt Euch auch so'n Ding, {name}. Es sind genug davon da.", sourceObjectiveStatus = "unverified-source-field" }
quests[4287] = { id = 4287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ostpylon", description = "Während meines Aufenthaltes hier sind mir seltsame Gerüchte über rätselhafte Pylonen zu Ohren gekommen, die es angeblich draußen in der Wildnis des Kraters geben soll, {name}. Ich nehme an, sie sind ziemlich groß, mit Kristallen an den Innenseiten.\n\nIch habe zwar noch nie welche gesehen, aber ich komme nicht umhin zu glauben, dass die Gerüchte wahr sind - und dass die Pylonen irgendetwas mit all den Kristallen zu tun haben, die wir gefunden haben.\n\nAlso, warum helft Ihr mir nicht, meine Neugier zu stillen? Angeblich soll es einen im östlichen Teil des Kraters geben. Meint Ihr, Ihr könntet ihn finden?", sourceObjective = "Findet den Standort des östlichen Kristallpylonen im Krater von Un'Goro.", completion = "Un'Goro ist ein sehr seltsamer Ort, {name}. Wenn man den Krater betritt, kommt es einem so vor, als wäre man in einer ganz anderen Welt...", sourceObjectiveStatus = "unverified-source-field" }
quests[4288] = { id = 4288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Westpylon", description = "Meine Experimente haben bis jetzt noch keine positiven Ergebnisse erzielt, {name}. Ich kann nur hoffen, dass Ihr eine Lösung findet, indem Ihr einen der Pylonen entdeckt, von denen ich gehört habe.\n\nWas, wenn wir bestimmte Farben mit ihnen kombinieren würden...ach, eines nach dem anderen. Zuerst müssen wir sie finden!\n\n{name}, sucht im westlichen Teil des Kraters. In diesem Gebiet soll sich irgendwo ein Pylon befinden.", sourceObjective = "Findet den Standort des westlichen Kristallpylonen.", completion = "Entlang der Ränder des Kraters gibt es viele verborgene Bereiche. Erkundet die gewundenen Pfade, wenn Ihr nicht mehr wisst, wo Ihr noch suchen sollt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4289] = { id = 4289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Affen von Un'Goro", description = "In diesem Krater gibt es viele seltsame Kreaturen - sie scheinen edler zu sein als ihre Verwandten, die man überall in meinem Heimatland und jenseits davon findet. Ich habe keine Erklärung dafür, aber dieser Ort trägt die Handschrift der Erdenmutter. Immer, wenn ich auf eines ihrer wundervollen Geschöpfe in diesem Krater stoße, erweise ich ihr meine Ehrerbietung.\n\nWenn auch Ihr diese Erleuchtung spüren möchtet, die eine solche Tat begleitet, dann geht nach Norden. Dort findet Ihr große Affen, die die Kraft eines jeden Sterblichen auf eine harte Probe stellen. Bringt mir ihre Pelze...beweist mir Eure Kraft.", sourceObjective = "Bringt Torwa Pfadfinder am Eingang zum Krater von Un'Goro 2 Gorillapelze von Un'Goro, 2 Stampferpelze von Un'Goro und 2 Donnererpelze von Un'Goro.", progress = "Haben Euch die Kreaturen hier bereits besiegt, {name}?\n\nLasst Euch doch nicht so leicht entmutigen. Die Un'Goro-Affen aufzuspüren und sie zu besiegen ist keine einfache Aufgabe, auch nicht für einen großen Jäger.", completion = "Ihr habt also Eure Kraft bewiesen und dass Ihr kräftig genug seid, um sogar die großen Affen von Un'Goro zu besiegen - das ist gut. Im Vergleich zu Lar'korwi war das zwar nur eine kleine Herausforderung, aber ich will Euch Euren großen Sieg nicht nehmen.\n\nDiese Pelze werden herrliche Kleidung für meinen Stamm abgeben. Ihr habt mir geholfen und Euch als würdig erwiesen.\n\nBevor Ihr Euch einer anderen Aufgabe annehmt, lasst uns noch der Erdenmutter huldigen und den Geistern der Affen danken, die Ihr getötet habt, damit sie wissen, dass ihr Tod nicht umsonst gewesen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[4290] = { id = 4290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lar'korwis Mahl", description = "Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.\n\nLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.\n\nWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.\n\nKommt dann zu mir zurück.", sourceObjective = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pfadfinder im Krater von Un'Goro zurück.", progress = "Hört auf meine Worte, {name}. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, {name}. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[4291] = { id = 4291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lar'korwis Fährte", description = "Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, {name}. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.\n\nAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasauruseier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.", sourceObjective = "Bringt Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro 2 Pheromondrüsen eines Ravasaurus.", progress = "Seid vorsichtig, {name}. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, {name}. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes.", sourceObjectiveStatus = "unverified-source-field" }
quests[4292] = { id = 4292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder für Lar'korwi", description = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Nördlich von hier findet Ihr einen kleinen Pfad, der in die Berge hinaufführt. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit der Drüse ein. Wenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.", sourceObjective = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro.", progress = "Lasst Euch nicht von Furcht überwältigen, {name}. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!\n\nNehmt das Fleisch, legt es in dem kleinen Tal ab und reibt es dann mit der Drüse ein. Nur so wird der Tod zu Euch kommen.", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, {name}. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[4293] = { id = 4293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Brühschleimerprobe...", description = "Der Teufelswald ist ein Wald weit im Norden des Brachlandes, sogar noch weiter weg als das Eschental. Um die dortigen Teiche herum, die durch dämonische Energie gesegnet wurden, befinden sich überall Brühschlammer. Die Geißel hat mit den Angriffen von Höllenbestien und anderer Dämonenmagie die Gegend stark verwüstet - die Brühschlammer sind angeblich während dieser Angriffe aus der Erde an die Oberfläche gekrochen.\n\nSammelt einige Proben von Teufelswaldbrühschlammern, dann verwenden wir die Testausrüstung hier neben mir, um eine Kontrollgruppe zusammenzustellen, mit der wir die anderen Proben, die Ihr einsammelt habt, vergleichen können.", sourceObjective = "Sammelt Teufelswaldschleimproben von den Brühschlammern im Teufelswald. Verwendet dann die Testausrüstung neben Chemiker Brenner in Unterstadt, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Teufelswaldproben, die Ihr findet, zu Chemiker Brenner.", progress = "Für unsere Kontrollgruppe brauche ich mindestens fünf verderbte Proben, {name}. Sammelt weiter Teufelswaldschleimproben, bis Ihr mir das geben könnt, was wir brauchen. Lady Sylvanas hat es verfügt...", completion = "Ah, wunderbar. Diese Proben sind genau richtig. Ich danke für Eure Hilfe.\n\nSobald wir alle Brühschleimerproben zusammenhaben, können wir mehr sagen. Langsam fange ich an zu glauben, dass Lady Sylvanas mit ihrer Ahnung nicht nur Recht hatte, sondern dass diese auch noch mit mehr Einsicht gesegnet war, als sogar sie gedacht hätte. Diese Proben sind sehr interessant. Allein zu sehen, wie sie auf meine Präparate reagiert haben ... hmm, ja, ganz zweifellos müssen wir noch weitere Untersuchungen anstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4294] = { id = 4294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und eine Menge Brühschlammer", description = "Habt Ihr schon einmal vom Krater von Un'Goro gehört, {name}? Er liegt in der Nähe der Tanariswüste und es ist ein großartiger Ort: üppig, von Leben sprühend, voller Kreaturen und Pflanzen.\n\nDorthin müsst Ihr Euch begeben. Ich habe mir sagen lassen, dass der Krater noch völlig unbesudelt und frei von Einflüssen von außen sei. Erst jetzt beginnen Forscher, seine Geheimnisse zu entdecken.\n\nIch würde die dortigen Brühschleimer und Brühschlammer gern testen. Wenn es stimmt, dass sie nicht verderbt sind, dann würde ich gern wissen, wie sich solche Kreaturen entwickelt haben.", sourceObjective = "Sammelt Brühschleimerprobe von Un'Goro von jedem der Brühschleimer im Krater von Un'Goro. Verwendet dann die Testausrüstung neben Chemiker Brenner in Unterstadt, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Proben von Un'Goro, die Ihr findet, zu Chemiker Brenner.", progress = "Ja, {name}? Wie läuft Eure Suche?", completion = "Einfach erstaunlich, {name}. Dieser Un'Goro Krater birgt wesentlich mehr Geheimnisse als ich dachte. Ich frage mich, was wir noch alles entdecken werden, wenn wir unsere Tests fortsetzen.\n\nWirklich erstaunlich... seht Euch nur an, wie rein diese Proben sind! Hmm... ich frage mich, was das bedeuten könnte. Es scheint sich bei ihnen um Elementare zu handeln, aber... auch noch um mehr. Sie erinnern mich an... die Alten Götter. Deren Spuren haben wir in ganz Azeroth gefunden und jetzt frage ich mich, ob diese Wesen nicht irgendwie mit ihnen verwandt sind.\n\nWir müssen weitere Tests durchführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4295] = { id = 4295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocknots Bier", progress = "Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der {race}, den ich letzte Woche erschlagen habe!", completion = "Was ist denn das? Ah! Das riecht wie Dunkeleisenbier! Das Trinken verschleiert meine Sicht, aber ich sehe, dass Ihr, werter Herr, ein echter Freund seid!" }
quests[4296] = { id = 4296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrifttafel der Sieben", description = "Die Legenden der Sieben führten mich in die brennende Steppe. Sie waren hoch gebildete und mächtige Zwerge, und wenn man über Wissen und Macht verfügt, so ist das der Schlüssel zum Reichtum.\n\nUnd genau das ist es, was ich will. Reichtum!\n\nWenn wir mehr über die Sieben in Erfahrung bringen könnten, würde das uns beide vielleicht reich machen. In den Ruinen von Thaurissan soll sich angeblich die Schrifttafel der Sieben befinden, auf der das Wissen über die alten Zwerge geschrieben steht. Sucht diese Schrifttafel, kopiert den Text und bringt ihn mir. Lasst uns deren Geheimnisse gemeinsam entschlüsseln!", sourceObjective = "Bringt Maxwort Funkelglanz in der brennenden Steppe die Abschrift der Schrifttafel.", progress = "Habt Ihr die Schriften der Sieben, {name}? Kennt Ihr jetzt die Geheimnisse dieser Schrifttafel?", completion = "Ah, Ihr habt die Schrifttafel gefunden! Und Eure Abschrift ist erstklassig! Seid Ihr sicher, dass Ihr ein {class} seid und kein Schreiber?\n\nHier, bitte sehr, {name}. Nehmt hier die Bezahlung, die ich Euch versprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[4297] = { id = 4297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen für das Baby", description = "Grimmlingflitzer sind Allesfresser - das bedeutet, dass sie sowohl Fleisch als auch Grünzeug fressen. Wenn dieses Junge hier schlüpft, sollten wir vorbereitet sein. Es ist kaum zu glauben, aber diese kleinen Kerlchen ernährt man am besten mit Fleischstücken, roh und saftig. Ich habe nie herausgefunden, warum das so ist, aber es muss wohl etwas mit Elunes Plan für die Elfen zu tun haben...vielleicht waren sie als Beschützer oder so etwas vorgesehen, ich weiß es nicht.\n\nIch kümmere mich vorerst um das Ei. Warum besorgt Ihr nicht ein paar Silbermähnenpirscherflanken, mit denen wir das Junge füttern können, sobald es geschlüpft ist?", sourceObjective = "Bringt Agnar Tiermeister im Hinterland 5 Silbermähnenpirscherflanken.", progress = "Habt Ihr das Fleisch, {name}? Euer Kleines hier wird bald schlüpfen. Wenn seine erste Mahlzeit nicht ausreicht, wird er die erste Woche vielleicht nicht überleben, und ich möchte nicht, dass das geschieht.\n\nIch will ehrlich zu Euch sein, {name}. Ich bin neidisch, weil Ihr so ein Ei habt und ich nicht. Und ich möchte es nicht bereuen, Euch hier ausgeholfen zu haben.", completion = "Das wird reichen, und wenn ich mich nicht irre, wird Euer Kleines bald schlüpfen. Wie ist das so? Ihr wisst schon, bald Vater zu sein? Haha, Ihr habt wohl nicht damit gerechnet, einmal solche Verantwortung übernehmen zu müssen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[4298] = { id = 4298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elternfreuden", description = "He, es war wohl schon weiter, als ich dachte...", sourceObjective = "Sprecht mit Agnar Tiermeister im Hinterland.", completion = "Hier, nehmt das Ei... besser, Ihr habt es in der Hand, damit das Junge gleich eine Bindung zu Euch aufbaut und glaubt, Ihr wärt sein Papa.\n\nGlückwunsch, {name}. Ihr habt jetzt ein Kind... sozusagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4300] = { id = 4300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenklingenwaffen", description = "Hmm, jetzt, wo ich darüber nachdenke, könnte es doch etwas geben, das Ihr für die Hand erledigen könntet. Ja, Jes'rimon könnte bestimmt Eure Hilfe brauchen.\n\nIm Krater von Un'Goro gibt es Raptoren mit tödlichen Klauen. Manche dieser Raptoren haben weiße Klauen statt schwarze wie der Tod. Die Mitglieder der Hand haben...Kunden..., denen aus diesen Klauen gefertigte Waffen gefallen. Bringt mir reichlich von diesen weißen Klauen, dann werde ich Euch gut entlohnen. Wenn Ihr das schnell genug tut, dann kann ich Euch vielleicht noch auf andere Weise helfen.", sourceObjective = "Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen.", progress = "Meine Kunden sind nicht sehr geduldig, {name}. Habt Ihr schon irgendwelche Klauen?", completion = "Ah, die sind hervorragend. Danke, {name}. Und Ihr seid zurück, bevor sie benötigt werden... sehr gut.\n\nVielleicht fertigen wir ja eine Waffe für Euch aus diesen Klauen an. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[4301] = { id = 4301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige U'cha", description = "Während Ihr Un'Goro erkundet habt, sind mir ein paar andere Dinge aufgefallen, die einem mächtigen Jäger wie Euch sicher gefallen würden. Zum Beispiel gibt es da einen gewaltigen Affen unter den Gorillas im Norden. Ihr seid schon einmal in dieser Höhle gewesen, aber dieses Mal frage ich mich doch, ob Ihr die Begegnung mit ihm wohl überleben würdet, solltet Ihr meine Aufgabe annehmen.\n\nIch nenne ihn U'cha und er ist einer der größten Söhne der Erdenmutter, da könnt Ihr sicher sein. Besiegt U'cha und bringt mir seinen Pelz. Wenn Euch das gelingt, habt Ihr das Recht darauf, ein großer Jäger genannt zu werden.", sourceObjective = "Bringt U'chas Pelz zu Torwa Pfadfinder am Eingang des Kraters von Un'Goro.", progress = "U'cha... was für ein großartiges Tier. Riesig und rot, mit Zähnen so lang wie Dolche. Arme so dick wie Baumstämme und so schnell wie der schnellste Berglöwe, den ich je gesehen habe. Ihr solltet Euch glücklich schätzen, ein solches Objekt für die Prüfung Eures Mutes vorzufinden - mein Volk hat seit Generationen keine derartige Kreatur mehr zu sehen bekommen.", completion = "Gut gemacht, {name}. Ich bin erfreut. Heute habt Ihr hier Großes geleistet.\n\nU'cha war einer der größten Affen, die ich je gesehen habe. Die Tatsache, dass Ihr seine Kraft bezwungen habt, zeugt von Eurer eigenen Kraft... und Eurem Mut.\n\nDaher ist es nur angemessen, dass ich Euch dies hier als Zeichen meines Respekts überreiche. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[4321] = { id = 4321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sache verstehen", description = "Die Information über die Pylonen, die Ihr mir gabt, ist sehr interessant...\n\nGebt mir einen Moment Zeit, um ein paar Berechnungen anzustellen, {name}. Sprecht mich demnächst noch einmal an, dann sollte ich Euch die Antwort geben können, nach der wir gesucht haben.", sourceObjective = "Sprecht demnächst mit J. D. Collie.", completion = "So, {name}. Das ist echt faszinierend... Ich kann nur hoffen, dass meine Diagramme korrekt sind! Ich habe alles in dieser Anleitung zusammengefasst, die ich Euch überlassen werde.\n\nJetzt sollte ich all Eure Fragen zu den Kristallen beantworten können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4322] = { id = 4322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängnisausbruch!", description = "Wir müssen hier weg, {name}. Helft mir, meine Ausrüstung aus dem Vorratsbereich zu holen und meine Freunde zu befreien. Falls wir hier rauskommen, dann müsst Ihr Euch weiter nach Morgans Wacht durchschlagen und mit Marschall Maxwell sprechen. Er wird Euch weitere Anweisungen geben.", sourceObjective = "Helft Marschall Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marschall Maxwell zurück, wenn Ihr Erfolg hattet.", completion = "Erstaunlich, {name}. Einfach erstaunlich. Windsor ist vor nicht einmal fünf Minuten hier durchgestürmt. Er spuckte große Töne, behauptete jedoch, alles mit Beweisen untermauern zu können. Jetzt ist er auf dem Weg nach Stormwind, um Bolvar und... Lady Prestor damit zu konfrontieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[4324] = { id = 4324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuka Schraubstutz", description = "Mein Bruder Ribbly war sein ganzes Leben lang zu nichts nütze; aber jetzt, glaube ich, hat er endlich einen gewissen Wert! Aber... wir werden Eure Hilfe brauchen, um aus Ribblys Wert Kapital zu schlagen.\n\nMeine Schwester Yuka hat ihn wochenlang gesucht und endlich in der brennenden Steppe gefunden. Sie hat mich wissen lassen, dass sie ein paar Helfer brauchen könnte.\n\nAlso, was meint Ihr? Wollt Ihr uns helfen? Falls ja, sprecht mit meiner Schwester. Ihr findet sie im Flammenkamm versteckt, in einer Höhle nordwestlich des Schreckensfelsens.", sourceObjective = "Sprecht mit Yuka Schraubstutz in der brennenden Steppe.", completion = "Ja, ich suche meinen Bruder. Wir müssen ihn finden und zurückbringen, gesegnet sei sein Herz.\n\nAber wenn wir ihn nicht im Ganzen zurückbringen können... dann reicht auch sein Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[4341] = { id = 4341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kharan Hammermacht", description = "Seid Ihr in den rauchenden Ruinen von Thaurissan gewesen? Seid Ihr dort zufällig einem erbärmlichen Tölpel namens Kharan Hammermacht begegnet? Dem Zwerg, der eigentlich über mein kleines Mädchen wachen sollte?\n\n<Der König schluchzt.>\n\nUnd jetzt ist sie verschwunden, {name}!\n\nIch habe meine Leute die gesamte Steppe durchkämmen lassen. Doch der einzige Hinweis, den sie über den Verbleib meiner Tochter finden konnten, war, dass sie vielleicht in den Tiefen ist. Möglicherweise ist sie sogar schon tot!\n\nAngeblich wird Kharan dort als Gefangener festgehalten...findet ihn! Ich will Antworten!", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und findet Kharan Hammermacht.\n\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten.", completion = "Bitte, lasst es mich erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[4342] = { id = 4342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kharans Geschichte", description = "Bitte hört mich an, ehe Ihr ein Urteil fällt!", sourceObjective = "Lasst Kharan Hammermacht seine Geschichte erzählen.", progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Wie Ihr seht, gab es nichts, was ich hätte tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[4343] = { id = 4343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4361] = { id = 4361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Überbringer schlechter Botschaften...", description = "Ihr müsst König Magni diese Informationen bringen, {name}. Er wird wissen, was zu tun ist!", sourceObjective = "Kehrt nach Eisenschmiede zurück und überbringt König Magni Bronzebart die schlechten Nachrichten.", completion = "<Wütend schlägt König Magni mit der Faust auf den Tisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4362] = { id = 4362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Königreichs", description = "Es scheint, als habe mein alter Widersacher, Dagran Thaurissan, mich und das ganze Königreich Eisenschmiede in seiner Gewalt.\n\nVielleicht seid Ihr meine letzte Hoffnung, {name}. Ihr müsst meine Tochter Moira retten!\n\nEs gibt nur einen Weg, wie der Zauber, mit dem Thaurissan Moira belegt hat, wirklich zuverlässig gebrochen werden kann: Ihr müsst ihn töten.\n\nAber, {name}, meiner Tochter dürft Ihr kein Leid zufügen! Vergesst nicht, dass sie Thaurissans Kontrolle unterliegt! Alles, was sie vielleicht sagt oder tut, geschieht aufgrund von Thaurissans bösem Zauber!", sourceObjective = "Kehrt in die Schwarzfelstiefen zurück und rettet Prinzessin Moira Bronzebart aus den Fängen des bösen Imperators Dagran Thaurissan.", completion = "<Prinzessin Bronzebeard weint bitterlich über den Verlust von Imperator Dagran Thaurissan.>\n\nWarum???", sourceObjectiveStatus = "unverified-source-field" }
quests[4363] = { id = 4363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überraschung der Prinzessin", description = "Thaurissan war ein großer und ehrenhafter Zwerg. Ihr habt mein Leben zerstört - meines und das meines ungeborenen Kindes!\n\n<Ihr habt den Eindruck, als leide Prinzessin Bronzebart noch immer unter den letzten Auswirkungen des vom Imperator gewirkten Zaubers.>\n\nKehrt nach Eisenschmiede zurück und sagt meinem Vater, dass der Erbe des Königreichs Eisenschmiede ein Dunkeleisenzwerg sein wird.\n\nOb er dies billigt oder nicht, so wird es sein.", sourceObjective = "Kehrt nach Eisenschmiede zurück und sprecht mit König Magni Bronzebart.", completion = "<König Magni Bronzebeard ist sichtlich erschüttert.>\n\nEs scheint, als habe Thaurissan gewonnen - sogar im Tode.\n\nIhr seid entlassen, {name}. Doch ehe Ihr geht, dürft Ihr Euch Eure Belohnung aus dem königlichen Gewölbe auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4381] = { id = 4381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallflicker", progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euch oder Eure Verbündeten heilen.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch." }
quests[4382] = { id = 4382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkraft", progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Geist steigern.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch." }
quests[4383] = { id = 4383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallbarriere", progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und rote Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Schutz vor körperlichem Schaden stärken.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch." }
quests[4384] = { id = 4384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallschwächer", progress = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination die Verteidigung eines Gegners schwächen.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch." }
quests[4385] = { id = 4385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallsprengladung", progress = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination eine starke Explosion auslösen, die Euren Feinden Schaden zufügt.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch." }
quests[4386] = { id = 4386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallspitze", progress = "Mit Hilfe der Pylon-Tafel könnt Ihr blaue und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination einen Schild erschaffen, der Euren Feinden Schaden zufügt.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch." }
quests[4401] = { id = 4401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4402] = { id = 4402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgars Kaktusapfel Surprise", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweíß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, {name}. Wenn Ihr mir 10 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", sourceObjective = "Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen.", progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, {name}! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[4403] = { id = 4403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4421] = { id = 4421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis der Jadefeuer", description = "Nicht viele kommen hierher und suchen das Abenteuer... Die Verderbnis hat sich im Teufelswald überall ausgebreitet und macht vor nichts Halt.\n\nAls Mitglied des Smaragdkreises trachte ich danach, dieses Land zu heilen. Doch es gibt andere, die wünschen, dass es weiter schwärt.\n\nIch spreche von den Jadefeuersatyrn, die sich nordwestlich von hier aufhalten, bei den Ruinen von Constellas. Ihr Anführer ist ein besonders grausamer Satyr namens Xavathras und unter seiner Führung übertragen sie die Krankheit auf alle Wesen, denen sie begegnen.\n\nWir müssen dieses Land, das einst das unsrige war, verteidigen. Besiegt Xavathras und vernichtet seine Diener.", sourceObjective = "Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Blauwind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", completion = "Den Teufelswald von Xavathras zu befreien, ist nur der erste Schritt auf einem langen Weg. Es wird viel Arbeit vonnöten sein, um den Schaden zu beheben, der hier angerichtet worden ist.\n\nIch spüre, dass hier mehr am Werk ist als nur die Satyrn allein, aber die Wahrheit werden wir wohl erst im Lauf der Zeit herausfinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[4441] = { id = 4441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebundene Urtume", description = "Die Flöte, die Ihr gefunden habt, wurde aus einem Urtumbeschützer geschnitzt, den Treantverbündeten, die schon immer treu über die Nachtelfen gewacht haben.\n\nEs ist den Satyrn gelungen, alles zu verderben, mit dem sie in Kontakt kommen, einschließlich der Urtume, die im Teufelswald lebten. Mit Hilfe der teuflischen Verderbnis wurde der Geist des Urtums gefangen und gefoltert und nie wieder völlig freigegeben. Der Teufelsbinder, den Ihr gefunden habt, hängt ganz ohne Zweifel damit zusammen.\n\nWir müssen versuchen, die Flöte zu läutern, {name}. Bringt mir gesegnetes Wasser vom Tempel des Mondes in Darnassus.", sourceObjective = "Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", progress = "Hoffentlich wird das Wasser den Geist des Urtums freisetzen, sodass er von nun an in Frieden ruhen kann.", completion = "Danke, {name}. Und jetzt müssen wir hoffen und beten, dass wir den Schaden beheben können, der hier angerichtet worden ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[4442] = { id = 4442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geläutert!", description = "Ich werde jetzt versuchen, die Flöte mit dem Wasser von Elune zu läutern. Wir müssen diesem Leiden ein Ende machen...\n\nMöge Elune meine Hände und mein Herz leiten.\n\nSprecht mich gleich noch einmal an.", sourceObjective = "Sprecht Eridan gleich noch einmal an.", completion = "Mit dem gesegneten Wasser konnte ich die Verbindung zwischen der Flöte und dem Geist des Urtums unterbrechen. Aber ich glaube, dass Ihr, wenn Ihr diese Flöte an einem heiligen Ort verwendet, vielleicht die Geister der Urtume beschwören könnt.\n\nIhr könntet es einmal in den Ruinen im südlichen Teil der Ruinen des Eisenwaldes versuchen. Einst bewohnten viele verderbte Treants diese Gegend und es ist möglich, dass sie sich noch immer dort aufhalten, und sei es auch nur in Geistgestalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4443] = { id = 4443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Peitscherwurzel", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
