quests[4447] = { id = 4447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Nachtdrache", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4448] = { id = 4448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Nachtdrache", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4449] = { id = 4449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingesperrt!", description = "He! He, Ihr da! Kommt her!\n\nIhr müsst mir dringend helfen. Ich bin vor den Dunkeleisenzwergen abgehauen und hab mich hier drin versteckt, damit se mich nich' sehen. Verdammte Drecksgeologen und ihre Magie! Die müss'n geseh'n haben, wie ich mich versteckt hab, weil als Allernächstes ham se die Tür versperrt. Ham was gesagt von wegen, dass sie zurückkommen und mich holen würden, und dann sind sie verschwunden.\n\nIhr müsst denen zeigen, wer hier der Boss ist! Könnt Ihr das für mich tun? Verpasst den Geologen 'ne Lektion! Ach, und könnt Ihr mir 'n paar Stücke Seidenstoff beschaffen für...für...ach, für nix.", sourceObjective = "Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", progress = "Ich hab nicht ewig Zeit! Beschafft mir schon diese Stücke Seidenstoff! Äh, Geologen. Ich meine Geologen. Schnappt Euch diese Geologen! Sie verdienen es, meinen... na ja, Euren Zorn zu spüren.", completion = "Oh, toll! Fühlt sich auch klasse an!\n\nWas? Ach ja... die Geologen. Denen habt Ihr's gehörig gezeigt, was? Ich kann Euch gar nich' genug danken, {name}. So hab ich 'n bisschen Zeit, hier drin alles fertig zu machen... Äh, ich meine natürlich, jetzt muss ich mir erst mal keine Sorgen machen, dass die so schnell wiederkommen. Also, nochma' danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[4450] = { id = 4450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschäftsbuch aus Tanaris", description = "Ach, wisst Ihr was? Da fällt mir grade was ein.\n\nWo ich doch immer noch hier drin festsitz: Wollt Ihr nich' vielleicht 'n kleinen Job für mich fertig machen, den ich angenommen hab, als ich in Tanaris war? Is' auch ganz einfach... na ja, wenn man nich' grade hier drin sitzt, jedenfalls.\n\nKrinkle Goldstahl in Gadgetzan war scharf auf so'n paar Sachen, die hier in der sengenden Schlucht und an 'n paar anderen Orten gefunden wurden. Vielleicht könnt Ihr Euch ja die Liste einmal ansehen und ihm den Kram dann bringen?\n\nIch schieb Euch sein Geschäftsbuch unter der Tür durch, wenn Ihr interessiert seid. Bringt es ihm zusammen mit dem Zeug, das er will, nachdem Ihr den ganzen Kram eingesammelt habt.", sourceObjective = "Nehmt die Abschrift von Goldstahls Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goldstahl in Tanaris aufsucht.", progress = "Ja, bitte? Was kann ich für Euch tun, {race}? Ich bin fürchterlich beschäftigt und viele Kunden warten auf meine Dienste. Vielleicht könnt Ihr Euch ein wenig beeilen? Ich will ja nicht unhöflich sein, aber ich habe einfach keine Zeit - nicht, wenn ich mit all meiner Arbeit fertig werden möchte.", completion = "Oh, wie ich sehe, habt Ihr es für angebracht gehalten, einen Teil der Arbeit zu erledigen, um die ich gebeten hatte. Ausgezeichnet. Und ich dachte schon, Ihr wolltet, dass ich etwas für Euch fertige.\n\nDie sind alle perfekt... und es ist auch alles da. Danke, {class}.\n\nEs kann vermutlich nichts schaden, Euch mit etwas zu belohnen... hmm, was würdet Ihr als nützlich erachten?", sourceObjectiveStatus = "unverified-source-field" }
quests[4451] = { id = 4451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zur Freiheit", description = "Der kleine Messingschlüssel sieht recht einfach aus. Das Einzige, was ihn von anderen seiner Art unterscheidet, sind einige Worte, die darauf eingeritzt sind:\n\n\"Dunkeleisenplumpsklo - Nicht duplizieren\".\n\nIhr habt absolut keine Ahnung, was das heißen soll oder wofür der Schlüssel gut ist.", sourceObjective = "Sucht in der sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel für Rußschlacks Schuppen verwenden kann, den Ihr gefunden habt.", progress = "*hust*\n\nWer is' da? Seht Ihr nich', dass ich beschäftigt bin?", completion = "Da brat mir doch einer... Wie, zum Geier... !? Ihr habt den Schlüssel gefunden! Ich wusste, dass die verdammten Dunkeleisenzwerge ihn versteckt ham, nachdem se mich hier eingesperrt hatten! Vielsten Dank, {name}. Ihr seid echt Spitze! Na, dann dreht jetzt mal den Schüssel rum und lasst den alten Locheed hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[4461] = { id = 4461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Peitscherwurzel", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4462] = { id = 4462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Nachtdrache", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4463] = { id = 4463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband des Nachsinnens", progress = "Übergebt mir die Komponenten, sterbliches Geschöpf.\n\nDes Weiteren benötige ich Bezahlung in Gestalt von dreißig Goldstücken für diese Schöpfung.", completion = "Nehmt den Plunder, Dummkopf. Und verlasst mich, damit ich mich meinen Studien widmen kann!" }
quests[4464] = { id = 4464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4465] = { id = 4465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4466] = { id = 4466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4467] = { id = 4467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[4481] = { id = 4481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband der Konstitution", progress = "Für jedes Ding auf dieser Welt gilt es, einen Preis zu bezahlen. Und der Preis für den speziellen Gegenstand, den Ihr wünscht, beläuft sich auf dreißig Goldstücke.\n\nSelbstverständlich werde ich den Großteil der Komponenten, die Ihr eingesammelt habt, für mich selbst zurückbehalten. Doch sorgt Euch nicht, Ihr sollt Euren Plunder erhalten.", completion = "Es ist eine Schande für sein Andenken... dass ein sterbliches Geschöpf wie Ihr seine Lebensaufgabe vollendet!\n\nNehmt Euer Gemisch und hebt Euch hinfort!" }
quests[4482] = { id = 4482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband der Hartnäckigkeit", progress = "Dreißig Goldstücke, {race}. Dreißig Goldstücke und die benötigten Komponenten.", completion = "Es hat Kariel mehrere Eurer Lebensspannen gekostet, den Buchband fertig zu stellen, den Ihr jetzt in der Hand haltet, {race}. Und wozu das alles? Damit sein Jünger in der brennenden Steppe stehen und seine Forschungen missbrauchen kann, um ein unendliches Verlangen nach dem Arkanen zu befriedigen ... Verflucht sei diese elende Sucht.\n\nEuer Mangel an Mitgefühl und Eure unstillbare Gier ekeln mich an. Hinfort mit Euch!" }
quests[4483] = { id = 4483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband der Abhärtung", progress = "Wenn es Widerstandsfähigkeit ist, die Ihr wünscht, so benötige ich dreißig Goldstücke.", completion = "Auch andere Buchbände sind in dieser Welt verloren gegangen. Verloren an Orten, die zu betreten Ihr nie wagen würdet. Orte, die Euch beten lassen würden, dass es sie nicht gibt.\n\nIch werde die Energien dieser Komponenten in mich aufsaugen. Und Ihr werdet die überschüssigen Rückstände erhalten..." }
quests[4484] = { id = 4484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband der Gier", progress = "Vergeudet meine Zeit nicht, {race}. Gebt mir das, was ich benötige. Dreißig Goldstücke und die Komponenten.", completion = "Mein Kopf hämmert... Die Energien der unendlichen Weiten, die unser Universum ausmachen... ARGGH!\n\n<Mathredis scheint große Schmerzen zu haben.>\n\nNehmt, was Ihr wünscht, und geht!" }
quests[4485] = { id = 4485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant des Adels", description = "Hallo, {name}. Wie ich sehe, ist Eure Hingabe weiterhin stark, ebenso wie Euer Glaube.\n\nIch denke, es ist an der Zeit, dass Ihr mit Duthorian Rall in Sturmwind sprecht. Es gibt noch einige Lektionen, die Ihr lernen müsst, und ich spüre, dass Ihr dazu bereit seid.\n\nSucht ihn in der Kathedrale des Lichts auf... und, {name}, nehmt diese Lektionen ernst! Ihr habt Euren derzeitigen Rang durch harte Arbeit und Demut erreicht, enttäuscht uns jetzt nicht, indem Ihr überheblich werdet.\n\nGehabt Euch wohl.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[4486] = { id = 4486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant des Adels", description = "Nee, nee, nee. Jetzt sieh sich nur mal einer den mächtigen Paladin in all seinem Glanz an.\n\nTut mir leid, {name}, war nicht böse gemeint... Ich werde nur manchmal ein bisschen neidisch, wenn ich sehe, was Ihr für tolle Taten vollbracht habt. Tiza hat gesagt, das sei meine Schwäche, und ich habe ihr geschworen, dass ich daran arbeiten würde. Aber manchmal ist das einfach schwer, wisst Ihr.\n\nAber der Grund, warum ich mit Euch sprechen wollte, war, dass Duthorian Rall in Sturmwind gesagt hat, Ihr solltet ihn in der Kathedrale des Lichts treffen, wenn Ihr bereit seid. Klang ziemlich wichtig. Klang, als sei irgendwas los.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "Ah, Ihr seid zur Kathedrale zurückgekehrt, {name}. Gut. In letzter Zeit ist viel geschehen und ich würde mich gern Eurer Hilfe versichern, solltet Ihr Euch würdig erweisen.\n\nEs gehen viele verräterische Feinde um. Ich werde Eure Hilfe benötigen, um sie aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[4487] = { id = 4487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsross beschwören", description = "Ah, gut, da seid Ihr ja. Ich habe Euch <einen Sukkubus/eine Höllenbestie> hinterhergeschickt, um Eure Aufmerksamkeit zu erregen, aber es scheint, als sei es Euch gelungen herzukommen, ehe <er/sie> Euch gefunden hat. Einerlei.\n\nIn letzter Zeit gab es einiges an Gerede über Eure wachsende Macht - das ist gut für Euch und möglicherweise schlecht für andere. Doch das sind alles Nebensächlichkeiten. Wichtig ist nur, dass ich denke, dass Ihr Euch bewiesen habt und deswegen... hihi... einen gewissen Segen verdient.\n\nOberhalb von Ratschet im Brachland findet Ihr einen Mann namens Strahad. Ich glaube, Eure Wege haben sich bereits gekreuzt.", sourceObjective = "Sprecht mit Strahad Farsan in Ratschet.", completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4488] = { id = 4488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsross beschwören", description = "Ah, {name}, wie ich sehe, beehrt Ihr uns mit Eurer Anwesenheit. Wie wunderbar!\n\nIch hoffe, Ihr erwartet nicht auch noch, dass wir Euch von Kopf bis Fuß bedienen. Ihr mögt ja vielleicht schnell an Macht gewinnen, doch Ihr seid noch immer ein Kleinkind, was das wahre Wissen und das wahre Verständnis angeht. Wenn Ihr nicht aufpasst, wird die Verderbnis Euch und Euren schwachen Willen überwältigen.\n\nAber ich sollte zum Thema kommen: Strahad möchte mit Euch sprechen. Er wohnt noch immer im Brachland in seinem Turm, der Ratschet überblickt. Ich schlage vor, Ihr säumt nicht zu lange.", sourceObjective = "Sprecht mit Strahad Farsan in Ratschet.", completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4489] = { id = 4489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsross beschwören", description = "Ihr da, {race}! Kommt her!\n\nIhr werdet {name} gerufen, nicht wahr?\n\nDas habe ich mir gedacht. Ich fasse mich kurz: Ihr gewinnt an Macht und das ist nicht unbeobachtet geblieben. Und nun ist die Zeit gekommen, dass Ihr für Eure Anstrengungen belohnt werdet.\n\nBegebt Euch ins Brachland. Oberhalb von Ratschet findet Ihr dort Strahad Farsan - vielleicht erinnert Ihr Euch an ihn? Er möchte mit Euch sprechen. Ich würde nicht säumen.", sourceObjective = "Sprecht mit Strahad Farsan in Ratschet.", completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4490] = { id = 4490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsross beschwören", description = "Ich möchte Euch eine Belohnung für Eure Geduld und Eure harte Arbeit geben. Doch wisset, dass sich die Fähigkeit, ein Teufelsross zu beschwören, in Zukunft wesentlich schwieriger gestalten wird. Ihr müsst sie Euch verdienen - und es wird nicht leicht sein.\n\nDoch geht nun fürs Erste, nehmt die Macht mit Euch, eine solche Kreatur zu beschwören, und verwendet diese Macht, wie Ihr es für richtig haltet.", sourceObjective = "Sprecht in Ratschet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört.", completion = "Viel Glück, {name}. Ich freue mich schon darauf, Euch in der Zukunft wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4491] = { id = 4491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Hilfe von guten Freunden", description = "Argh... es ist so heiß...\n\nIch war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Ich muss wohl einen Hitzschlag haben.\n\nBitte, bringt mich zu meinem Freund Spraggel in Marschalls Zuflucht zurück. Ich glaube, es geht mir noch gut genug, um Euch dorthin zu folgen.\n\nAber ich fühle mich ziemlich schwach. Wenn ich also noch mal in Ohnmacht fallen sollte, dann bespritzt mich einfach mit etwas Wasser aus Spraggles Feldflasche. Das sollte helfen, hoffe ich...", sourceObjective = "Führt Ringo zu Spraggel Frock in Marschalls Zuflucht.\n\nFalls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben.", completion = "Ringo ist in keiner besonders guten Verfassung, {name}, aber ich bin froh, dass ich ihn in einem Stück zurückhabe.\n\nDanke, dass Ihr ihn gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4492] = { id = 4492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren!", description = "Ihr müsst mir helfen, {name}! Mein Freund Ringo ist vor einer Weile aufgebrochen, um den Vulkan südlich von hier zu erforschen, und er ist schon viel zu lange weg. Ich mache mir große Sorgen um ihn.\n\nMeint Ihr, Ihr könnt ihn suchen? Nehmt doch meine Feldflasche mit - wenn Ihr Ringo tatsächlich findet, dann hat er sie bestimmt nötig!", sourceObjective = "Sucht Ringo am Feuersäulengrat.", progress = "Wa... Was?", completion = "Oh... Ich bin ja so froh, dass mich jemand gefunden hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[4493] = { id = 4493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Marsch der Silithiden", description = "Es scheint, als sei es die Absicht der Silithiden - nein, ihr ganzer Lebenszweck! -, alles zu verschlingen, was ihnen im Weg steht und was nicht zu ihrer eigenen Ökologie gehört. Nur darauf konzentrieren sie sich und darum stellen sie eine große Gefahr für alles Leben auf Azeroth dar.\n\nBis jetzt haben wir nur die Anfänge gesehen. Ich vermute, dass sie ihre Kraft aus einem Ort tiefer drinnen in Kalimdor beziehen: aus dem Krater von Un'Goro. Geht nach Gadgetzan in der Tanariswüste und sprecht mit Alchimist Stößelbruch. Erzählt ihm von meiner Theorie; er wird uns bestimmt dabei helfen, die Silithiden zu bekämpfen.", sourceObjective = "Sprecht in Gadgetzan mit Alchimist Stößelbruch.", completion = "Ja, ich habe vermutet, dass Gracina Euch zu mir geschickt hat. Eure Erfahrung im Kampf gegen diese Biester ist unschätzbar wertvoll - meines Wissens nach hat bisher niemand sonst mit dieser Spezies zu tun gehabt. Was Gracinas Idee betrifft, dass sie aus dem Un'Goro Krater kommen... vielleicht tun sie das tatsächlich. Der Un'Goro ist ein geheimnisvoller und gefährlicher Dschungel westlich von hier. Vielleicht ist er auch der nächste Schritt auf dem Weg herauszufinden, was es mit den Silithiden auf sich hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[4494] = { id = 4494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Marsch der Silithiden", description = "Es scheint, als sei es die Absicht der Silithiden - nein, ihr ganzer Lebenszweck! -, alles zu verschlingen, was ihnen im Weg steht und was nicht zu ihrer eigenen Ökologie gehört. Nur darauf konzentrieren sie sich und darum stellen sie eine große Gefahr für alles Leben auf Azeroth dar.\n\nBis jetzt haben wir nur die Anfänge gesehen. Ich vermute, dass sie ihre Kraft aus einem Ort tiefer drinnen in Kalimdor beziehen: aus dem Krater von Un'Goro. Geht nach Gadgetzan in der Tanariswüste und sprecht mit Alchimist Stößelbruch. Erzählt ihm von meiner Theorie; er wird uns bestimmt dabei helfen, die Silithiden zu bekämpfen.", sourceObjective = "Sprecht in Gadgetzan mit Alchimist Stößelbruch.", completion = "Ja, ich habe vermutet, dass Zilzibin Euch zu mir geschickt hat. Eure Erfahrung im Kampf gegen diese Biester ist unschätzbar wertvoll - meines Wissens nach hat bisher niemand sonst mit dieser Spezies zu tun gehabt. Was Zils Idee betrifft, dass sie aus dem Un'Goro Krater kommen... vielleicht tun sie das tatsächlich. Der Un'Goro ist ein geheimnisvoller und gefährlicher Dschungel westlich von hier. Vielleicht ist er auch der nächste Schritt auf dem Weg herauszufinden, was es mit den Silithiden auf sich hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[4495] = { id = 4495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Freund", description = "Ich habe einen Freund, Iverron, der mich normalerweise jeden Tag um dieselbe Zeit besucht. Komischerweise ist er heute noch nicht da gewesen - genau genommen ist er sogar schon etliche Stunden über seiner sonstigen Zeit.\n\nIch muss zugeben, ich bin etwas besorgt, {name}. Iverron verbringt viel Zeit bei der Spinnenhöhle oben im Norden und ich bin sicher, Ihr wisst, wie gefährlich es dort ist - überall Spinnen!\n\nFalls Ihr zufällig dort vorbeikommen solltet, könntet Ihr dann nach ihm Ausschau halten?", sourceObjective = "Sucht Iverron an der Höhle im Norden.", completion = "Ich bin ja so froh, dass Ihr mich gefunden habt, {name}. Woher habt Ihr gewusst, dass ich hier bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[4496] = { id = 4496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dschungelei", description = "Meine Forschungen haben ergeben, dass die Silithiden den Bienen ähneln: Wenn man die Königin des Schwarmbaus tötet, dann sollte das den Rest in völliges Chaos stürzen. Ich werde einen Köder brauen, mit dem wir die Königin herauslocken können, und sobald sie draußen ist, streckt Ihr sie nieder.\n\nDoch zuerst brauchen wir einige Reagenzien; wir wollen doch nicht, dass Ihr völlig unvorbereitet im Dschungel umherstolpert. Geht nach Westen, sucht den Schwarmbau der Silithiden im Krater von Un'Goro und beschafft Euch eine Duftdrüse von einem der Viecher. Außerdem brauche ich einige Erdproben von Un'Goro.", sourceObjective = "Bringt eine Gorishiduftdrüse und 5 Erdproben von Un'Goro zu Alchimist Stößelbruch in Gadgetzan.", progress = "Eine geeignete Duftdrüse zu finden, könnte einige Zeit in Anspruch nehmen - die Drüse darf nicht beschädigt sein und das wird durch die Art und Weise, wie Ihr sie Euch beschaffen müsst, nicht gerade erleichtert. Was die Erdproben angeht, so denke ich, dass die sich ziemlich leicht finden lassen sollten.\n\nNun, wie dem auch sei - habt Ihr die Gegenstände, die ich brauche, um den Köder herzustellen?", completion = "Die Duftdrüse, ah ja. Die Membran scheint intakt zu sein - ausgezeichnet. Die Erde... ja, die ist genau richtig. Und jetzt sollte ich in der Lage sein, mit meinen besonderen Zutaten all dies zum perfekten Köder zu verarbeiten.\n\nGebt mir einen Moment Zeit, um den Köder herzustellen, {name}. Sobald er fertig ist, können wir den nächsten Schritt unternehmen, der hoffentlich die Silithiden aufhält, bevor sie Gadgetzan überrennen - und den Rest von Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[4501] = { id = 4501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht, Pterrordax!", description = "Gesucht: Ein fähiger Kämpfer, der sich der Bedrohung durch die Pterrordax im Krater von Un'Goro annimmt. Ihre Zahl wächst ständig und sie werden zu einer Bedrohung für die Reisenden in der Gegend.\n\nDezimiert den Bestand, indem Ihr 10 Pterrordax und 15 rasende Pterrordax tötet.\n\nSprecht mit Spraggel Frock, nachdem Ihr die Aufgabe erledigt habt, dann erhaltet Ihr eine Belohnung.", sourceObjective = "Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggel Frock in Marschalls Zuflucht.", completion = "Ich habe schreckliche Angst vor den Pterrordax hier! Danke, dass Ihr ihre Anzahl reduziert habt, {name}. Vielleicht fühle ich mich jetzt wieder sicher genug, um mich aus Marshals Zuflucht herauszutrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4502] = { id = 4502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulkanische Aktivität", description = "Als Lehrling von Marvon Nietensucher habe ich unglaublich viel gelernt. Aber er ist jetzt schon sehr lange fort. Daher denke ich, werde ich an ein paar eigenen Experimenten arbeiten.\n\nIch habe kürzlich etwas über den Krater von Un'Goro gelesen und über die eigentümliche Vulkanaktivität, die in der Mitte des Kraters zu erkennen ist. Ich glaube, ich könnte eine Menge lernen, wenn ich nur etwas Asche von den Elementaren dort haben könnte.\n\nWürde es Euch etwas ausmachen, etwas Asche für mich einzusammeln, falls Ihr dort entlangkommen solltet?", sourceObjective = "Sammelt 9 Proben der Asche von Un'Goro von den Feuerelementaren am Vulkan im Krater von Un'Goro ein und bringt die Proben zu Liv Ritzelflick in Ratschet.", progress = "Stimmt es, dass der Vulkan im Un'Goro aktiv ist? Ich bin sicher, ich könnte eine Menge aus der Asche des Vulkans lernen, {name}.", completion = "Diese Proben sind einfach perfekt für meine Studien! Danke, {name}! Ich verspreche auch, dass ich Euch als Erstem von meinen Ergebnissen berichten werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[4503] = { id = 4503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sappalots Flieger", description = "Ich baue einen Flugapparat!\n\nIch bin hier gestrandet und habe leider absolut überhaupt keinen Orientierungssinn. Ich würde ja einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Viecher jagen mir einfach eine höllische Angst ein.\n\nAlso, werdet Ihr mir helfen? Ich muss nur noch die Flügel bauen und ich glaube, dass sich die eingesponnenen Schuppen von Pterrordax und Dimetrodons perfekt dafür eignen würden. Ich werde mich zwar garantiert nicht mit denen anlegen, aber Ihr seht ziemlich zäh aus. Wollt Ihr es nicht versuchen?", sourceObjective = "Sammelt 8 eingesponnene Dimetrodonschuppen und 8 eingesponnene Pterrordaxschuppen für Sappalot in Marschalls Zuflucht.", progress = "Jedes berühmte Fahrzeug braucht einen Namen. Ich dachte, ich nenne es... Pwned!", completion = "Ja, diese Schuppen sind perfekt. Mit diesen Schuppen kriege ich meinen Flieger bestimmt in die Luft!\n\nDanke!", sourceObjectiveStatus = "unverified-source-field" }
quests[4504] = { id = 4504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superkleber", description = "Ich bin immer auf der Suche nach neuen Methoden, um schnelles Gold zu verdienen, {name}. Wenn Ihr mir bei meiner neuesten Idee helft, dann gebe ich Euch ein bisschen was vom Gewinn ab. Na, was sagt Ihr dazu?\n\nDas hab ich mir gedacht!\n\nGeht zu den Teergruben im Norden des Kraters von Un'Goro und beschafft mir etwas Teer. Aber nicht jeden x-beliebigen Teer, versteht Ihr? Ihr müsst den von den Kreaturen nehmen, die an den Teergruben leben. Normaler Teer ist einfach nicht klebrig genug.\n\nDie pflanzenartigen Kreaturen jedoch haben Chlorophyll in ihrer Haut, und wenn man das mit dem Teer mischt, dann wird das superklebrig!", sourceObjective = "Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan.", progress = "Und Tran'rek hat es wieder einmal geschafft - dieser Superkleber wird der letzte Schrei!", completion = "Ja, dieser Teer ist genau richtig...\n\nHe, Moment mal, meine Hände! Ich krieg sie nicht mehr auseinander...\n\nVielleicht war das doch keine so gute Idee. Oh, wartet mal! Superklebeteerentferner! Da steckt das wahre Geld drin!", sourceObjectiveStatus = "unverified-source-field" }
quests[4505] = { id = 4505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brunnen der Verderbnis", description = "Manche Leute sagen vielleicht, ich sei außergewöhnlich grausam... Aber in Wirklichkeit bin ich doch nur von dem Wunsch beseelt zu sehen, wie die Horde einen Vorteil gegenüber der Allianz erringt, und zwar auf jede nur mögliche Weise.\n\nSeit kurzem interessiere ich mich für einen Mondbrunnen in den Ruinen von Constellas. Er soll südlich von hier liegen und von den Jadefeuersatyrn gepflegt werden. Der Mondbrunnen, der einst ein Symbol der Erneuerung für die unerträglichen Nachtelfen war, ist jetzt verderbt und wird dazu benutzt, neue Satyrn hervorzubringen.\n\nIch habe da eine Idee, {name}, und ich hätte gern eine Probe von dem Wasser... für meinen kleinen Katzenfreund hier.", sourceObjective = "Beschafft eine Probe verderbten Wassers vom Mondbrunnen der Jadefeuersatyrn und bringt sie zu Winna Hazzard am Blutgiftposten.", progress = "Das ist von äußerster Wichtigkeit. Macht Euch jetzt auf den Weg.", completion = "Wohlan denn. Wir müssen einen Weg finden, diese Verderbnis gegen unsere Feinde einzusetzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[4506] = { id = 4506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Säbler", description = "Dieses verderbte Wasser können wir zu unserem Vorteil verwenden, {name}. Mit nur einer kleinen Menge Wasser wurde mein Kätzchen doppelt so groß und scheint jetzt irgendwie... stärker als vorher zu sein. Solche Katzen könnten sich noch als nützlich erweisen...\n\nHier, {name}. Nehmt diesen Katzentransportkorb und lasst das Kätzchen darin neben dem Mondbrunnen in den Ruinen von Constellas frei. Hi, hi... Ich bin mir sicher, das Ergebnis wird Euch gefallen!\n\nBringt mir danach die Katze zurück, dann werde ich mich für Eure Zeit und Mühe erkenntlich zeigen.", sourceObjective = "Bringt Winnas Kätzchen zum verderbten Mondbrunnen, lasst es dort frei und bringt es dann wieder zu Winna zurück.\n\nSobald Ihr wieder bei Winna seid, klickt auf die Katze, um sie Winna zu übergeben.", progress = "Jetzt sagt mir nicht, dass Ihr nicht dorthin zurückgehen könnt! Geht schon!", completion = "Exzellent!\n\nDen Verlassenen ist jedes Mittel recht, um die Allianz zu zerschmettern! Das verderbte Wasser wird sich in Zukunft sicherlich noch als nützlich für unsere weiteren Bemühungen erweisen...", sourceObjectiveStatus = "unverified-source-field" }
quests[4507] = { id = 4507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer schlägt Dame", description = "Hier ist der Köder. Im Schwarmverbund sollte sich eine Art von Kristall befinden. Wir glauben, dass die Silithiden den Kristall als eine Art Einstellungsgerät verwenden, das den ganzen Schwarmbau miteinander verbindet. Wo sich dieser Kristall befinden könnte, wollt Ihr wissen? Ich würde vorschlagen, Ihr versucht es in der Brutstätte innerhalb des Schwarmbaus.\n\nWenn Ihr den Köder bei dem Kristall benutzt, sollte das die Königin aufscheuchen, aber seid gewarnt - sie ist wahrscheinlich von mehreren Wachen umgeben. Schaltet die Königin aus und entfernt ihr Gehirn. Ich weiß, das klingt eklig, aber wir müssen es unbedingt untersuchen. Viel Glück, {name}!", sourceObjective = "Besiegt die Schwarmkönigin der Gorishi, sobald sie erscheint.\n\nBringt das Gehirn der Schwarmkönigin zu Alchimist Stößelbruch nach Gadgetzan.", progress = "Es ist von absoluter Wichtigkeit, dass wir das Gehirn der Königin für unsere Forschungen in die Hände bekommen. Das, was wir bisher in Erfahrung bringen konnten, lässt uns glauben, dass die Silithiden möglicherweise von einer bösartigen Intelligenz kontrolliert werden. Ich wage gar nicht daran zu denken, wer oder was etwas so Heimtückisches wie die Silithiden kontrollieren könnte, {name}.", completion = "Phantastisch, {name}! Wir haben hier und heute einen sehr bedeutsamen Sieg errungen. Es wird einige Zeit dauern, bis wir vollständig verstehen, was genau wir hier haben; aber wir werden das Beste daraus machen, nur keine Sorge.\n\nWas die Silithiden angeht, so glaube ich kaum, dass wir sie bereits in ihrer Gänze gesehen haben. Diese Lösung war zu sauber, es tut mir Leid, das sagen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4508] = { id = 4508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "Meine jüngsten Ergebnisse und das Wissen, das wir heute hier gesammelt haben, müssen in die Hände von Leuten gelangen, die etwas damit anfangen können. So einfallsreich wir hier in Gadgetzan auch sein mögen, das hier können wir nicht allein schaffen.\n\nBringt meinen jüngsten Bericht zu Gracina Glaubensmacht nach Darnassus; sie hält sich doch immer noch im Tempel des Mondes auf, oder? Sie hat Freunde, und zwar ziemlich hohe Tiere innerhalb der Allianz; wenn wir die in diese Sache mit hineinziehen können, {name}, dann haben wir vielleicht eine Chance, dies alles zu überleben.", sourceObjective = "Bringt Stößelbruchs Bericht von Un'Goro zu Gracina Glaubensmacht in Darnassus.", progress = "Es sind alles Dummköpfe, {name}! Sie würden niemals über den eigenen Tellerrand schauen, ob es nicht irgendwo eine größere Bedrohung geben könnte - ihr blinder Hass auf die Horde wird noch unser aller Ende bedeuten! Ich weiß nicht, was ich ihnen noch als Beweis für die Silithidenbedrohung liefern soll - ich kann sie doch nicht in einen der Schwarmbauten werfen, damit sie es mit eigenen Augen sehen!\n\nAber entschuldigt ... Ihr habt Neuigkeiten für mich?", completion = "Ich weiß dies zwar wirklich zu schätzen, aber leider bin ich mir nicht sicher, ob es uns irgendetwas bringen wird. Die Allianz ignoriert alle Bedrohungen, die nicht von der Horde ausgehen, und sogar unsere eigenen Anführer hier in Darnassus können sich nicht darauf einigen, was diese Bedrohung eigentlich ist. Narren wie Fandral Staghelm sind der Ansicht, dass die Silithiden längst nicht die Gefahr aus der Vergangenheit darstellen, für die ich sie halte. Seine Unwissenheit wird nur noch von seiner Arroganz übertroffen.\n\nIhr habt die Bedrohung doch selbst gesehen, {name}. Wir müssen weiterhin alles tun, um die Silithiden zu besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[4509] = { id = 4509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "Meine jüngsten Ergebnisse und das Wissen, das wir heute hier gesammelt haben, müssen in die Hände von Leuten gelangen, die etwas damit anfangen können. So einfallsreich wir hier in Gadgetzan auch sein mögen, das hier können wir nicht allein schaffen.\n\nBringt meinen jüngsten Bericht zu Zilzibin Tomtom nach Orgrimmar; er lebt doch immer noch im oberen Teil der Gasse, oder? Er hat Freunde ziemlich weit oben in der Horde; wenn wir die mit in diese Sache hineinziehen können, {name}, dann haben wir vielleicht eine Chance, dies alles zu überleben.", sourceObjective = "Bringt Stößelbruchs Bericht von Un'Goro zu Zilzibin Tomtom in Orgrimmar.", progress = "Es sind alles Dummköpfe, {name}! Sie würden niemals über den eigenen Tellerrand schauen, ob es nicht irgendwo eine größere Bedrohung geben könnte - ihr blinder Hass auf die Allianz wird noch unser aller Ende bedeuten! Ich weiß nicht, was ich ihnen noch alles als Beweis für die Silithidenbedrohung liefern soll - ich kann sie doch nicht in einen der Schwarmbauten werfen, damit sie es mit eigenen Augen sehen!\n\nAber entschuldigt ... Ihr habt Neuigkeiten für mich?", completion = "Ich weiß dies zwar wirklich zu schätzen, aber leider bin ich mir nicht sicher, ob es uns irgendetwas bringen wird. Die Horde ignoriert alle Bedrohungen, die nicht von der Allianz ausgehen. Während Thrall selbst vielleicht sogar handeln würde, wenn ihm die Fakten vorgelegt würden, so wird er doch von allen Seiten mit widersprüchlichem Rat bestürmt. Wenn es nach diesen Narren ginge, dann müssten wir uns pausenlos im Kreis drehen, wenn sie nur der Meinung wären, dass wir der Allianz damit schaden könnten!\n\nIhr habt die Bedrohung doch selbst gesehen, {name}. Wir müssen weiterhin alles tun, um die Silithiden zu besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[4510] = { id = 4510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "{name}, Eure Hilfe war wirklich unschätzbar wertvoll. Es wird zweifellos der Moment kommen, an dem ich erneut um Euren Beistand im Kampf gegen die Silithiden bitten muss. Wir müssen erst verarbeiten, was wir im Krater von Un'Goro gelernt haben - ich fürchte, dass meine ursprüngliche Annahme, die Silithiden kämen aus dem Un'Goro, falsch war... dass an einem anderen Ort tatsächlich eine wesentlich stärkere Präsenz existiert.\n\nBringt diese Nachricht zu Idriana in der Bank. Sie wird Euch etwas aus meinem Gewölbe geben, das Ihr als Zeichen meiner Dankbarkeit ansehen sollt. Ich danke Euch für Eure mutige Unterstützung, {class}.", sourceObjective = "Bringt den Bankgutschein zu Idriana in der Bank von Darnassus.", progress = "Elune'adore, {class}. Was kann ich heute für Euch tun?", completion = "Dieser Bankgutschein ermächtigt mich, einen Gegenstand aus Gracina Spiritmights Konto bei uns zu entnehmen und Euch zu übergeben. Es scheint, als seien Glückwünsche angebracht!", sourceObjectiveStatus = "unverified-source-field" }
quests[4511] = { id = 4511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "{name}, ohne Euch wären wir niemals so weit gekommen. Es wird zweifellos der Moment kommen, an dem ich erneut um Eure Hilfe im Kampf gegen die Silithiden bitten muss. Wir müssen erst verarbeiten, was wir im Krater von Un'Goro gelernt haben - ich fürchte, dass meine ursprüngliche Annahme, die Silithiden kämen aus dem Un'Goro, falsch war... dass an einem anderen Ort tatsächlich eine wesentlich stärkere Präsenz existiert.\n\nBringt diese Nachricht zu Karus in der Bank. Er wird Euch etwas aus meinem Gewölbe geben, das Ihr als Zeichen meiner Dankbarkeit ansehen sollt. Danke für Eure tatkräftige Unterstützung, {class}.", sourceObjective = "Bringt den Bankgutschein zu Karus in der Bank von Orgrimmar.", progress = "Zug-zug! Wie kann ich Euch heute helfen, {class}?", completion = "Dieser Bankgutschein ermächtigt mich, einen Gegenstand aus Zilzibin Drumlores Konto bei uns zu entnehmen und Euch zu übergeben. Es scheint, als seien Glückwünsche angebracht!", sourceObjectiveStatus = "unverified-source-field" }
quests[4512] = { id = 4512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brühschlammer auf Abwegen", description = "Aber womit ich mich am meisten beschäftigt habe, das sind die Brühschlammer. Ich weiß, das klingt seltsam, aber die sind wirklich überall!\n\nVor kurzem habe ich einer Dame in Menethil dabei geholfen, ihre Tasche wiederzufinden - ein Brühschlammer hatte sie gefressen. Ich habe auch gesehen, wie Mitglieder der Königlichen Apothekervereinigung aus Unterstadt Proben von dem Zeug sammelten. Ich möchte wissen, wieso! Wo kommt es her?\n\nIch habe auch gehört, dass es im Teufelswald noch mehr davon geben soll. Ich brauche einige Proben von den Brühschlammern dort, damit ich meine Forschungen weiter vorantreiben kann. Ich gebe Euch einige Behälter mit; verwendet diese, um eine Probe von den toten Kreaturen einzusammeln.", sourceObjective = "Bringt 6 gefüllte verfluchte Brühschlammergläser und 6 gefüllte besudelte Brühschlammergläser zu Laris Bummelritzel in Eisenschmiede.", progress = "Schon einige meiner bisherigen Experimente waren absolut faszinierend. Ich glaube, mit ein bisschen mehr Arbeit kann ich noch genauer herausfinden, was es mit diesen Kreaturen auf sich hat und welchen Zusammenhang es zwischen ihnen und der Entwicklung des Lebens auf Azeroth gibt - falls ein solcher Zusammenhang überhaupt existiert.\n\nEine meiner Haupttheorien - die allerdings nicht auf sonderlich viel Gegenliebe stößt - ist der Gedanke, dass die Brühschlammer und Brühschleimer irgendwie mit der Erschaffung dieses Planeten zusammenhängen ... fast so, als seien sie eine seiner Ausscheidungen.\n\nAber das kann ich nicht beweisen oder widerlegen, solange ich nicht mehr Proben bekomme.", completion = "Ganz erstaunlich, {name}! Ihr seid nahe genug herangekommen, um eine Probe der verderbten Wesen zu erhalten, und dabei seht Ihr nicht mitgenommener aus als vorher! Danke. Oh, diese Exemplare eignen sich perfekt. Ich kann es kaum erwarten, meine Versuche daran zu beginnen.\n\nWenn ich Recht habe, dann bin ich vielleicht bald einer der größten Wissenschaftler der Forscherliga!\n\nDas wird allen Zwergen beweisen, dass es kein Fehler war, uns Gnomen nach dem Vorfall in Gnomeregan nach Ironforge hineinzulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4513] = { id = 4513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brühschlammer auf Abwegen", description = "Ich brauche noch mehr Proben, {name}. Aber - und ich weiß nicht so recht, wie ich das ausdrücken soll - es müssen reine Proben sein. Ich weiß, ich weiß. \"Was meint Ihr mit 'rein', Laris?\", fragt Ihr. Ich kann es nicht genau sagen. Ich weiß, dass die hier verderbt sind... genau wie im Teufelswald. Und genau deswegen ist meine Erkenntnis so wichtig. Die Brühschlammer scheinen sich anzupassen... die Eigenschaften der Gegend anzunehmen, in der sie sich befinden. Ich muss Proben finden, die nicht verunreinigt sind. Aber wo? Wo?!\n\nPah! {name}, nehmt diese Behälter einfach mit, nur für den Fall, dass Ihr irgendwo welche finden solltet.", sourceObjective = "Bringt 10 gefüllte reine Probengläser zu Laris Bummelritzel in Eisenschmiede.\n\nFalls Ihr Probleme habt, fündig zu werden, dann kann Laris Euch vielleicht noch den einen oder anderen Hinweis geben.", progress = "So viel, über das man nachdenken muss. Aber was bedeutet es alles? Und wie wirkt es sich auf die Bevölkerung von Azeroth aus?", completion = "Ihr habt es gefunden? {name}, Ihr seid ein wahrer Schatz. Eure Hingabe und Eure Hilfe waren einfach fabelhaft und ich kann Euch gar nicht genug danken.\n\nBitte, nehmt dies für Eure Mühen. Es wartet Arbeit auf mich, aber ich bin sicher, dass ich Eure Dienste erneut in Anspruch nehmen werde, wenn Ihr später wiederkommt.\n\nDanke. Vielen herzlichen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[4521] = { id = 4521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Wächter", description = "Winterquell liegt gleich hinter der Holzschlundfeste, im Nordosten des Teufelswalds. Seid Ihr schon mal dort gewesen?\n\nIch habe gehört, dass es in jener Region nur so von Kreaturen wimmeln soll, die Wildekin genannt werden. Diese Bestien sind dafür bekannt, dass sie Geheimnisse bewachen, und zwar Geheimnisse der Nachtelfen.\n\nWir müssen herausfinden, was in Winterquell verborgen liegt.\n\nIch habe gehört, die struppigen Eulenbestien findet man südlich von der Straße, und außerdem soll es noch so genannte tobende Eulenbestien geben, die im Zentrum von Winterquell zu finden sind. Räumt sie aus dem Weg und verschafft Euch so Zutritt zu dem Gebiet.", sourceObjective = "Trull Scheiterbann im Teufelswald möchte, dass Ihr 15 tobende Eulenbestien und 15 struppige Eulenbestien tötet.", completion = "Das sind ausgezeichnete Neuigkeiten, {name}. Jetzt, wo diese Bestien aus dem Weg geschafft sind, können wir uns weiter nach Winterspring hineinwagen. Seid Ihr bereit für neue Taten?", sourceObjectiveStatus = "unverified-source-field" }
quests[4542] = { id = 4542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht zum Freiwindposten", description = "<Tapferer Reisender/Tapfere Reisende>, die Zentauren haben ihre Angriffe in diesem Gebiet verstärkt. Der Freiwindposten muss umgehend über diese erneuten Angriffe informiert werden! Sucht Klippenbehüter Langhorn am Freiwindposten im Südosten auf und gebt ihm diese dringende Nachricht.\n\nDoch seht Euch vor und geht dem hier in der Nähe herumlungernden Grimmtotemklan aus dem Weg... in letzter Zeit benehmen die Leute sich seltsam uns gegenüber.", sourceObjective = "Bringt Klippenbehüter Langhorn am Freiwindposten die dringende Nachricht.", progress = "Was wollt Ihr, {class}? Eine dringende Botschaft - für mich?", completion = "Noch mehr schlechte Nachrichten! Jetzt sind diese Zentauren zu weit gegangen! Sie haben eine meiner Nachschubkarawanen überfallen und die gesamte Truppe abgeschlachtet. Das ist ungeheuerlich und wird nicht ohne Strafe bleiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[4561] = { id = 4561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test auf Unreinheiten - Krater von Un'Goro", progress = "Ihr nehmt eine Brühschleimerprobe aus dem Un'Goro Krater und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Brühschleimer seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure geläuterten Un'Goro-Brühschleimerproben sowie einige andere Rückstände enthält.", completion = "Ihr hebt die Petrischale mit der Brühschleimerprobe hoch. Der einzige Weg, um herauszufinden, ob die Probe rein genug ist, wird sein, die Schale zu öffnen und deren Inhalt selbst zu untersuchen. Im besten Falle findet Ihr eine Probe, die Chemiker Fuelys Ansprüchen genügt." }
quests[4581] = { id = 4581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kayneth Stillwind", description = "Der Druide Kayneth Stillwind hat sich bei mir gemeldet. Er hätte gern einen Bericht über das, was an unserer Küste und in den Wäldern um Astranaar vorgeht. Er befürchtet, dass eine Verderbnis durch das Eschental zieht... und vielleicht hat er Recht damit.\n\nHier, bringt ihm meinen Bericht. Ihr werdet ihn im Schrein von Waldeslied finden, im Nachtweisenwald im Osten.", sourceObjective = "Bringt Shindrells Notiz zu Kayneth Stillwind in Waldeslied.", progress = "Habt Ihr etwas für mich?", completion = "Ah, Shindrells Bericht! Vielen Dank, {name}. Shindrell ist, wie eine gute Schildwache sein muss: mutig und aufmerksam. Ich muss das hier lesen; vielleicht finden sich darin Hinweise auf ein Übel, von dem ich fürchte, dass es durch Ashenvale zieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4601] = { id = 4601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funkelmat 5200!", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", sourceObjective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftig peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt während er hin und her schlingert...", sourceObjectiveStatus = "unverified-source-field" }
quests[4602] = { id = 4602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funkelmat 5200!", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", sourceObjective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt, als er hin und her schlingert...", sourceObjectiveStatus = "unverified-source-field" }
quests[4603] = { id = 4603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funkelmatastisch", progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomen-Lösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel." }
quests[4604] = { id = 4604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funkelmatastisch", progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomen-Lösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel." }
quests[4605] = { id = 4605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funkelmat 5200!", sourceObjective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[4606] = { id = 4606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funkelmat 5200!", sourceObjective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[4621] = { id = 4621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holla, Admiral!", description = "Jetz' hört mal zu, <oller Seebär/olle Piratenbraut>... Wegen der Machthaber in Beutebucht könn'n wir Blutsegel nich' hinsegeln, wo wir woll'n, und uns nich' das nehm'n, was wir als Beute ha'm woll'n. Tätet Ihr aber Flottenmeister Seehorn 'n Messer verpass'n, dann würd'n wir nie wieder mit 'nem Schiff aus Beutebucht aneinander geraten tun. Tätet Ihr Baron Revilgaz 'n Messer verpass'n, dann müsst'n wir uns nie wieder denen ihrem Gesetz stellen.\n\nWenn Ihr also 'n Admiral ehrenhalber bei uns werd'n wollt - ja, ADMIRAL hab ich gesagt! - dann verpasst den beiden 'n Messer, wie ich's gesagt hab. Un' jetz' geht, <Jungchen/Mädel>, un' kommt wieder, sobald Ihr's gemacht habt.", sourceObjective = "Tötet Flottenmeister Seehorn und Baron Revilgaz aus Beutebucht und kehrt dann zu Flottenmeister Firallon zurück. Er befindet sich auf der Purpurschleier vor der Küste des Schlingendorntals.", sourceObjectiveStatus = "unverified-source-field" }
quests[4641] = { id = 4641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Platz in der Welt", description = "Endlich seid Ihr alt genug, {name}... alt genug, um im Namen der Horde zu kämpfen. Um für den Ruhm des Kriegshäuptlings Siege zu erringen.\n\nJa...\n\n<Kaltunk mustert Euch.>\n\nDoch, doch, Ihr eignet Euch.\n\nZweifellos wollt Ihr Euch einen mächtigen Drachen oder einen Dämon suchen und ihn mit bloßen Händen erwürgen, aber vielleicht ist es vernünftiger, wenn Ihr mit etwas weniger... Gefährlichem anfinget.\n\n<Kaltunk lacht.>\n\nMeldet Euch bei Gornek; der sollte Euch eine Aufgabe zuweisen können, die zu einem wie Euch passt, {class}. Ihr findet Gornek im Höhlenbau im Westen.", sourceObjective = "Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen.", completion = "Wieder einer von Kaltunks Rekruten, was?\n\nEs ist wirklich schlecht um die Horde bestellt, wenn das das Beste ist, was wir auf die Beine stellen können. Einerlei. Wenn es so weit ist und wir erkennen, dass Ihr bereit seid, das Tal zu verlassen, werdet Ihr ein stolzer Krieger der Horde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[4642] = { id = 4642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinigung von Einflüssen", description = "Hier drin eingeschlossen ist einer von den Brühschlammern, die Ihr im Teufelswald eingesammelt habt. Bringt das Behältnis zum Krater von Un'Goro und sucht dort einen reinen Brühschlammer - einer von den Urzeitbrühschlammern wird's tun, denke ich. Sobald Ihr nahe genug heran seid, lasst den Brühschlammer aus dem Behältnis frei, und dann wollen wir doch mal sehen, was die beiden voneinander halten.\n\nBringt mir nach dem Ende des Experiments eine Probe von dem, was anschließend noch übrig ist. Ich erwarte Euch hier im Apothekarium.", sourceObjective = "Bringt eine verschmolzene Brühschlammerprobe zum Chemiker Brenner in Unterstadt.", progress = "Wie läuft das Experiment, {name}? Ich werde weiter die Proben studieren, die Ihr mir beschafft habt - langsam verstehe ich, warum sich Lady Sylvanas so sehr für diese Kreaturen interessiert. Sollten sie wirklich ein Teil der Alten Götter sein, wer weiß, wie wir das zu unserem Vorteil ausnutzen können ...", completion = "Oh, ganz ausgezeichnet, {name}. Wirklich ganz ausgezeichnet.\n\nWas für eine Geschichte. Wer hätte gedacht, dass die beiden auf diese Weise miteinander interagieren würden... Ich muss mich wohl eingehender mit den Umweltbedingungen auseinander setzen, die diese Veränderungen in den Kreaturen auslösen.\n\nAlso werde ich meine Forschungen jetzt fortsetzen. Vielleicht sehen wir uns bald wieder. Bis dahin wünsche ich Euch alles Gute.", sourceObjectiveStatus = "unverified-source-field" }
quests[4661] = { id = 4661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test für Verderbnis - Teufelswald", progress = "Ihr nehmt eine Brühschlammerprobe aus dem Teufelswald und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Schleim seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure veränderten Teufelswaldschleimproben und einige andere Rückstände enthält.", completion = "Ihr hebt die Petrischale mit der Brühschleimerprobe hoch. Der einzige Weg, um herauszufinden, ob die Probe rein genug ist, wird sein, die Schale zu öffnen und deren Inhalt selbst zu untersuchen. Im besten Falle findet Ihr eine Probe, die Chemiker Fuelys Ansprüchen genügt." }
quests[4681] = { id = 4681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Land gespült", description = "Die gestrandete Kreatur ist kein Einzelfall hier in Dunkelküste. Entlang der Ufer und sogar im Wasser gibt es noch mehr davon. Ich möchte, dass Ihr einen weiteren Fall untersucht, von dem wir wissen - da wurde die Kreatur westlich von Auberdine im Meer gesichtet, und zwar in der Nähe eines gesunkenen Schiffes. Kommt mit allem, was Ihr findet und was uns bei unseren Forschungen behilflich sein könnte, zu mir zurück.\n\nAußerdem begegnet Ihr auf Euren Reisen vielleicht auch noch anderen Kreaturen. Falls Ihr etwas entdecken solltet, dann zögert bitte nicht und informiert uns darüber!", sourceObjective = "Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde.", progress = "Sobald Ihr die Überreste der Kreatur in den Gewässern westlich von hier untersucht habt, kann ich einen ordentlichen Bericht für den Tempel des Mondes in Darnassus verfassen. Vielleicht sind wir dann etwas näher an der Lösung des Rätsels, warum diese armen Kreaturen sich dazu entschlossen haben, ihr Leben an der Küste von Dunkelküste auszuhauchen.", completion = "Ihr seid mir hier und heute eine große Hilfe gewesen. Jetzt haben wir eine reelle Chance, hinter das Geheimnis zu kommen, warum diese Kreaturen sich an den Ufern von Dunkelküste auf den Strand werfen. Der Gedanke, dass sie vielleicht aus der Gegend um Teldrassil fliehen, ist beunruhigend. Solltet Ihr auf Euren Reisen auf andere, ähnliche Kreaturen treffen, dann lasst es mich bitte wissen. Wir befinden uns mit unserer Forschung noch ganz am Anfang.\n\nBitte, nehmt im Namen des Tempels des Mondes dies als Dank für Eure Bemühungen an. Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[4701] = { id = 4701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellt sie ab", description = "Zweifellos habt Ihr die Worgs schon gesehen, die die Orcs des Schwarzfels befehligen.\n\nEs ist seltsam... ganz egal, wie viele wir vernichten, es scheinen nie weniger zu werden. Meine Späher haben berichtet, dass die Worgs gezüchtet, trainiert und schließlich von der Schwarzfelsspitze exportiert werden: der Hauptstadt der Schwarzfelsorcs. Ihr müsst Euch zur Schwarzfelsspitze begeben und der Quelle dieser Bedrohung auf den Grund gehen. Ihr auf den Grund gehen... und sie vernichten.\n\nViel Glück, {name}. Möge Cenarius Euch beschützen...", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.", completion = "Denkt nicht länger über ihr Leiden nach, {name}. Jene Bestie war verderbt - ein Produkt dunkler Magie. Ihr habt der Allianz einen großen Dienst erwiesen und sollt dafür belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[4721] = { id = 4721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Wächter", description = "Es sind Läufer aus Winterquell zurückgekehrt, die berichten, dass es im Süden von Winterquell eine Reihe kleiner Höhlen gibt. Es scheint, als würden sich im Gebiet um diese Höhlen herum Wildekin aufhalten. Falls sie wirklich irgendetwas Wertvolles bewachen, so ist das der Ort, an dem wir es finden werden, denke ich.\n\nIhr werdet feststellen, dass diese Wildekin eine etwas größere Herausforderung sind als die, mit denen Ihr Euch bisher herumgeschlagen habt, {name}. Es scheint, als hätte genau das, was diese Kreaturen beschützen wollen, sie in den Wahnsinn getrieben.", sourceObjective = "Trull Scheiterbann im Teufelswald möchte, dass Ihr in Winterquell 10 Berserkereulenbestien jagt.", completion = "Vor harter Arbeit habe ich großen Respekt, {name}. Jetzt können wir unsere Pläne mit Winterspring weiter vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[4722] = { id = 4722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meeresschildkröte", description = "Ihr findet den Kadaver einer Meeresschildkröte, die sich vor einiger Zeit an das Ufer von Dunkelküste an den Strand geworfen hat. Der Kadaver wurde von den Murlocs gefleddert, die um die Überreste der Kreatur herum ihr Lager aufgeschlagen haben. Dennoch scheinen an den Überresten der Kreatur noch einige geeignete Proben zu haften, aus denen Gwennyth Bly'Leggonde aus Auberdine vielleicht noch etwas machen kann.", sourceObjective = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Hallo, {name}... habt Ihr irgendwelche Kreaturen entdeckt, die an Land gespült wurden und von denen Ihr mir berichten wollt?", completion = "Eine weitere Entdeckung, die wir untersuchen können - gut gemacht, {name}! Diese Überreste werden gründlich untersucht, sobald sie in Darnassus ankommen. Bitte nehmt dieses kleine Honorar an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4723] = { id = 4723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meereskreatur", description = "Die Überreste eines riesigen Dreschers - viel größer als alles, was Ihr in Dunkelküste zu finden erwartet hättet - liegen gestrandet an der Küste des Nebelrandes. Wie es diese Kreatur hierher verschlagen hat, ist nicht zu sagen - die Murlocs, die sich jetzt an dem Gerippe gütlich tun, sehen viel zu schwach aus, als hätten sie, selbst in großer Anzahl, die Bestie erlegen können. \n\nWährend ein Teil des Kadavers bereits sauber abgenagt wurde, ist doch noch genug davon übrig, um Gwennyth Bly'Leggonde aus Auberdine eine Probe zur Untersuchung bringen zu können.", sourceObjective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Vielleicht werden wir eines schönen Tages einen Weg finden, wie wir verhindern können, dass diese armen Kreaturen ohne jeden Sinn und Zweck ihr Leben an den Ufern von Dunkelküste aushauchen. Doch bis dahin müssen wir unsere Forschungen fortsetzen!\n\nSeid gegrüßt, {name}... welche Neuigkeiten bringt Ihr?", completion = "Noch eine Entdeckung, gut gemacht, {name}! Diese Überreste werden gründlich untersucht, sobald sie in Darnassus ankommen. Bitte nehmt dieses kleine Honorar an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4724] = { id = 4724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herrin der Meute", description = "Manche sagen, die vom Schwarzfelsklan kontrollierten Worgs seien durch eine übernatürliche Macht erschaffen worden. Andere wiederum sagen, es seien gar keine echten Worgs, sondern eine Art dämonische Hunde, die den Orcs von einem gefallenen Grubenlord überlassen wurden.\n\nDie Wahrheit ist wesentlich weniger weit hergeholt, aber nicht weniger erschreckend. Die Worgs des Schwarzfels stammen von Halycon und ihrem Partner. Halycon ist die gewaltige Höhlenmutter der Worgs. Und ihr Partner? Es hat noch niemand überlebt, der etwas über diesen Partner sagen konnte.\n\nTrefft die Worgs dort, wo es ihnen am meisten wehtut. Vernichtet Halycon...aber, {name}, seid auf der Hut.", sourceObjective = "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte.", completion = "Tollwütige Welpen? Gizrul der Geifernde? Und Ihr seid noch am Leben, um davon zu berichten?! Unglaublich! Diese Belohnung habt Ihr Euch wohl verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[4725] = { id = 4725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meeresschildkröte", description = "Entlang der Küste liegen weitere Überreste von gestrandeten Meeresschildkröten. Bei diesem speziellen Kadaver ist eine Art Sänfte auf dem Panzer der Schildkröte angebracht. Vielleicht wurde diese Kreatur von unbekannten Wesen an den Strand getrieben, statt sich selbst auf Strand zu setzen, wie sich aus einigen der anderen Überreste schließen ließ. Grauflossenmurlocs haben sich jetzt an den Überresten der Kreatur niedergelassen und fressen das Aas.\n\nIn der Sänfte findet Ihr einen Kasten mit seltsamen Zeichen darauf - vielleicht kann Gwennyth Bly'Leggonde in Auberdine sich einen Reim darauf machen.", sourceObjective = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Es ist mir eine Freude, Euch wiederzusehen, {name}. Zwar machen wir große Fortschritte bei der Lösung des Rätsels, warum so majestätische Meereskreaturen sich selbst an den Ufern von Dunkelküste auf Strand setzen, aber es kommt mir so vor, als würde jede beantwortete Frage zwei neue aufwerfen.\n\nSeid Ihr hier, um uns bei unseren Forschungen behilflich zu sein?", completion = "Ich habe schon von solchen Sänften gehört, wie Ihr sie auf dem Rücken jener Meeresschildkröte gefunden habt. Ich glaube, es handelt sich dabei um Nagasänften, die diese sowohl im Kampf verwenden als auch, um Vorräte an Land zu befördern. Die Zeichen auf dem Kasten, den Ihr gefunden habt, stammen von den Naga - das könnte auch ihr massiertes Eindringen im nördlichsten Teil von Dunkelküste erklären.\n\nIch schicke diesen Kasten nach Darnassus, zusammen mit Euren übrigen Entdeckungen. Das ist für Euch - nochmals danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[4726] = { id = 4726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutlingessenz", description = "Schon seit Wochen studiere ich die Drachkin der brennenden Steppe und ich glaube, mir ist endlich ein Durchbruch gelungen! Ich habe ein Gerät gebaut - ich habe es \"Draco-Incarcinatrix 900\" getauft -, mit dem ich die Essenz von Großdrachenwelpenbrutlingen einfangen kann!\n\nOder zumindest glaube ich das.\n\nHier, nehmt das Gerät und zappt damit einen Brutling in der brennenden Steppe. Wenn Ihr den Brutling dann besiegt, während er sich noch unter dem Einfluss des Geräts befindet, dann sollte eigentlich seine Essenz freigesetzt werden.\n\nWenn dem so ist, dann prima! Bringt mir ein paar Proben zurück, damit ich sie studieren kann.", sourceObjective = "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Kesseldampf am Flammenkamm in der brennenden Steppe.", progress = "Habt Ihr die Brutlingessenz, {name}? Ich kann es kaum erwarten, sie zu studieren.\n\nUnd ganz abgesehen davon, ist mein Kunde nicht gerade jemand, den man gern enttäuscht...", completion = "Es hat geklappt! Ihr habt die Essenz! Gut gemacht, {name}! Gut gemacht!\n\nDiese Essenz wird für meine Forschungen von unschätzbarem Wert sein. Ich hoffe, dass ich eines Tages herausfinden werde, wie ich lebende Großdrachenwelpen einfangen oder mir zumindest ihre Eier beschaffen kann. Wenn mir dies gelänge, dann würden mich alle Drachenforscher auf der ganzen Welt beneiden!\n\nMein Auftraggeber wäre auch zufrieden - und wie ich schon sagte, ist er jemand, den man besser zufrieden stellen sollte ...", sourceObjectiveStatus = "unverified-source-field" }
quests[4727] = { id = 4727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meeresschildkröte", description = "Am Sandstrand im Norden von Dunkelküste liegen die skelettierten Überreste einer Meeresschildkröte. Entweder haben die Grauflossenmurlocs dieses Gerippe nicht gefunden, oder sie haben es zwar gefunden, halten sich aber aus irgendeinem unbekannten Grund davon fern. Wie dem auch sei, es ist genug von der Schildkröte übrig, dass Ihr Gwennyth Bly'Leggonde in Auberdine eine Probe bringen könnt, damit der Tempel des Mondes diese studieren kann.", sourceObjective = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Hallo, {name}, habt Ihr weitere gestrandete Kreaturen gefunden, über die der Tempel des Mondes Bescheid wissen sollte?", completion = "Es ist interessant, dass an der Stelle keine Murlocs waren. Das dürfen wir nicht außer Acht lassen, wenn wir die Überreste dieser Kreatur untersuchen. Ich danke Euch für Eure Bemühungen, {name}. Im Namen des Tempels des Mondes soll ich Euch dies geben, zur Entschädigung für die von Euch aufgewendete Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[4728] = { id = 4728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meereskreatur", description = "Der Kadaver von etwas, das wie ein riesiger Meeressäuger aussieht, liegt teilweise ausgeweidet am Strand. Eine Schubkarre und verschiedenste Werkzeuge liegen bei der riesigen, gestrandeten Meereskreatur verstreut, ganz so, als habe schon einmal jemand den Versuch unternommen, sie zu untersuchen. Zwar wurde die Bestie bereits von Murlocs zerfleddert, doch es ist noch genug davon übrig, um eine passende Probe für Gwennyth Bly'Leggonde aus Auberdine einzusammeln.", sourceObjective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Seid mir erneut gegrüßt, {name}! Was führt Euch nach Auberdine zurück? Seid Ihr vielleicht hier, um mir von einer weiteren Entdeckung zu berichten?", completion = "Ah, ich glaube, das, was Ihr da entdeckt habt, wurde früher schon einmal von der Forscherliga untersucht. Die Liga ist hier in Dunkelküste aktiv und ihre Leute haben erzählt, dass sie dabei waren, eine der gestrandeten Kreaturen zu untersuchen, bis sie von den Murlocs vertrieben wurden. Es scheint, als hättet Ihr dort Erfolg gehabt, wo dies bislang keinem von uns vergönnt war. Bitte, nehmt dieses Honorar im Namen des Tempels des Mondes an.", sourceObjectiveStatus = "unverified-source-field" }
quests[4729] = { id = 4729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiblers Exotische Tiere", description = "Wahrscheinlich fragt Ihr Euch, was ich hier draußen mache. Schaut Euch die Käfige an! Liegt es nicht auf der Hand?\n\nIch liebe Tiere, aber ich bin Händler von Beruf. Ich spüre exotische Tiere für die Reichen und Berühmten auf und dann zähme ich die Bestien, damit sie sich auch wie brave Tiere verhalten.\n\nJetzt fragt Ihr Euch wahrscheinlich, was Ihr für Kibler tun könnt. Die Antwort ist einfach: Nehmt den Bestienkäfig hier und beschafft mir ein paar Worgwelpen. Dafür zähme ich Euch auch einen Worg!", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler.", progress = "<Kibler streitet sich gerade mit Toucan Stan.>", completion = "Ihr habt sie gerade noch rechtzeitig erwischt, {name}. Wenig später, und sie hätten nicht mehr ausgebildet werden können! Gebt mir eine Minute, dann könnt Ihr den kleinen Kerl mit nach Hause nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4730] = { id = 4730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meereskreatur", description = "Am Strand liegt der halb aufgefressene Kadaver von etwas, das vielleicht einmal ein riesiger Meeressäuger war. Eine Bande Murlocs, stärker als diejenigen, die näher an Auberdine zu finden sind, haben ihr Lager um die verendete Kreatur herum aufgeschlagen. Es ist noch genug von der Kreatur übrig, um Gwennyth Bly'Leggonde in Auberdine eine passende Probe ihrer Knochen bringen zu können.", sourceObjective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Hallo, {name}! Seid Ihr hier, um mir von einer weiteren Entdeckung zu berichten?", completion = "Die Knochen, die Ihr da habt, stammen von sanftmütigen Meeressäugern, die, wie wir wissen, die Wasser rund um Teldrassil bewohnen. Es war bisher noch nicht bekannt, dass diese Kreaturen sich selbst gewaltsam auf Strand setzen, so wie wir das von den Dreschern kennen. Warum sollten sie das tun, frage ich mich? Nun ja, vielleicht bringt uns das Studium ihrer Überreste dem Wissen näher, nach dem wir streben.\n\nNochmals danke für Eure Hilfe. Bitte, nehmt dieses Honorar vom Tempel des Mondes an.", sourceObjectiveStatus = "unverified-source-field" }
quests[4731] = { id = 4731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meeresschildkröte", description = "Erneut findet Ihr gestrandete Meeresschildkrötenüberreste. Bei diesen Überresten ist eine Art Sänfte auf dem Panzer der Schildkröte festgeschnallt. Vielleicht wurde diese Kreatur von unbekannten Wesen an den Strand getrieben, statt sich selbst auf Strand zu setzen, wie sich aus einigen der anderen Überreste schließen ließ. Mächtige Grauflossenmurlocs haben sich beim Gerippe der Kreatur niedergelassen.\n\nIn der Sänfte findet Ihr einen Kasten mit seltsamen Zeichen darauf - vielleicht kann Gwennyth Bly'Leggonde in Auberdine sich einen Reim darauf machen.", sourceObjective = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Hallo, {name}. Ihr habt für den Tempel des Mondes wirklich ganz hervorragende Arbeit geleistet. Dürfen wir darauf hoffen, dass Ihr Eure Bemühungen auch weiterhin auf unsere Sache konzentrieren werdet?", completion = "Ich habe schon von solchen Sänften gehört, wie Ihr sie auf dem Rücken jener Meeresschildkröte gefunden habt. Ich glaube, es handelt sich dabei um Nagasänften, die diese sowohl im Kampf verwenden als auch, um Vorräte an Land zu befördern. Die Zeichen auf dem Kasten, den Ihr gefunden habt, stammen von den Naga ... könnte die Kreatur, die Ihr entdeckt habt, getötet worden sein, als sie gerade unterwegs nach Süden war... nach Ashenvale vielleicht?\n\nIch werde es nicht versäumen, diesen Kasten zusammen mit Euren übrigen Entdeckungen nach Darnassus zu schicken. Das ist für Euch - nochmals danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[4732] = { id = 4732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meeresschildkröte", description = "Ihr findet den Kadaver einer Meeresschildkröte, die sich selbst vor einiger Zeit an das Ufer von Dunkelküste auf Strand gesetzt hat. Der Kadaver ist schon fast vollständig von Grauflossenmurlocs abgefressen worden - eben jenen Murlocs, die um die Überreste der Kreatur herum ihr Lager aufgeschlagen haben. Dennoch scheinen an den Überresten der Kreatur noch einige geeignete Proben zu haften, aus denen Gwennyth Bly'Leggonde aus Auberdine vielleicht noch etwas machen kann.", sourceObjective = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Seid mir gegrüßt, {name}... habt Ihr noch weitere Entdeckungen, von denen Ihr dem Tempel des Mondes berichten wollt?", completion = "Ihr habt noch weitere gestrandete Kreaturen gefunden, {name}? Die Meeresschildkröten tummelten sich für gewöhnlich in den Wassern am Fuße von Nordrassil, bevor er zerstört wurde. Doch seit der Entstehung von Teldrassil sind diese Wesen immer seltener gesichtet worden. Manche beenden ihr Leben hier, wie wir entdeckt haben - aus uns völlig unbekannten Gründen.\n\nMit Eurer Hilfe können wir dem Geheimnis vielleicht auf die Spur kommen. Bitte nehmt dies an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4733] = { id = 4733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandete Meereskreatur", description = "Die Überbleibsel dessen, was anscheinend einmal ein riesiger Drescher war, wurden an den steinigen Gestaden des Zwielichtufers angeschwemmt. Der Drescher ist wesentlich größer als alle anderen Drescher, die in diesen Landesteilen gesichtet wurden. Wo immer die Kreatur auch hergekommen sein mag, es scheint nicht so, als sei sie in Dunkelküste heimisch.\n\nObwohl das Wesen schon stellenweise angefressen wurde, ist noch genug davon übrig, um eine passende Probe für Gwennyth Bly'Leggonde in Auberdine einzusammeln.", sourceObjective = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", progress = "Elune sei Dank - Ich freue mich, Euch wiederzusehen, mein lieber {name}. Der Tempel des Mondes beschäftigt sich weiterhin mit dem seltsamen Phänomen der hier in Dunkelküste gestrandeten Kreaturen. Habt Ihr vielleicht wieder etwas, das uns weiterhelfen könnte?", completion = "Die Ausmaße des Dreschers, von dem Ihr erzählt, lassen sich kaum vorstellen. Selbst die ältesten Drescher in dieser Gegend erreichen nur einen Bruchteil dieser Größe. Zwar war bekannt, dass um Teldrassil herum größere Drescher zu finden waren, doch hat ihre Zahl ständig abgenommen. Ich kann mir nicht helfen, ich frage mich, ob die Kreaturen, die sich selbst hier auf Strand setzen, irgendwie damit zu tun haben.\n\nWir werden die Knochen analysieren, die Ihr uns gebracht habt. Bitte, nehmt dies so lange im Namen des Tempels des Mondes an. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4734] = { id = 4734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ei-Frosten", description = "Ich habe hart an einem neuen Gerät gearbeitet, {name} - dem Eiszilloskop! Es ist so konstruiert, dass es einen Strahl kalter Energie auf das Ei eines schwarzen Großdrachen abgibt und es einfriert! Könnt Ihr das für mich ausprobieren?\n\nIch habe gehört, dass die Großdrachen weit oben auf der Schwarzfelsspitze einen Horst haben, wo sie ihre Eier ausbrüten. Da müsst Ihr hin, um das Eiszilloskop zu testen, und dann müsst Ihr mir sagen, wie es funktioniert hat!\n\nUnd seid unbesorgt. Gefrorene Dracheneier sollten harmlos sein. Bloß bei den ungefrorenen müsst Ihr Euch Sorgen machen!", sourceObjective = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst.", progress = "{name}! Habt Ihr das Eiszilloskop getestet?", completion = "Es hat funktioniert? Ausgezeichnet! Ich hab's gewusst!\n\nWährend Ihr weg wart, habe ich an einer neuen Version des Eiszilloskops gearbeitet. Es hat jetzt eine viel größere Reichweite.\n\nHier, Ihr könnt eines davon haben, falls Ihr noch mal zur Blackrockspitze zurückgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[4735] = { id = 4735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiersammlung", description = "{name}, ich bin endlich bereit für echte Dracheneier! Hier, nehmt dieses kollektronische Modul. Es ist so konstruiert, dass es ein Drachenei extrahiert und für den Transport vorbereitet. Kehrt zum Horst zurück und verwendet das Modul, um Eier einzusammeln.\n\nAber vergesst nicht, sie vorher einzufrieren, sonst schlüpfen sie vielleicht aus, ehe Ihr sie einsammeln könnt!\n\nWenn Ihr genug Eier habt, dann bringt sie mir.", sourceObjective = "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Kesseldampf am Flammenkamm in der brennenden Steppe.", progress = "Habt Ihr die Eier, {name}? Mein Kunde hat gehört, dass Ihr sie für mich sammelt, und ist sehr begierig darauf, sie in die Finger zu bekommen!", completion = "Wahnsinn, Ihr habt sie! Das kollektronische Modul hat funktioniert! Ich bin ein Genie!\n\nDanke, {name}. Mein Kunde wird äußerst erfreut sein, dass er diese Eier bekommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[4736] = { id = 4736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Menara Leerbringer", description = "Ah, hallo, {name}. Ihr macht bei Eurer Ausbildung gute Fortschritte. So gute Fortschritte, um genau zu sein, dass ich finde, Ihr solltet für Eure harte Arbeit belohnt werden - und dafür, dass Euch die arkanen Künste noch nicht verderbt haben.\n\nFalls Ihr Interesse habt, sucht Menara Leerbringer in Ratschet auf. Momentan wohnt sie in Strahad Farsans Turm über der Stadt.\n\nSie ist nicht sehr umgänglich, {name}, also erwartet keine Lobeshymnen von ihr. Aber wenn Ihr hart arbeitet, dann wird sie sich gut um Euch kümmern.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[4737] = { id = 4737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Menara Leerbringer", description = "Hmpf. Noch immer wollt Ihr mächtiger werden. Ich sage, es ist nur eine Frage der Zeit, ehe die Verderbnis und die Sucht sich Eurer bemächtigen und Ihr ein Sklave dessen werdet, über das Ihr Macht gewinnen wollt.\n\nPah! Ihr seid ein Dummkopf! Die Zeit wird mir Recht geben - nichts anderes, nur die Zeit.\n\nDoch es scheint, dass nicht alle derselben Meinung sind wie Zevrost. Es scheint, als wäre Menara bereit, Instrumente für Euch herzustellen, mit denen Ihr mächtiger werden und Eure Kräfte besser nutzen könnt. Falls Ihr Interesse habt, dann begebt Euch nach Ratschet im Brachland. Sie befindet sich dort über der Stadt.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", completion = "Ah, Zevrost hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4738] = { id = 4738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Menara Leerbringer", description = "Lasst uns eine Sache klarstellen, {name}: Ich finde nicht, dass Ihr für eine solche Verantwortung schon bereit seid. Ich glaube nicht, dass ein Neuling bei der Erschaffung irgendeines Gegenstands der Macht helfen sollte, und schon gar nicht jemand, der noch so unerfahren ist.\n\nDoch diese Entscheidung liegt nicht bei mir. Diese Entscheidung treffen die maßgeblichen Stellen oder zumindest diejenigen, die Euch eine solche Gabe zukommen lassen wollen.\n\nFalls Ihr mehr darüber wissen wollt, dann schlage ich vor, Ihr sucht Menara Leerbringer in Ratschet auf. Für gewöhnlich hält sie sich in dem Turm über der Hafenstadt auf.", sourceObjective = "Sprecht im Brachland mit Menara Leerbringer.", completion = "Ah, Demisette hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4739] = { id = 4739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Menara Leerbringer", description = "{class}! Ja, Ihr!\n\nIhr habt noch nicht alles Handwerkszeug zusammen, aber es ist deutlich, dass Ihr bereit seid - Euch umgibt eine Aura größeren Selbstvertrauens. Ja, das erkenne ich jetzt.\n\nMenara Leerbringer kann Euch ein paar Dinge beibringen, wenn Ihr denkt, dass Ihr bereit seid. Sie unterrichtet jüngere Schüler in den arkanen Künsten. Sie macht denen, die ihre Prüfungen bestehen, sogar Geschenke.\n\nGeht nach Ratschet ins Brachland, wenn Ihr Interesse habt. Sie ist in Strahads Turm über der Stadt.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", completion = "Ah, Kaal hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4740] = { id = 4740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gurgelbacke!", description = "Achtung!\n\nEine Belohnung wird ausgesetzt für den Tod des Murlocs \"Gurgelbacke\". Diese üble Bestie ist nachgewiesenermaßen verantwortlich für den Tod mindestens einer Schildwache und wird verdächtigt, den Untergang von mindestens zwei Frachtschiffen in den Gewässern vor Dunkelküste verursacht zu haben!\n\nZuletzt wurde Gurgelbacke an einem Barackenlager der Murloc südlich von Auberdine gesehen. Es wird angenommen, dass er die Hütten dort verteidigt. Das Kopfgeld kann bei Schildwache Glynda Nal'Shea in Auberdine eingefordert werden.\n\nDer Dorfrat von Auberdine", sourceObjective = "Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.\n\nInformiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod.", completion = "Na, sieht ganz so aus, als wolltet Ihr etwas mehr, als Euch nur zu erkundigen! Die Bürger werden erleichtert sein zu hören, dass sie heute Nacht ein bisschen sicherer und tiefer schlafen können.\n\nHeute habt Ihr der Gerechtigkeit für das Volk von Auberdine zum Sieg verholfen, {name}. Dafür möchte ich Euch dies als passende Belohnung anbieten - für einen echten Helden des Volkes von Auberdine!", sourceObjectiveStatus = "unverified-source-field" }
quests[4741] = { id = 4741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Wächter", description = "Die Wildekin in den nördlichen Bereichen von Winterquell werden immer aggressiver. Wir müssen unsere Aktivitäten dort fortsetzen.\n\nJagt die mondbestrahlten Eulenbestien von Winterquell und untersucht das Gebiet, das sie bewohnen.\n\nDie Gegend dort ist gefährlich, aber ich weiß, dass Ihr der Aufgabe gewachsen seid. Kehrt zu mir zurück, sobald Ihr 13 der Wildekin getötet habt.", sourceObjective = "Trull Scheiterbann im Teufelswald möchte, dass Ihr in Winterquell 13 mondbestrahlte Eulenbestien jagt.", completion = "Ich kann spüren, dass Eure Arbeit Euch Spaß macht. Und ich glaube, wir sind hier etwas auf der Spur.", sourceObjectiveStatus = "unverified-source-field" }
quests[4742] = { id = 4742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Aufstiegs", description = "Wie Ihr sehen könnt, befinden sich an dem unverzierten Siegel drei leere Sockel. Jeder dieser Sockel muss mit einem Edelstein gefüllt werden, der die Befehlsgewalt der Führungsspitze darstellt. Und schließlich muss Oberanführer Wyrmthalak, der Meister der unteren Zitadelle, das Siegel in den Flammen des schwarzen Drachenschwarms schmieden.\n\nEines müsst Ihr wissen, sterbliches Wesen: Die Wahrscheinlichkeit, dass einer der drei Generäle der unteren Zitadelle zu einer bestimmten Zeit einen der Edelsteine trägt, ist äußerst gering. Ihr dürft in Eurer Wachsamkeit nicht nachlassen. Bleibt entschlossen!", sourceObjective = "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.\n\nVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.", progress = "Mut und vor allem Geduld Euch, sterbliches Wesen!", completion = "<Vaelans Bild verschwimmt einen Moment lang.>\n\n<Die Teile, die Ihr gesammelt hattet, sind verschwunden.>\n\nDas ungeschmiedete Siegel des Aufstiegs ist jetzt bereit. Es ist Zeit für den letzten Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4743] = { id = 4743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Aufstiegs", description = "Nur wenige der schwarzen Drachkin außerhalb der oberen Zitadelle sind in der Lage, das Siegel mit ihrem eigenen Flammenatem zu schmieden. Wyrmthalak ist ein solcher Drachkin, doch sein Wille kann nicht gebrochen werden.\n\nIhr müsst zum Drachensumpf in den Düstermarschen reisen. Dort werdet Ihr einen alten Drachen namens Aschenschwinge finden. Seinen Willen müsst Ihr brechen, {name}. Brecht seinen Willen und verwendet diese Kugel, sobald er geschwächt ist. Doch Ihr werdet nur wenige Sekunden haben, in denen Ihr seinen Geist kontrollieren und die Flammen anfachen könnt, mit denen das Siegel geschmiedet wird.", sourceObjective = "Reist zum Drachensumpf in den Düstermarschen. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.\n\nIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!", progress = "Vergeudet keine Zeit, sterbliches Wesen. Nefarian arbeitet fieberhaft daran, sein Übel über unsere Welt zu bringen.", completion = "Bewegt Euch nicht, während ich die letzte Herbeirufung des Schutzes wirke.\n\n<Vaelans Augen werden zu zwei Flammenkugeln.>\n\nDas Siegel des Aufstiegs ist vollendet...\n\nWisset eines: Ich habe das Artefakt mit mächtigem Zauberschutz magieerfüllt. In Eurer dunkelsten Stunde, wenn Ihr glaubt, dass alles verloren ist, dann wird Euch die Kraft des roten Drachenschwarms zur Verfügung stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4761] = { id = 4761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thundris Windwirker", description = "Beim Erkunden des Furbolglagers seid Ihr auf Neuigkeiten gestoßen, über die Ihr Thundris Windwirker informieren solltet. Er fungiert umsichtig als der Älteste von Auberdine und kümmert sich weise und gerecht um die täglichen Angelegenheiten des Dorfs. Bitte setzt ihn von den Dingen, die Ihr bislang über die Furbolgangelegenheit in Erfahrung gebracht habt, in Kenntnis.\n\nIch glaube, er hat bezüglich der Gründe für deren Verderbnis seine eigene Theorie. Vielleicht könnt Ihr zusammen mit ihm einen Plan erarbeiten, mit dem das Gleichgewicht der Natur hier wiederhergestellt werden kann!", sourceObjective = "Sprecht mit Thundris Windwirker in Auberdine.", completion = "Grüße, {class}. Eure Erkundung der Lage bei den Furbolgs kommt für Auberdine gerade zur rechten Zeit. Wir haben es seit einiger Zeit nicht nur mit Waldbewohnern zu tun, die auf unsere Anwesenheit jetzt ganz offen feindlich reagieren, sondern mit der offensichtlichen Verderbnis des Waldes selbst. Hoffentlich könnt Ihr Auberdine in diesen schwierigen Zeiten helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4762] = { id = 4762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klippenquell", description = "Der Klippenquell wird immer verderbter. Er mündet in Nebelrand und ich fürchte, dass sich das verunreinigte Wasser bald auf Auberdine auswirken wird. Ich halte die Furbolgs der Schwarzfelle flussaufwärts für den Auslöser der Besudelung, aber ich vermute auch, dass sie nicht die wahre Ursache sind.\n\nNehmt diesen Probenbehälter und begebt Euch zur Mündung des Flusses nördlich von hier. Geht weiter landeinwärts bis zum ersten Wasserfall und entnehmt dem Teich dort eine Probe. Oberhalb davon seht Ihr eine Brücke. Kommt zu mir nach Auberdine zurück, sobald Ihr die Probe habt.", sourceObjective = "Geht von Auberdine aus nach Norden zum ersten Wasserfall des Klippenquell und entnehmt aus dem Teich dort eine Probe.\n\nKehrt mit der Probe des Klippenquells zu Thundris Windwirker nach Auberdine zurück.", progress = "Die Verschmutzung des Cliffspring ist nur der Anfang einer alarmierenden Entwicklung hier in Dunkelküste. Die Probe, die Ihr mir gabt, wird uns dabei helfen, einen Plan zu entwickeln. Einen Angriffsplan, wie ich so langsam befürchte.", completion = "Es überrascht mich nicht, dass dieses Wasser so schmutzig ist, aber seht nur, wie faulig es geworden ist! Es sieht so aus, als sollte man lieber umgehend etwas unternehmen, nicht wahr, {name}?\n\nÖstlich von Euch liegt der Teufelswald. Dort ist die eigentliche Quelle dieser Verderbnis, und zwar eine, die ich in der Vergangenheit schon einmal gesehen habe. Ich behaupte, dass diese Probe meine Vermutung bestätigen wird. Vielleicht können wir hier ein Heilmittel entwickeln, aber um es überhaupt versuchen zu können, brauchen wir Unterstützung. Wenn es so weit ist, {name}, hoffe ich, dass Ihr uns Eure Hilfe nicht verweigern werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[4763] = { id = 4763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verderbten Schwarzfelle", description = "Wir haben herausgefunden, dass die Satyrn ein Grund für die Verderbnis der Furbolgs sind. Sie sollen ihre Macht durch Talismane ausüben, mit denen sie ihre Magie kanalisieren können. Damit die Furbolgs Aussicht auf Rettung haben, müssen wir den Satyrverderber aus seinem Versteck locken und ihm diesen Talisman abnehmen!\n\nFüllt diese Schale an unserem Mondbrunnen und holt aus dem Lager der Furbolgs im Norden ein paar Proben ihrer Lebensmittel. Mischt alles zusammen und stellt die Schale in die Nähe des Freudenfeuers am Fluss. Sobald die Furbolgs davon essen, werden sie lang genug gesäubert, um den Satyrverderber herauszulocken... Den Ihr dann töten müsst!", sourceObjective = "Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.\n\nHolt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.\n\nMischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Klippenquell auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.\n\nNehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine.", progress = "Der Talisman der Verderbnis ist ein unheilvolles Ding, dessen einziger Zweck darin besteht, das Gleichgewicht der Natur zu stören. An dem Tag, an dem Ihr dem Satyr, der die Furbolgs quält, diesen Gegenstand abnehmt und zu mir bringt, damit ich ihn vernichten kann, haben wir einen großen Sieg errungen!", completion = "Der Krieg zur Rückeroberung unseres Waldes von den Mächten der Verderbnis hat zwar gerade erst begonnen, aber heute haben wir eine Schlacht gewonnen! {name}, das Volk von Auberdine steht tief in Eurer Schuld, die man Euch nur schwerlich vergelten kann. Bitte nehmt dies zusammen mit unserem Dank. Was wir heute hier gelernt haben, kann unsere Freunde, die Furbolgs, vielleicht eines Tages auf Dauer aus den Fesseln der Pein befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[4764] = { id = 4764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomriggers Schnalle", description = "Hoch droben auf der Schwarzfelsspitze gibt es eine Kammer, die einst 'Halle des Glücks' genannt wurde. Dort bewahrten die Dunkeleisenzwerge ihre Relikte, Trophäen und Kunstobjekte auf.\n\nDoch das ist schon lange her. Man sagt, dass die Halle eingestürzt sei und jetzt für... weniger hehre Zwecke genutzt wird. Ich glaube jedoch, dass man dort immer noch so manch altes Zwergenrelikt finden kann.\n\nEines dieser Relikte ist Doomriggers Schnalle, deren Oberfläche so reich mit seltenen Edelsteinen verziert ist, dass angeblich jeder Zwerg bei ihrem Anblick in Verzückung geraten soll.\n\nDiese Schnalle ist Euer Ziel, {name}.", sourceObjective = "Bringt Mayara Wolkenglanz in der brennenden Steppe Doomriggers Schnalle.", progress = "Habt Ihr die Schnalle, {name}? Mein Herr wird Euch dafür reichlich entlohnen.", completion = "Ihr habt sie gefunden! Also waren die Gerüchte wirklich wahr!\n\nIch danke Euch, {name}. Mein Herr, Graf Remington Ridgewell, wird überglücklich über dieses neue Stück für seine Sammlung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[4765] = { id = 4765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Kronenbrunn", description = "Ich habe Doomriggers Schnalle in eine Kiste gepackt, damit sie nach Sturmwind geschickt werden kann. {name}, Ihr wart wirklich eine große Hilfe - darf ich Euch noch um einen letzten Gefallen bitten?\n\nBringt Graf Remington Kronenbrunn die Kiste. Ihr findet ihn in der Burg von Sturmwind. Ich bin sicher, dass er sich sehr über das freuen wird, was Ihr ihm bringt.", sourceObjective = "Bringt Kronenbrunns Kiste zu Remington Kronenbrunn nach Sturmwind.", progress = "Man sagte mir, dass ein Bote kommen würde. Einer mit einem Geschenk von der Blackrockspitze.\n\nSeid Ihr das vielleicht?", completion = "Ah, Ihr seid das also! Seid bedankt, {name}. Und falls Ihr es noch nicht wisst... die Dankbarkeit eines Adligen derer von Ridgewell übertrifft selbst die Großzügigkeit eines Königs.", sourceObjectiveStatus = "unverified-source-field" }
quests[4766] = { id = 4766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mayara Wolkenglanz", description = "Eine meiner Agentinnen, Mayara Wolkenglanz, wurde in die brennende Steppe entsandt, um die in Ruinen liegende Stadt Thaurissan zu erkunden. Diese zerstörte Stadt der Dunkeleisenzwerge könnte sehr wertvolle Objekte bergen... Objekte, die gar trefflich in unser Familienmuseum passen würden.\n\nMayara sagt, dass sie etwas gefunden hätte und nun Hilfe bräuchte, um es zu holen, allerdings befindet es sich nicht in Thaurissan. Stattdessen ist eine Exkursion zur Schwarzfelsspitze nötig.\n\nIch weiß nichts Genaues, aber sprecht doch mit Mayara in der brennenden Steppe, falls Ihr interessiert seid.", sourceObjective = "Sprecht mit Mayara Wolkenglanz in der brennenden Steppe.", completion = "Ihr kommt aus Stormwind? Wunderbar - ich weiß von einem Kunstobjekt, für das Remington alles geben würde, um es seinem Museum einzuverleiben, aber leider ist es nicht einfach zu beschaffen.\n\nUnd hier kommt Ihr ins Spiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[4767] = { id = 4767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windreiter", description = "Mir wurde aufgetragen, weitere Flügeldrachen für die Meisterwindreiter zu rekrutieren. Sie werden immer mehr und ich hoffe, selbst eines Tages ein Windreiter zu werden. Wie dem auch sei, wir können gar nicht genug Flügeldrachen ausbilden, um der Nachfrage gerecht zu werden. Vielleicht könnt Ihr mir helfen, {name}.\n\nIch möchte, dass Ihr zum Steilhang reist, um dort ein paar Flügeldracheneier zu sammeln. Geht von hier aus nach Nordwesten entlang der Talwände, bis zu einer Rampe, die in das Gebiet des Steilhangs hineinführt. Seid vorsichtig, Flügeldrachen haben einen starken Beschützerinstinkt, was ihre Eier angeht, und schätzen keine Eindringlinge.", sourceObjective = "Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen.", progress = "{name}, habt Ihr die Flügeldracheneier, um die ich gebeten habe? Ich brenne wirklich darauf, so bald wie möglich mit meiner Windreiterausbildung zu beginnen!", completion = "Perfekt! Mit diesen Eiern kann ich hoffentlich die nächste Hürde auf dem Weg zum Windreiter nehmen. Hier habt Ihr ein Zeichen meiner Anerkennung. Möge Eure Jagd immer von Erfolg gekrönt sein, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4768] = { id = 4768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelsteinschrifttafel", description = "Die Dunkelsteinschrifttafel enthält die Niederschriften des vor langer Zeit verstorbenen Zwergs Urheld Dunkelstein. Er war ein äußerst fähiger Alchimist, den seine Zeitgenossen für verrückt hielten und der seine Forschungen daher für sich behielt.\n\nEr hielt jedoch alles auf Schrifttafeln fest und ich glaube, dass eine dieser Schrifttafeln auf der Schwarzfelsspitze zu finden ist, in einer Kammer, die einst die 'Halle des Glücks' genannt wurde. Ich weiß nicht, wie man sie heute bezeichnet, denn nur wenige reisen zum Schwarzfels und kehren heil zurück.\n\nFalls Ihr jedoch gewillt seid, Euch den Gefahren dort zu stellen, und mir diese Schrifttafel bringt, erwartet Euch eine große Belohnung.", sourceObjective = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Dunkelsteinschrifttafel.", progress = "Habt Ihr die Schrifttafel gefunden, {name}? Ich brenne darauf, ihre Geheimnisse zu erfahren.", completion = "Ausgezeichnet. Es wird Tage dauern, bis ich die in diese Schrifttafel eingravierten Formeln erforscht habe, aber ich bin zuversichtlich, dass meine Mühen reichlich Früchte tragen werden.\n\nIch danke Euch, {name}. Ihr habt uns einen unschätzbaren Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4769] = { id = 4769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vivian Lagrave und die Dunkelsteinschrifttafel", description = "Vivian Lagrave aus Kargath im Ödland hat sich an mich gewandt. Aufgrund ihrer Studien ist sie davon überzeugt, dass es irgendwo auf der Schwarzfelsspitze eine alte Niederschrift gibt, die nützlich für unsere Forschung sein könnte. Um dies zu bestätigen, benötigt sie jemanden, der diesen Text von der Schwarzfelsspitze holt. Das ist keine leichte Aufgabe.\n\nFalls Ihr interessiert seid, sprecht in Kargath mit Vivian.", sourceObjective = "Sprecht mit Schattenmagierin Vivian Lagrave.", completion = "Das stimmt. Ich glaube, dass es auf der Blackrockspitze eine Schrifttafel gibt, die alte alchimistische Rezepte enthält. Ich bin froh, dass Ihr hier seid, denn ich brauche Hilfe, um an diese Schrifttafel zu gelangen.\n\nMacht es Euch bequem, dann erkläre ich es Euch näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[4770] = { id = 4770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Heimreise", description = "Bitte helft mir, {class}! Ich verstecke mich jetzt schon eine ganze Weile hier am Steilhang und seit Tagen habe ich kein freundliches Gesicht mehr gesehen. Ich kam hierher, um die Flügeldrachen zu studieren, und bin dabei wohl etwas zu dicht herangekommen. Nachdem ich von einem der Nester verjagt wurde, habe ich mich verlaufen.\n\nIch muss zum Weißgipfelposten zurückkehren! Motega weiß nicht, dass ich vermisst werde, und er wird wütend sein, wenn er hört, dass ich allein zum Steilhang gegangen bin.\n\nDer Weißgipfelposten liegt direkt östlich von hier...bringt mich bitte dorthin!", sourceObjective = "Begleitet Pao'ka Bergrausch aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Feuermähne.", completion = "Was!? Wenn ich gewusst hätte, dass Pao'ka Swiftmountain in der Gegend des Steilhangs herumschnüffeln wollte, hätte ich ihn an ein Totem gekettet! Sein Vater hat ihm nur ungern gestattet, mich nach Tausend Nadeln zu begleiten. Wir kamen hierher, um die verschiedenen Kreaturen zu studieren, die dieses wunderschöne Land bewohnen.\n\nIch weiß es zu schätzen, dass Ihr Pao'ka geholfen habt. Hoffentlich wiegt dies hier alle Unannehmlichkeiten wieder auf, die Ihr dafür in Kauf genommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4771] = { id = 4771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerungstrickfalle", description = "Ich habe die Dämmerungstrickfalle in den Behälter gelegt, den Ihr uns gebracht habt, denjenigen, in dem sich die Dracheneier befanden. Euer Auftrag besteht darin, sie tief nach Scholomance hineinzubringen.\n\nDer untote Magier Vectus führt ein Team von Gelehrten der Geißel an... legt die Dämmerungstrickfalle in ihre Kammer, genannt der \"Vorführraum\". Sie wird dann mit den dort gefundenen Untoten reagieren und sie mit ein wenig Glück vernichten.\n\nDanach sollte es kein Problem sein, Vectus zu besiegen. Nicht wahr?", sourceObjective = "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Moppelzink zurück.", completion = "Ihr habt es geschafft! Vectus ist besiegt! Und die Dämmerungstrickfalle... hat sie funktioniert?\n\nHm... vielleicht war mein Gerät nicht der Erfolg, den ich mir erhofft hatte, aber ich bin froh, dass Ihr die Sache trotzdem bewerkstelligen konntet. Gut gemacht, {name}!\n\nDie Argentumdämmerung und die guten Menschen von Azeroth sind in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[4781] = { id = 4781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Eure nächste Aufgabe ist so einfach wie die erste, allerdings werdet Ihr jetzt Hilfe benötigen.\n\nIch möchte einen Umhang besticken und benötige dazu Goldfaden, allerdings ist dieses Garn recht schwer zu beschaffen, und nur wenige wissen, wie man es herstellt. Glücklicherweise kennt jemand, der unsere Sache unterstützt, dieses Geheimnis und ist gewillt, uns zu helfen.\n\nBringt Xizk Gutstich in Beutebucht einen Goldbarren. Er ist ein Schneidermeister und wird mit Freuden das Garn für Euch spinnen. Goldbarren könnt Ihr von geschickten Minenarbeitern einschmelzen lassen. Bittet einfach einen Minenarbeiter um Hilfe.", sourceObjective = "Bringt Xizk Gutstich im Schlingendorntal einen Goldbarren.", progress = "Goldbarren, ja... ja. Bringt mir einen, dann sehen wir, ob ich nicht ein bisschen Garn für Euch spinnen kann. Bis dahin schlage ich vor, dass Ihr Euch zunächst darauf konzentriert, etwas mächtiger zu werden. Die schwersten Aufgaben liegen immer noch vor Euch. Und glaubt mir... Ihr werdet Euch irgendwann wünschen, besser vorbereitet zu sein, so mächtig Ihr Euch momentan auch fühlen möget.", completion = "Perfekt, {name}. Ich bin froh, dass Ihr so schnell einen Minenarbeiter gefunden habt, der Euch helfen konnte. Oder habt Ihr das etwa selbst erledigt? Auf jeden Fall habt Ihr Eure Sache gut gemacht. Das hier eignet sich perfekt, um daraus Garn zu machen.\n\nEs wird jedoch eine Weile dauern, um es zu spinnen, daher solltet Ihr später wiederkommen. Um genau zu sein: Ich muss es einer Prinzessin schicken, die wir in einem Turm eingesperrt haben und deren einzige Aufgabe es ist, Goldfäden zu spinnen ... Nein, wirklich. Das ist mein Ernst ... na gut, ich habe geflunkert.", sourceObjectiveStatus = "unverified-source-field" }
quests[4782] = { id = 4782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Kehrt zu Menara zurück und sagt Ihr, dass es eine Weile dauern wird, aber ich werde auf jeden Fall auf sie... und Euch zurückkommen. Sagt Ihr, dass Ihr zunächst noch die restlichen Komponenten zusammentragen müsst - bis dahin sollte ich das Garn fertig haben. Ihr könnt dann wieder herkommen und es mitnehmen.\n\nViel Glück, {name}. Oh, und grüßt Strahad von mir, wenn Ihr schon mal dort seid. Der alte Zausel... hat doch wirklich kaum einen Steinwurf von Ratschet einen Turm errichtet... verrückt.", sourceObjective = "Kehrt zu Menara Leerbringer im Brachland zurück.", completion = "Gut, Ihr seid zurückgekehrt, {name}. Und wo ist das Garn? Meine Fäden?\n\nAch so, ich verstehe. Da kann man nichts machen. Der Goblin und sein Bruder haben uns bisher noch nie im Stich gelassen - es ist wohl entschuldbar, dass er nicht alles stehen und liegen ließ, um sich sofort an die Arbeit zu machen. Na gut ... es gibt noch andere Dinge, um die wir uns in der Zwischenzeit kümmern können.\n\nSeid Ihr bereit für den nächsten Schritt?", sourceObjectiveStatus = "unverified-source-field" }
quests[4783] = { id = 4783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Die nächsten Komponenten findet Ihr in Desolace, weit westlich des Brachlandes und sogar des Steinkrallengebirges.\n\nNach der Teilung herrscht dort noch immer das reine Chaos. Sowohl Eure Kraft als auch Eure Schlauheit werden dort auf die Probe gestellt werden - Ihr werdet Euch Kreaturen voller Hass und sogar der Brennenden Legion stellen müssen.\n\nBringt mir etwas Blut von den Satyrn der Zornsäer im Nordosten. Und dann bringt mir noch einen geringen Höllenstein von den geringen Höllenbestien beim Zirkel der Mannoroc.\n\nWir brauchen beides, um daraus eine Robe für Euch zu fertigen.", sourceObjective = "Bringt Menara Leerbringer im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein.", progress = "Desolace ist nicht gerade ein freundlicher Ort: Naga, Riesen, Satyrn, die Brennende Legion... all das und sich gegenseitig bekämpfende Zentaurenklans machen das Land äußerst gefährlich, wenn Ihr Euch nicht vorseht.\n\nWie ich schon sagte, wird das alles nicht nur Eure Kraft und Schlauheit auf die Probe stellen, sondern auch Eure Geduld. Seid immer auf der Hut in dieser Gegend, {name}.", completion = "Ausgezeichnet, {name}. Das ist perfekt. Ich werde jetzt alles vorbereiten, während Ihr Euch auf die Suche nach den beiden letzten Komponenten macht. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[4784] = { id = 4784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Ich brauche jetzt nur noch drei Dinge, {name}, dann kann ich Eure Robe fertig stellen.\n\nZuerst brauche ich das feine Goldgarn, das Xizk für Euch gesponnen hat. Kehrt zu ihm nach Beutebucht zurück und holt es.\n\nAls Zweites brauche ich ein paar glimmende Kohlen von den Feuerelementaren im Arathihochland. Wenn ich mich recht erinnere, leben sie im Westen in der Nähe des Thoradinswalls.\n\nAls Letztes benötige ich dann noch einen von Euch geschaffenen Seelensplitter.\n\nKommt hierher zum Turm zurück, sobald Ihr alle Komponenten habt, dann stelle ich Eure Robe fertig.", sourceObjective = "Bringt Menara Leerbringer im Brachland feinen Goldfaden, 2 glimmende Kohlen und einen Seelensplitter.", progress = "Bald ist es so weit, {name}. Das verspreche ich Euch. Die Robe wird Euren Ansprüchen mehr als gerecht werden und Euch sicherlich gegenüber Euren Feinden einen großen Vorteil verschaffen.", completion = "Exzellent, {name}! Alle Komponenten sind da und wir sind bereit.\n\nIhr werdet höchst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[4785] = { id = 4785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feiner Goldfaden", sourceObjective = "Bitte sehr, {name}. Und bitte richtet doch Menara Grüße von uns aus.\n\nWir erwarten große Dinge von Euch. Wenn die Legion in die Knie gezwungen ist, wird man bestimmt Euren Namen rufen und Eure Kraft preisen. Ich kann es kaum erwarten!", sourceObjectiveStatus = "unverified-source-field" }
quests[4786] = { id = 4786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertiggestellte Robe", description = "Jetzt schneidere ich die Robe für Euch. Es dauert nur einen Augenblick. Geht nicht weit fort, ja?", sourceObjective = "Wartet, bis Menara Leerbringer Eure Robe fertiggestellt hat, und sprecht dann noch einmal mit ihr.", completion = "Es ist vollbracht, {name}. Hier, bitte sehr. Tragt sie mit Stolz.\n\nIhr habt hart dafür gearbeitet und ich sehe große Taten in Eurer Zukunft. Denkt daran: Um sich der Verderbnis zu erwehren, die unseren Weg begleitet, bedarf es eines starken Willens und großer, innerer Stärke. Solange Ihr Herr Eures Willens seid, wird Euch großer Erfolg beschieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[4787] = { id = 4787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das uralte Ei", description = "Mosh'arus Prophezeiung spricht von einem uralten Ei. Es ist ein Relikt aus einer Zeit, als die Trolle noch über riesige Reiche herrschten, und es hat die Kraft, die Essenz von Hakkar zu binden. Möglicherweise ist es das einzige Mittel, um unsere Welt vor diesem Bösen zu schützen.\n\nBringt mir das uralte Ei, {name}. Man sagt, dass es tief verborgen in Jintha'Alor im Hinterland liegt, in einer Höhle hinter dem Amphitheater am obersten Punkt der Stadt.", sourceObjective = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", progress = "Habt Ihr das uralte Ei? Ich spüre, wie sich große Mächte regen, und ich fürchte, dass die Zeit knapp wird.", completion = "Ah, Ihr habt das Ei! Ich verneige mich vor Euch, {name}. An Eure Kraft und Euren Mut wird man sich noch lang erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[4788] = { id = 4788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Schrifttafeln", description = "Während ich die dritte und vierte Schrifttafel von Mosh'aru überprüfe, müsst ihr die fünfte und sechste finden! Es wird nicht einfach sein, da sie in den Händen der Trolle des Gluthauerstamms auf der Schwarzfelsspitze sind. Die Spitze ist ein dunkler Berg aus Feuer zwischen der brennenden Steppe und der sengenden Schlucht.\n\nViel Glück, {name}. Die Schwarzfelsspitze ist kein Ort für anständige Leute...", sourceObjective = "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", progress = "Wart Ihr bei der Spitze, {name}? Habt Ihr die fünfte und sechste Schrifttafel?", completion = "Unglaublich! Ihr habt sie gefunden! Ihr seid ein wahrer Held, {name}!\n\nDas ist eine gute Sache, denn ich habe die Schrifttafeln gelesen, die Ihr mir zuvor gebracht habt, und nach dem, was ich herausgefunden habe... tja, da werden wir wohl einen Helden brauchen, der aufhält, was kommt...", sourceObjectiveStatus = "unverified-source-field" }
